import { get } from 'lodash'
import { formatMoney } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { PROPERTY_LANG } from '../../../Property/lang'
import TransactionInfoCard from '../TransactionInfoCard'
import { propertyOwnershipMap } from '../../../../CommonContainer/PropertySummaryPage/helpers'
import { formatDate } from '../../../../../helpers/formatDate'

function PropertyInsuredInfo (props) {
  const { policy } = props

  const renderInsuredData = () => {
    const policyDetail = policy?.policy_detail
    const propertyBreakup = policy?.policy_detail?.property_data
    return {
      heading: `${LANG_STRINGS.insuredObject}`,
      items: [
        {
          head: PROPERTY_LANG.province,
          value: get(policyDetail, 'province_name', '')
        },
        {
          head: PROPERTY_LANG.city,
          value: get(policyDetail, 'city_name', '')
        },
        {
          head: PROPERTY_LANG.postalCode,
          value: get(policyDetail, 'postal_code', '')
        },
        {
          head: PROPERTY_LANG.insuredObjectLocation,
          value: get(policyDetail, 'location', '')
        },
        {
          head: PROPERTY_LANG.buildingCategory,
          value: get(policyDetail, 'property_data.occupation_data.occupation_name_mitra', '')
        },
        {
          head: PROPERTY_LANG.buildingUse,
          value: get(policyDetail, 'property_data.occupation_data.occupation_desc_mitra', '')
        },
        {
          head: PROPERTY_LANG.noOfFloor,
          value: get(policyDetail, 'property_data.no_of_floor', '')
        },
        ...(policyDetail?.questionnaire?.map((q) => ({
          head: q.question,
          value: q.value ? 'Iya' : 'Tidak'
        })) || []),
        {
          head: PROPERTY_LANG.propertyOwnership,
          value: propertyOwnershipMap[policyDetail?.customer_data?.type] || ''
        },
        {
          head: PROPERTY_LANG.ownerName,
          value:get(policyDetail, 'customer_data.name', '')
        },
        {
          head: PROPERTY_LANG.buildingValue,
          value: formatMoney(get(propertyBreakup, 'building_value', 0), 0)
        },
        {
          head: PROPERTY_LANG.valueOfBuildingContent,
          value: formatMoney(get(propertyBreakup, 'building_content_value', 0), 0)
        },
        {
          head: PROPERTY_LANG.machineValue,
          value: formatMoney(get(propertyBreakup, 'machine_value', 0), 0)
        },
        {
          head: PROPERTY_LANG.equipmentValue,
          value: formatMoney(get(propertyBreakup, 'equipment_value', 0), 0)
        },
        {
          head: PROPERTY_LANG.stockValue,
          value: formatMoney(get(propertyBreakup, 'stock_value', 0), 0)
        },
        {
          head: PROPERTY_LANG.totalSumInsured,
          value: formatMoney(get(policy, 'total_sum_insured', 0), 0)
        },
        {
          head: LANG_STRINGS.policyStartDate,
          value: formatDate(get(policyDetail, 'start_date'), 'DD/MM/YYYY')
        },
        {
          head: LANG_STRINGS.policyEndDate,
          value: formatDate(get(policyDetail, 'end_date'), 'DD/MM/YYYY')
        }
      ]
    }
  }

  return (
    <TransactionInfoCard
      data={renderInsuredData()}
      className={!get(policy, 'policy_detail.property_address', '') && 'border-red'}
    />
  )
}

export default PropertyInsuredInfo
