import { get } from 'lodash'
import { LANG_STRINGS } from '../../../../../lang'
import { PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'
import { genderMap, maritalStatusMap } from '../../../../../containers/CommonContainer/PropertySummaryPage/helpers'
import TransactionInfoCard from '../TransactionInfoCard'
import { formatDate } from '../../../../../helpers/formatDate'
import { PROPERTY_LANG } from '../../../Property/lang'

function CustomerData (props) {
  const { policy } = props
  const customerData = policy.customer_data || {}
  const productCode = get(policy, 'policy_detail.product_code', '')

  const renderCustomerData = () => {
    return {
      heading: `${LANG_STRINGS.customerData}`,
      items: [
        {
          head: LANG_STRINGS.photoKTP,
          value: get(policy, 'policy_detail.ktp_url', ''),
          type: 'img'
        },
        {
          head: LANG_STRINGS.enterNumberAsInKtp,
          value: get(policy, 'policy_detail.ktp_no', '')
        },
        {
          head: LANG_STRINGS.enterNameAsInKtp,
          value: get(customerData, 'name', '')
        },
        {
          head: LANG_STRINGS.customerPhone,
          value: get(customerData, 'mobile_no', '')
        },
        {
          head: LANG_STRINGS.emailAddress,
          value: get(customerData, 'email', '')
        },
        {
          head: LANG_STRINGS.province,
          value: get(customerData, 'customer_address.province_name', '')
        },
        {
          head: LANG_STRINGS.city,
          value: get(customerData, 'customer_address.city_name', '')
        },
        {
          head: LANG_STRINGS.postalCode,
          value: get(customerData, 'customer_address.postal_code', '')
        },
        {
          head: LANG_STRINGS.addressDetail,
          value: get(customerData, 'customer_address.address', ''),
          newline: true
        }
      ]
    }
  }

  const renderCustomerDataProperty = () => {
    const isIndividualCustomer = customerData?.type === 'individual'
    const isCorporateCustomer = customerData?.type === 'corporate'
    return {
      heading: LANG_STRINGS.policyHolderData,
      items: [
        ...(isIndividualCustomer ? [
          {
            head: LANG_STRINGS.photoKTP,
            value: get(customerData, 'ktp_url', ''),
            type: 'img'
          },
          {
            head: LANG_STRINGS.ktpKitasNumber,
            value: get(customerData, 'ktp_no', '')
          },
          {
            head: LANG_STRINGS.ktpKitasName,
            value: get(customerData, 'name', '')
          },
          {
            head: LANG_STRINGS.placeOfBirth,
            value: get(customerData, 'birth_place', '')
            
          },
          {
            head: LANG_STRINGS.dateOfBirth,
            value: formatDate(get(customerData, 'birth_date'), 'DD/MM/YYYY')
          },
          {
            head: LANG_STRINGS.gender,
            value: genderMap[customerData?.gender] || ''
          },
          {
            head: LANG_STRINGS.maritalStatus,
            value: maritalStatusMap[customerData?.marital_status]
          },
          {
            head: LANG_STRINGS.phoneNumber,
            value: get(customerData, 'mobile_no', '')
          },
          {
            head: LANG_STRINGS.email,
            value: get(customerData, 'email', '')
          },
        ] : []),
        ...(isCorporateCustomer ? [
          {
            head: PROPERTY_LANG.corporateNpwpPhoto,
            value: get(customerData, 'corporate_data.npwp_url', ''),
            type: 'img'
          },
          {
            head: PROPERTY_LANG.corporateNpwpNumber,
            value: get(customerData, 'corporate_data.npwp_no', '')
          },
          {
            head: PROPERTY_LANG.corporateName,
            value: get(customerData, 'corporate_data.name', '')
          },
          {
            head: PROPERTY_LANG.corporateType,
            value: get(customerData, 'corporate_data.corporate_type_data.mitra_name', '')
          },
          {
            head: PROPERTY_LANG.economicActivity,
            value: get(customerData, 'corporate_data.economic_activity_data.mitra_name', '')
          },
          {
            head: PROPERTY_LANG.foundingDate,
            value: formatDate(get(customerData, 'corporate_data.founding_date'), 'DD/MM/YYYY')
          },
          {
            head: PROPERTY_LANG.countryOfOrigin,
            value: get(customerData, 'corporate_data.country_of_origin', '')
          },
          {
            head: PROPERTY_LANG.picName,
            value: get(customerData, 'corporate_data.pic_name', '')
          },
          {
            head: PROPERTY_LANG.picPhoneNumber,
            value: get(customerData, 'corporate_data.pic_mobile_no', '')
          },
          {
            head: PROPERTY_LANG.picEmail,
            value: get(customerData, 'corporate_data.pic_email', '')
          },
        ] : []),
        {
          head: LANG_STRINGS.province,
          value: get(customerData, 'customer_address.province_name', '')
        },
        {
          head: LANG_STRINGS.city,
          value: get(customerData, 'customer_address.city_name', '')
        },
        {
          head: LANG_STRINGS.postalCode,
          value: get(customerData, 'customer_address.postal_code', '')
        },
        {
          head: LANG_STRINGS.address,
          value: get(customerData, 'customer_address.address', ''),
          newline: true
        }
      ]
    }
  }

  switch (productCode) {
    case PROPERTY_PROTECTION:
      return <TransactionInfoCard data={renderCustomerDataProperty()} />
    default:
      return <TransactionInfoCard data={renderCustomerData()} />
  }
}

export default CustomerData
