import { useEffect, useState, useRef, useCallback, useMemo } from 'react'
import { connect } from 'react-redux'
import { NotificationManager } from 'react-notifications'
import { get, isEmpty } from 'lodash'
import moment from 'moment'
import { useResetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../components/index.js'
import {
  OFFLINE_PACKAGE_CODE,
  HEALTH_FULL_PROTECTION,
  MANUAL_ORDER,
  PROPERTY_PROTECTION,
  MARINE_CARGO,
  OFFLINE_CAR_PROTECTION_TLO,
  FLEET_POLICY,
  CAR_PROTECTION,
  TRAVEL_PROTECTION,
  EXTENDED_WARRANTY_PROTECTION,
  OFFLINE_PROTECTION,
} from '../../../../../constants/pkgCode.js'
import { LANG_STRINGS } from '../../../../../lang/index.js'
import policyActions from '../../../../../redux/policy/action.js'
import MVTransactionDetail from '../MVTransactionDetail/index.js'
import TravelTransactionDetail from '../TravelTransactionDetail/index.js'
import ExtendedWarrantyTransactionDetail from '../ExtendedWarrantyTransactionDetail/index.js'
import OfflineTransactionDetails from '../MVTransactionDetail/mvPre.js'
import PropertyTransactionDetail from '../PropertyTransactionDetail/index.js'
import DynamicTransactionDetail from '../../../DynamicTransactionDetail/index.js'
import { sharingViaWhatsApp } from '../../../../../helpers/sharingWA.js'
import { copySharingData, isIos } from '../../../../../helpers/utility.js'
import { downloadFileInIos } from '../../../../../bridges/iOS.js'
import { ANDROID_BRIDGE } from '../../../../../bridges/android.js'
import { downloadFile } from '../../../../../methods/file.js'
import { paymentStatusBahasa } from '../../../../../helpers/data.js'
import { APP_HOST } from '../../../../../configs/url.js'

import ConfirmationModal from '../../../../../components/ConfirmationModal/index.js'
import { getSharingMsgForProduct } from '../../../../../helpers/getPackageBody.js'
import {
  getFromLocalStorageData,
  removeFromLocalStorageData,
} from '../../../../../helpers/localstorage.js'
import { TRANSACTION_EDIT_SUCCESS } from '../../../../../constants/cookies.js'
import ShowSnackbar from '../../../../../components/ShowNotification/index.js'
import MarineCargoTransactionDetail from '../MarineCargoTransactionDetail/index.js'
// import HealthProtectionTransaction from '../HealthProtectionTransaction/index.js'
import { PolicyContextProvider } from '../../context/index.js'
import OfflineToOnlineTransactionDetail from '../OfflineToOnlineTransacctionDetail/index.js'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext/index.js'
import { useGetPartnerToken } from '../../../../../state/globalState/hooks/useGlobalContext.js'
import { PARTNER_CODE } from '../../../../../constants/appConstants.js'

const { getApplicationDetail, resetPolicyStore, getDownloadPdfRequest } = policyActions

function TransactionDetail(props) {
  const {
    match,
    applicationDetailLoading,
    pdfDownloadLoading,
    getDownloadPdfRequest,
    policyPdfStatus,
    policyPdfData,
    pdfFileDownloadError,
    getApplicationDetail,
    applicationDetail = {},
    location,
    agentPayingLoading,
    resetPolicyStore,
    history,
  } = props
  const [modalState, setModalState] = useState({})
  const sharePdfViaWhatsApp = useRef(false)
  const [{ isGuardianAgentLogin }] = useGlobalContextValue()
  const policyId = get(match, 'params.policyId', '') || get(location, 'state.id', '')
  const policyType = get(location, 'state.policyType', '')
  const hideBtnState = useRef([
    'PAYMENT_FAILED',
    'PAID',
    'EXPIRED',
    'POLICY_CREATED',
    'POLICY_CREATION_FAILED',
    'PROVISIONAL_FAILED',
    'APPLICATION_CANCELLED',
    'VERIFICATION_PENDING',
    'VERIFICATION_FAILED',
    'APPLICATION_INVALID',
  ])

  const { resetError } = useResetError()
  const [{ getPartnerTokenData = {} }, getPartnerTokenRequest] = useGetPartnerToken()
  const [showLoader, setShowLoader] = useState(false)
  const [{ getPartnerTokenStatus = '', updatePolicyStartDateStatus }, dispatchError] =
    useErrorContextValue()

  useEffect(() => {
    getApplicationDetail({ policyId, includeInsuranceDetail: true })
    if (getFromLocalStorageData(TRANSACTION_EDIT_SUCCESS) === 'success') {
      removeFromLocalStorageData(TRANSACTION_EDIT_SUCCESS)
      ShowSnackbar.success({ text: LANG_STRINGS.transactionEditSuccessful })
    }
    return () => {
      // empty the transaction detail
      resetPolicyStore(['applicationDetail'])
    }
  }, [getApplicationDetail, policyId, resetPolicyStore])

  const shareOnWhatsApp = useCallback(
    (pdfUrl) => {
      let isOfflinePolicy = false
      if (get(applicationDetail, 'product.package.code', '') === OFFLINE_PACKAGE_CODE) {
        isOfflinePolicy = true
      }
      let extraData = `Rincian transaksi Anda untuk: ${isOfflinePolicy ? '' : get(applicationDetail, 'product.package.name', '')} ${get(applicationDetail, 'product.provider.name', '')}\n`
      extraData += `ID Transaksi: ${get(applicationDetail, 'application_no', '')}\n`
      extraData += `Nama Tertanggung: ${get(applicationDetail, 'customer_data.name', '')}\n`
      extraData += `Status pembayaran: ${paymentStatusBahasa(get(applicationDetail, 'payment_status', ''))}\n`
      extraData += `Status polis: ${get(applicationDetail, 'policy_status', '')}\n`
      extraData += `Tanggal transaksi: ${moment(get(applicationDetail, 'application_date', '')).format('DD MMMM YYYY')}\n`
      if (isOfflinePolicy) {
        const linkOfShare = `${APP_HOST}/customer/policy/${applicationDetail.id}/?source=payment_wa`
        extraData += `Link: ${linkOfShare}`
      } else {
        extraData += `Unduh file rincian disini: ${pdfUrl}`
      }

      sharingViaWhatsApp({ text: extraData })
    },
    [applicationDetail]
  )

  useEffect(() => {
    if (policyPdfStatus === 'success' && policyPdfData) {
      if (sharePdfViaWhatsApp.current) {
        sharePdfViaWhatsApp.current = false
        shareOnWhatsApp(policyPdfData.pdf_url)
      } else if (isIos()) {
        downloadFileInIos(policyPdfData.pdf_url, 'policy.pdf', () => {
          NotificationManager.success(LANG_STRINGS.fileDownloadedSuccessfully)
        })
      } else if (ANDROID_BRIDGE.downloadFileInAndroid) {
        ANDROID_BRIDGE.downloadFileInAndroid(policyPdfData.pdf_url, '')
        NotificationManager.success(LANG_STRINGS.fileDownloadedSuccessfully)
      } else {
        downloadFile(policyPdfData.pdf_url)
      }
      resetPolicyStore(['policyPdfStatus'])
    } else if (policyPdfStatus && pdfFileDownloadError) {
      NotificationManager.error(policyPdfStatus)
      resetPolicyStore(['policyPdfStatus'])
    }
  }, [
    policyPdfStatus,
    policyPdfData,
    pdfFileDownloadError,
    resetPolicyStore,
    applicationDetail,
    shareOnWhatsApp,
  ])

  useEffect(() => {
    const accessToken = getPartnerTokenData?.access_token
    if (getPartnerTokenStatus === 'success' && accessToken) {
      const policiesUrl = `${process.env.REACT_APP_CLAIM_PORTAL_URL}/agency/login/?app_token=${accessToken}&redirectTo=/policydetail/${policyId}`
      window.open(policiesUrl, '_self')
      setShowLoader(true)
      resetError(['getPartnerTokenStatus'])
    } else if (getPartnerTokenStatus) {
      ShowSnackbar.error({ text: getPartnerTokenStatus })
      resetError(['getPartnerTokenStatus'])
    }
  }, [
    getPartnerTokenStatus,
    dispatchError,
    getPartnerTokenData?.access_token,
    policyId,
    resetError,
  ])

  const handleToClaimPortal = useCallback(() => {
    getPartnerTokenRequest({ partner_code: PARTNER_CODE.POLICIESPANEL })
  }, [getPartnerTokenRequest])

  const renderThePage = () => {
    const productCode = get(applicationDetail, 'product.package.product.code', '')
    const version = get(applicationDetail, 'version', null)
    if (
      [FLEET_POLICY, MANUAL_ORDER].includes(
        get(applicationDetail, 'policy_detail.protection_case', '')
      )
    ) {
      return <OfflineToOnlineTransactionDetail policy={applicationDetail} policyType={policyType} />
    }
    switch (productCode) {
      case PROPERTY_PROTECTION:
        return <PropertyTransactionDetail policy={applicationDetail} history={history} />
      case MARINE_CARGO:
        return <MarineCargoTransactionDetail policy={applicationDetail} history={history} />
      // case HEALTH_FULL_PROTECTION:
      //   return <HealthProtectionTransaction policy={applicationDetail} history={history} />
      case OFFLINE_CAR_PROTECTION_TLO:
        return (
          <OfflineToOnlineTransactionDetail policy={applicationDetail} policyType={policyType} />
        )
      case TRAVEL_PROTECTION: {
        const isLegacyTravel = !version || version === 1
        if (isLegacyTravel) {
          return <TravelTransactionDetail policy={applicationDetail} product={TRAVEL_PROTECTION} />
        }
        return <DynamicTransactionDetail policyData={applicationDetail} />
      }
      case EXTENDED_WARRANTY_PROTECTION:
        return (
          <ExtendedWarrantyTransactionDetail
            policy={applicationDetail}
            product={EXTENDED_WARRANTY_PROTECTION}
          />
        )
      case CAR_PROTECTION:
        return <MVTransactionDetail policy={applicationDetail} />
      case OFFLINE_PROTECTION:
        return <OfflineTransactionDetails policy={applicationDetail} />
      default:
        return <DynamicTransactionDetail policyData={applicationDetail} />
    }
  }

  const handleWhatsAppShare = useCallback(() => {
    // here we are handle the whatsapp share the pdf file
    sharePdfViaWhatsApp.current = true
    if (get(applicationDetail, 'product.package.code', '') === OFFLINE_PACKAGE_CODE) {
      shareOnWhatsApp()
    } else {
      getDownloadPdfRequest(policyId)
    }
  }, [shareOnWhatsApp, getDownloadPdfRequest, policyId, applicationDetail, sharePdfViaWhatsApp])

  const handleConfirmationModal = useCallback(() => {
    const modalObj = {
      showConfirmationModal: !modalState.showConfirmationModal,
      confirmModalTitle: LANG_STRINGS.downloadDetailTransactions,
      confirmModalAgree: LANG_STRINGS.agree,
      isPdfConfirm: true,
      confirmModalText: LANG_STRINGS.doYouWantToDownloadDetails,
    }
    setModalState(modalObj)
  }, [setModalState, modalState])

  const handleDownloadPdf = () => {
    // this function download the pdf file
    getDownloadPdfRequest(policyId)
    if (modalState.showConfirmationModal) {
      handleConfirmationModal()
    }
  }

  const handleCopyLink = useCallback(() => {
    const shareMsg = getSharingMsgForProduct(get(applicationDetail, 'product.package.code', ''))
    const linkOfShare = `${APP_HOST}/customer/policy/${policyId}/?source=payment_copy`
    copySharingData(`${shareMsg}\n${linkOfShare}`)
  }, [policyId, applicationDetail])

  const handleToDocumentsPage = useCallback(() => {
    // open the documents screen
    history.push({
      pathname: `/transactions/${policyId}/details/documents`,
    })
  }, [policyId, history])

  const handleToCreateEndorsementPage = useCallback(() => {
    // open the documents screen
    history.push({
      pathname: `/create_endorsement/${policyId}`,
    })
  }, [policyId, history])

  const handleToInvoicePage = useCallback(() => {
    if (applicationDetail?.invoice_receipt_list?.length === 1) {
      const receiptUrl = applicationDetail?.invoice_receipt_url
      window.open(`${receiptUrl}`, '_blank')
    } else {
      history.push({
        pathname: `/agent/${policyId}/invoice/documents`,
      })
    }
  }, [applicationDetail, history, policyId])

  const handleChangePolicyData = useCallback(
    (path) => {
      history.push({
        pathname: path,
        state: {
          applicationDetail,
        },
      })
    },
    [history, applicationDetail]
  )

  const sideMenuMap = useMemo(() => {
    let showSideMenuIcon = true
    const showDownloadDocsBtn = ['ACTIVE', 'PROVISIONAL_ISSUED', 'CANCELLED', 'REJECTED'].includes(
      applicationDetail.policy_status
    )
    const isHidePDF = [MANUAL_ORDER, FLEET_POLICY].includes(
      applicationDetail?.policy_detail?.protection_case
    )
    if (hideBtnState.current.includes(get(applicationDetail, 'status', ''))) {
      showSideMenuIcon = false
    }

    let menuItems = [
      {
        head: LANG_STRINGS.shareViaWhatsAppNew,
        handleClick: handleWhatsAppShare,
      },
      { head: LANG_STRINGS.copyLinkNew, handleClick: handleCopyLink },
    ]

    if (!isHidePDF && get(applicationDetail, 'product.package.code', '') !== OFFLINE_PACKAGE_CODE) {
      menuItems.push({
        head: LANG_STRINGS.downloadDetailTransactionsNew,
        handleClick: handleConfirmationModal,
      })
    }
    const productCode = get(applicationDetail, 'product.package.product.code', '')

    if (showDownloadDocsBtn) {
      if (showSideMenuIcon) {
        menuItems.push({
          head: LANG_STRINGS.downLoadPolicyDocuments,
          handleClick: handleToDocumentsPage,
        })
      } else {
        showSideMenuIcon = true
        menuItems = [
          {
            head: LANG_STRINGS.downLoadPolicyDocuments,
            handleClick: handleToDocumentsPage,
          },
        ]
      }
    }
    if (applicationDetail?.invoice_receipt_list?.length > 0) {
      if (showSideMenuIcon) {
        menuItems.push({
          head: LANG_STRINGS.lookInvoice,
          handleClick: handleToInvoicePage,
        })
      } else {
        showSideMenuIcon = true
        menuItems = [
          {
            head: LANG_STRINGS.lookInvoice,
            handleClick: handleToInvoicePage,
          },
        ]
      }
    }
    if (
      (productCode === CAR_PROTECTION || productCode === TRAVEL_PROTECTION) &&
      ['ACTIVE', 'POLICY_CREATED'].includes(applicationDetail.policy_status) &&
      process.env.REACT_APP_SHOW_CLAIM === 'true'
    ) {
      menuItems.push({
        head: LANG_STRINGS.claim,
        handleClick: handleToClaimPortal,
      })
    }

    if (
      !get(applicationDetail, 'use_pay_later', false) &&
      (['INITIATED', 'APPLICATION_COMPLETED'].includes(get(applicationDetail, 'status', '')) ||
        get(applicationDetail, 'payment_status', '') === 'WAITING_FOR_PAYMENT') &&
      productCode !== MARINE_CARGO &&
      productCode !== HEALTH_FULL_PROTECTION
    ) {
      showSideMenuIcon = true
      if (!isGuardianAgentLogin) {
        menuItems.push({
          head: LANG_STRINGS.changePolicyData,
          handleClick: () => handleChangePolicyData(`/change/policy/data/${policyId}`),
        })
      }
      menuItems = [
        ...menuItems,
        {
          head: LANG_STRINGS.editAddonsData,
          handleClick: () => handleChangePolicyData(`/change/policy/addons/${policyId}`),
        },
      ]
    }

    if (
      !(productCode === TRAVEL_PROTECTION) &&
      ['ACTIVE', 'PROVISIONAL_ISSUED'].includes(get(applicationDetail, 'policy_status', '')) &&
      !get(applicationDetail, 'expired') &&
      process.env.REACT_APP_SHOW_ENDORSEMENT_REQ === 'true'
    ) {
      menuItems = [
        ...menuItems,
        {
          head: LANG_STRINGS.applyEndorsement,
          handleClick: handleToCreateEndorsementPage,
        },
      ]
    }
    return { menuItems, showSideMenuIcon }
  }, [
    applicationDetail,
    handleWhatsAppShare,
    handleCopyLink,
    handleConfirmationModal,
    handleToDocumentsPage,
    policyId,
    handleChangePolicyData,
    handleToInvoicePage,
    isGuardianAgentLogin,
    handleToClaimPortal,
    handleToCreateEndorsementPage,
  ])

  useEffect(() => {
    if (!updatePolicyStartDateStatus) return

    if (updatePolicyStartDateStatus === 'success') {
      getApplicationDetail({ policyId, includeInsuranceDetail: true })
    }
  }, [resetError, updatePolicyStartDateStatus])

  return (
    <PolicyContextProvider>
      <Container
        title={LANG_STRINGS.transaction}
        displayBackButton
        loader={applicationDetailLoading || pdfDownloadLoading || agentPayingLoading || showLoader}
        showSideMenuIcon={sideMenuMap.showSideMenuIcon}
        sideMenuItems={sideMenuMap.menuItems}
        hideBottomTabs
        onBackClick={() => history.push('/transactions')}
      >
        {!isEmpty(applicationDetail) && renderThePage()}

        <ConfirmationModal
          showModal={modalState.showConfirmationModal}
          onClose={handleConfirmationModal}
          agreeText={modalState.confirmModalAgree}
          confirmText={modalState.confirmModalText}
          modelTitle={modalState.confirmModalTitle}
          hideClose={!modalState.isPdfConfirm}
          onAgree={modalState.isPdfConfirm ? () => handleDownloadPdf() : handleConfirmationModal}
        />
      </Container>
    </PolicyContextProvider>
  )
}

export default connect(
  (state) => ({
    applicationDetail: state.Policy.applicationDetail,
    applicationDetailLoading: state.Loading.GET_APPLICATION_DETAIL,
    policyPdfStatus: state.Policy.policyPdfStatus,
    policyPdfData: state.Policy.policyPdfData,
    pdfFileDownloadError: state.Error.GET_DOWNLOAD_PDF,
    pdfDownloadLoading: state.Loading.GET_DOWNLOAD_PDF,
    agentPayingLoading: state.Loading.AGENT_PAYING,
  }),
  {
    getDownloadPdfRequest,
    getApplicationDetail,
    resetPolicyStore,
  }
)(TransactionDetail)
