import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { ShareQuotationStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../lang/index'
import { Button, CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { RequiredStar } from '../../../../../commonStyle/index.style'
import DynamicForm from '../../../../../components/DynamicForm'
import { getShareQuotationWithCustomer } from '../../constants'
import { useCallback, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'

function ShareQuotation ({ preFilledData = {}, show, onClose, onSend = () => {}, loader }) {
  const formRef = useRef()
  const [isBtnDisabled, setIsBtnDisabled] = useState(true)

  const handleCustomerForm = useCallback((...restData) => {
    // manage change data here
    setIsBtnDisabled(false)
  }, [])

  const handleSendQuote = useCallback(() => {
    // submit the quote to customer
    const data = formRef.current.validateFormValues()
    if (data) {
      onSend(data)
    }
  }, [onSend])

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title={LANG_STRINGS.share}
      zIndex={4}
      showHeader
    >
      <ShareQuotationStyle>
        <CircularLoader isLoading={loader}>
          <CustomText
            size='1em'
            color={AgentColorPallette.blackGrey}
            bottom='0.4rem'
          >
            {LANG_STRINGS.shareThisWithYourCustomer}
          </CustomText>
          <CustomText
            size='0.8em'
            weight={700}
            color={AgentColorPallette.blackGrey}
          >
            <RequiredStar
              size='1.6em'
              color={AgentColorPallette.maroonRed}
              verticalAlign='middle'
            >
              *
            </RequiredStar>&nbsp;&nbsp;{LANG_STRINGS.columnsMustBeFilled}
          </CustomText>
          <DynamicForm
            form={getShareQuotationWithCustomer(preFilledData)}
            onChange={handleCustomerForm}
            ref={formRef}
          />
          <Button
            onClick={handleSendQuote}
          >
            {LANG_STRINGS.send}
          </Button>
        </CircularLoader>
      </ShareQuotationStyle>
    </BottomActionSheet>
  )
}

export default ShareQuotation
