import QuoteSection from '../QuoteSections'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { useMemo, useCallback } from 'react'
import VehiclePhotSection from '../VehiclePhotoSection'
import { mapDamagePhotos } from '../../../MVPolicyVehicleForm/constants'

function VehicleDocumentAndDetails ({ policy, className, onEditClick, isPolicyDetail }) {
  const detailObj = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.chassisNumber,
        value: policy?.chasis_number
      },
      {
        title: LANG_STRINGS.machineNumber,
        value: policy?.machine_number
      },
      {
        title: LANG_STRINGS.transmission,
        value: policy?.transmission_type
      },
      {
        title: LANG_STRINGS.color,
        value: policy?.color
      }
    ]
  }, [policy])

  const vehicleModifications = useMemo(() => {
    return policy?.accessories?.map(accessory => ({
      title: accessory.name,
      type: 'img',
      value: accessory.img
    }))
  }, [policy])

  const vehicleDamage = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.congenitalDamagePhoto,
        value: mapDamagePhotos(policy?.damage_photos),
        type: 'img',
        isMultiple: true
      },
      {
        title: LANG_STRINGS.remarksSubmitted,
        value: policy?.damage_remarks
      }
    ]
  }, [policy])

  const handleEditClick = useCallback((section, subSection) => {
    onEditClick({
      section
    }, subSection, 'insured_object')
  }, [onEditClick])

  return (
    <>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.document}
          data={[
            {
              title: LANG_STRINGS.stnkPhoto,
              value: policy?.stnk_url,
              type: 'img'
            }
          ]}
          onEditClick={() => handleEditClick(LANG_STRINGS.document, 'vehicle_document')}
          isEdit={!isPolicyDetail}
        />
      </div>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.detailObject}
          data={detailObj}
          isEdit={!isPolicyDetail}
          onEditClick={
            () => handleEditClick(LANG_STRINGS.detailObject, 'vehicle_detail_object')
          }
        />
      </div>
      <VehiclePhotSection
        className={className}
        policy={policy}
        onEditClick={
          () => handleEditClick(LANG_STRINGS.vehiclePhoto, 'vehicle_photos')
        }
        isEdit={!isPolicyDetail}
      />
      {
        !!policy?.accessories?.length && (
          <div className={className}>
            <QuoteSection
              title={LANG_STRINGS.vehicleModificationPhotos}
              data={vehicleModifications}
              marginBtm={isPolicyDetail && policy?.damage_photos ? '' : '20px'}
              onEditClick={
                () => handleEditClick(LANG_STRINGS.vehicleModificationPhotos, 'vehicle_modification_photos')
              }
              isEdit={!isPolicyDetail}
            />
          </div>
        )
      }
      {
        (isPolicyDetail ? policy?.damage_photos : true) && (
          <div className={className}>
            <QuoteSection
              title={LANG_STRINGS.vehicleDamage}
              data={vehicleDamage}
              marginBtm='20%'
              onEditClick={
                () => handleEditClick(LANG_STRINGS.vehicleDamage, 'vehicle_damage')
              }
              isEdit={!isPolicyDetail}
            />
          </div>
        )
      }
    </>
  )
}

export default VehicleDocumentAndDetails
