import { useGetInstalmentDetails } from '../../state/hooks/usePolicyState'
import { useErrorContextValue, useLoaderContextValue, resetError, updateLoader } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { useEffect } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'
import InstalmentsInfo from '../InstalmentsInfo'

const InstalmentsInfoContainer = (props) => {
  const { policy } = props
  const [{ GET_INSTALMENT_DETAILS_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getInstalmentDetailsData }, getInstalmentDetailsRequest] = useGetInstalmentDetails()
  const [{ getInstalmentDetailsStatus = '', GET_INSTALMENT_DETAILS_ERROR }, dispatchError] = useErrorContextValue()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_INSTALMENT_DETAILS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (policy.id) {
      getInstalmentDetailsRequest({
        applicationId: policy.id
      })
    }
  }, [getInstalmentDetailsRequest, policy])

  useEffect(() => {
    if (GET_INSTALMENT_DETAILS_ERROR && getInstalmentDetailsStatus) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: getInstalmentDetailsStatus
        })
      }
      dispatchError(resetError({
        getInstalmentDetailsStatus: ''
      }))
    }
  }, [GET_INSTALMENT_DETAILS_ERROR, getInstalmentDetailsStatus, dispatchError])

  return (
    <CircularLoader isLoading={GET_INSTALMENT_DETAILS_LOADER}>
      <InstalmentsInfo instalmentsData={getInstalmentDetailsData} policy={policy} />
    </CircularLoader>
  )
}

export default InstalmentsInfoContainer
