import { useMemo } from 'react'
import { isDateBefore } from '../../../../../helpers/formatDate'

const PAYMENT_STATUS_ACTIVE = [
  'ACTIVE',
  'NO_PAYMENT_MADE',
  'WAITING_FOR_PAYMENT',
  'INSTALLMENT_IN_PROGRESS',
]
const POLICY_REJECT = ['REJECTED', 'CANCELLED']
const PAYMENT_COMPLETE = ['COMPLETED']

export const usePaymentStatus = (policy) => {
  const now = new Date()
  const paymentEndDate = new Date(policy?.payment_period?.end_date)

  // if payment_status is EXPIRED but payment end date is still in the future, allow user to re-generate payment
  const isPaymentActive =
    PAYMENT_STATUS_ACTIVE.includes(policy?.payment_status) ||
    isDateBefore(now.getTime(), paymentEndDate.getTime())

  const hasDoPayment = PAYMENT_COMPLETE.includes(policy?.payment_status)

  const isPolicyRejected = POLICY_REJECT.includes(policy?.policy_status)

  const isUsingPaylater = useMemo(() => {
    return (
      // to know if the product is allowed to use paylater
      policy?.pay_later_enabled &&
      // to know if the policy is already using paylater
      policy.use_pay_later
    )
  }, [policy])

  return { isPaymentActive, isUsingPaylater, hasDoPayment, isPolicyRejected }
}
