import get from 'lodash/get'
import { formatMoney, formatNumber } from '../../../../../../../helpers/utility'
import { MV_STAR, WALLET } from '../../../../../../../images'
import {
  StyleContainer,
  TrackerCommissionItem,
  TrackerItem,
  TrackerUpperSection,
  TrackerIcon,
  TrackerTitle,
  TrackerPointCommission,
  TrackerDateTitle,
  TrackerDateValue,
  TrackerDateItem,
  TrackerBottomSection,
} from './index.style'
import { formatDate } from '../../../../../../../helpers/formatDate'
import { getCommissionStyle } from './helpers'

function TrackerCommission({ trackerData }) {
  const commissionStyle = getCommissionStyle(get(trackerData, 'commission_status'))
  return (
    <StyleContainer>
      <TrackerUpperSection>
        <TrackerCommissionItem>
          <TrackerItem>
            <TrackerIcon src={WALLET} alt="Wallet Icon" />
            <TrackerTitle>Total Komisi</TrackerTitle>
          </TrackerItem>
          <TrackerItem>
            <TrackerTitle>Total Poin</TrackerTitle>
            <TrackerIcon src={MV_STAR} alt="Star Icon" />
          </TrackerItem>
        </TrackerCommissionItem>
        <TrackerCommissionItem>
          <TrackerPointCommission
            color={commissionStyle.color}
            textDecoration={commissionStyle.textDecoration}
          >
            {formatMoney(get(trackerData, 'agent_commission', 0), 'Rp')}
          </TrackerPointCommission>
          <TrackerPointCommission
            color={commissionStyle.color}
            textDecoration={commissionStyle.textDecoration}
          >
            {formatNumber(get(trackerData, 'agent_points', 0), { suffix: ' Poin' })}
          </TrackerPointCommission>
        </TrackerCommissionItem>
        <TrackerCommissionItem>
          <TrackerDateItem>
            <TrackerDateTitle>Diterima</TrackerDateTitle>
            <TrackerDateValue>
              {formatDate(get(trackerData, 'commission_received_at'), 'DD/MM/YYYY, HH:mm:ss') ??
                '-'}
            </TrackerDateValue>
          </TrackerDateItem>
          <TrackerDateItem>
            <TrackerDateTitle>Diterima</TrackerDateTitle>
            <TrackerDateValue>
              {formatDate(get(trackerData, 'points_received_at'), 'DD/MM/YYYY, HH:mm:ss') ?? '-'}
            </TrackerDateValue>
          </TrackerDateItem>
        </TrackerCommissionItem>
      </TrackerUpperSection>
      <TrackerBottomSection>
        <TrackerCommissionItem>
          <TrackerDateItem>
            <TrackerDateTitle>Tgl. Transaksi Diajukan</TrackerDateTitle>
            <TrackerDateValue>
              {formatDate(get(trackerData, 'transaction_date'), 'DD/MM/YYYY, HH:mm:ss') ?? '-'}
            </TrackerDateValue>
          </TrackerDateItem>
          <TrackerDateItem>
            <TrackerDateTitle>Tgl. Pembayaran Diterima</TrackerDateTitle>
            <TrackerDateValue>
              {formatDate(get(trackerData, 'payment_date'), 'DD/MM/YYYY, HH:mm:ss') ?? '-'}
            </TrackerDateValue>
          </TrackerDateItem>
        </TrackerCommissionItem>
      </TrackerBottomSection>
    </StyleContainer>
  )
}

export default TrackerCommission
