import QuoteSection from '../QuoteSections'
import { useMemo } from 'react'
import moment from 'moment'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { USAGE } from '../../../../../../../constants/appConstants'

function QuoteProtectionSection ({ policy = {}, className, isPolicyDetail }) {
  const specifications = useMemo(() => {
    const initialStartDate = policy?.start_date
    let startDate = ''
    let endDate = ''
    const period = parseInt(policy?.premium?.period) || 12
    if (initialStartDate) {
      startDate = moment(initialStartDate, 'YYYY-MM-DD').format('DD/MM/YYYY')
      endDate = moment(initialStartDate, 'YYYY-MM-DD').add(period, 'month').format('DD/MM/YYYY')
    }
    return [
      {
        title: LANG_STRINGS.benefit,
        value: policy?.product?.package?.code === 'car-protection-comprehensive' ? 'Komprehensif' : 'TLO & Komprehensif'
      },
      {
        title: LANG_STRINGS.vehicleUse,
        value: USAGE[policy?.usage]
      },
      {
        title: LANG_STRINGS.period,
        value: startDate && endDate ? `${startDate} - ${endDate}` : '12 Bulan'
      }
    ]
  }, [policy])

  return (
    <div className={className}>
      <QuoteSection
        data={specifications}
        title={LANG_STRINGS.insuranceSpecifications}
      />
    </div>
  )
}

export default QuoteProtectionSection
