import QuoteSection from '../QuoteSections'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { useMemo } from 'react'
import { getVehicleType } from '../../../../../../../helpers/data'
import { formatMoney } from '../../../../../../../helpers/utility'

function VehicleCriteria ({ policy = {}, className }) {
  const criteria = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.transportationType,
        value: getVehicleType(policy?.vehicle_type)
      },
      {
        title: LANG_STRINGS.productionYear,
        value: policy?.year
      },
      {
        title: LANG_STRINGS.brand,
        value: policy?.brand
      },
      {
        title: LANG_STRINGS.model,
        value: policy?.variant
      },
      {
        title: LANG_STRINGS.vehiclePrice,
        value: formatMoney(policy?.vehicle_sum_insured, 0)
      },
      {
        title: LANG_STRINGS.regionalCode,
        value: policy?.region_code
      },
      {
        title: LANG_STRINGS.vehicleNumber,
        value: policy?.vehicle_plate_no
      }
    ]
  }, [policy])

  return (
    <div className={className}>
      <QuoteSection
        data={criteria}
        title={LANG_STRINGS.vehicleCriteria}
        marginBtm={policy.accessories?.length ? '0' : '20%'}
      />
    </div>
  )
}

export default VehicleCriteria
