import { useState, useCallback, useEffect, useRef, useMemo } from 'react'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import PolicyPaymentInfo from '../../../../../../../components/PolicyPaymentInfo'
import CustomText from '../../../../../../../components/CustomText'
import Tabs from '../../../../../../../components/Tabs'
import { POLICY_TABS, POLICY_DETAILS_TAB } from './constants'
import { ExtendedWarrantyQuoteReviewStyle, CardBorderStyle, CardItemStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { useCompleteDraftQuote, useGetDraftQuoteDetails, useUpdateDiscount, useUpdateDraftQuote, useClaimsList } from '../../../../state/hooks/usePolicyState'
import { getMappedQuoteToPolicyData } from '../../../../helpers'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import CircularLoader from '../../../../../../../components/CircularLoader'
import EditMVPolicyQuote from '../../../EditMVPolicyQuoteBottomSheet'
import ShowSnackbar from '../../../../../../../components/ShowNotification/index'
import { BottomActionContainerStyle, Row } from '../../../../../../../commonStyle/index.style'
import { Button } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { CAR_PROTECTION, TRAVEL_PROTECTION, MV_QUOTE_STEPS_SECTIONS, EXTENDED_WARRANTY_PROTECTION } from '../../../../../../../constants/pkgCode'
import { useDraftPrevSteps } from '../../../../../../../state/commonState/hooks/useDraftPrevSteps'
import size from 'lodash/size'
import { gTagOnQuoteCreatedBy } from '../../../../../../../tagManager'
import { useGlobalContextValue } from '../../../../../../../contextProvider/GlobalContext/index'
import { QUOTE_CREATED_BY } from '../../../../../../../constants/appConstants'
import { useGetPkgDetail, useShareDraftQuoteToCustomer } from '../../../../../Packages/state/hooks/usePackages'
import { getPackagesReqBody, getExtraVehicleData } from '../../../../../../../helpers/getPackageBody'
import { extractValues, formatMoney } from '../../../../../../../helpers/utility'
import { PAYMENT_METHOD } from '../../../../../../../constants/payment'
import { coverageDetail, customerDetails, customerPhotos, insuranceDetailEw, TAP_EXTENDED_TABS, transactionDetailsEw, vehicleDetail, vehiclePhotos } from '../../../../../ExtendedWarranty/constant'
import UploadFileV3 from '../../../../../../../components/DynamicForm/components/UploadFileV3'
// import ShareQuotation from '../../../../../Packages/components/ShareQuotation'
import MVReviewTermsConditions from '../../../MVQuoteReview/components/MVReviewTermsConditions'
import ProductDetail from '../ProductDetail/index'

function ExtendedWarrantyQuoteReviewContainer ({
  policyData = {}, isPolicyDetail, height,
  isShowEditDiscount, top, onPaymentClick = () => {},
  isMVDraftDetail, isReviewQuote, productCode
}) {
  const that = useRef({
    tabsData: [
      ...(isPolicyDetail ? POLICY_DETAILS_TAB : []),
      ...POLICY_TABS
    ]
  })
  const [{ getPackageDetailData = {} }, getPkgDetailsReq] = useGetPkgDetail()
  const paymentInfoRef = useRef()
  // const [showShareSheet, setShowShareSheet] = useState(false)
  const [activeEwTab, setActiveEwTab] = useState(TAP_EXTENDED_TABS[0])
  const [showTerms, setShowTerms] = useState(false)
  const history = useHistory()
  const [showEditQuote, setShowEditQuote] = useState({
    editSection: '',
    show: false
  })
  const [claimDetails, setClaimDetails] = useState({
    claimId: null,
    claimStatus: null
  })
  const { draftQuoteId } = useParams()
  const [{ discount }, updateDiscount] = useUpdateDiscount()
  const [{
    DRAFT_QUOTATIONS_DETAILS_LOADER, GET_PACKAGE_DETAIL_LOADER,
    COMPLETE_DRAFT_QUOTE_LOADER, UPDATE_DRAFT_QUOTATION_LOADER,
    // SHARE_DRAFT_QUOTE_LOADER
  }] = useLoaderContextValue()
  const [{ getAgentDetailData, isGuardianAgentLogin }] = useGlobalContextValue()
  // const [, shareDraftQuoteReq] = useShareDraftQuoteToCustomer()
  const [{ draftQuotationsDetailsStatus, completeDraftQuoteStatus, completeDraftQuoteStatusCode, completeDraftQuoteErrorData, getClaimsListStatus, getPackageDetailStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [{ getClaimsListData }, getClaimsListRequest] = useClaimsList()
  const [{ completeDraftQuoteData }, completeDraftQuoteReq] = useCompleteDraftQuote()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [policy, setPolicy] = useState(() => {
    return draftQuotationsDetailsData.policy_details ? getMappedQuoteToPolicyData(draftQuotationsDetailsData.policy_details) : policyData
  })
  const isAllowedPaymentBtn = useMemo(() => {
    if (isMVDraftDetail) return true
    if (isPolicyDetail) {
      if (policy.policy_status === 'PENDING_DORMANT_COVERAGE' && productCode === EXTENDED_WARRANTY_PROTECTION) {
        return false
      }
      
      return (
        (!['PROVISIONAL_ISSUED', 'PENDING'].includes(policy.policy_status)) ||
        (['COMPLETED', 'PROOF_SUBMITTED'].includes(policy.payment_status))
      )
    }
    return false
  }, [policy, isPolicyDetail, isMVDraftDetail, productCode])

  const isHidePaymentBtn = useMemo(() => {
    if (isMVDraftDetail) return true
    if (isPolicyDetail) {
      return (
        (['COMPLETED', 'PROOF_SUBMITTED'].includes(policy.payment_status))
      )
    }
    return false
  }, [policy, isPolicyDetail, isMVDraftDetail])

  const savedDraftData = useRef({})
  const updateDraftTimer = useRef()
  const discountRef = useRef({
    pkgCallTimer: ''
  })
  const draftPrevSteps = useDraftPrevSteps()

  useEffect(() => {
    if (policy.application_no && (process.env.REACT_APP_SHOW_CLAIM === 'true')) {
      getClaimsListRequest({ applicationNo: policy.application_no })
    }
  }, [policy.application_no, getClaimsListRequest])

  useEffect(() => {
    if (!isPolicyDetail) {
      getDraftQuoteDetailsReq({
        draftQuoteId: draftQuoteId
      })
    }
  }, [getDraftQuoteDetailsReq, draftQuoteId, isPolicyDetail])

  useEffect(() => {
    if (draftQuotationsDetailsStatus === 'success' && draftQuotationsDetailsData?.policy_details) {
      if (isMVDraftDetail) {
        if (draftQuotationsDetailsData?.policy_application_id) {
          history.replace(`/transactions/${draftQuotationsDetailsData.policy_application_id}/details`)
          return
        }
        that.current.section = draftQuotationsDetailsData.section
        that.current.subSection = draftQuotationsDetailsData.sub_section
        const sectionData = MV_QUOTE_STEPS_SECTIONS[draftQuotationsDetailsData.section] || {}
        const tabsData = [...that.current.tabsData]
        that.current.tabsData = tabsData.filter(item => sectionData.tabsData[item.value])
      }
      setPolicy(getMappedQuoteToPolicyData(draftQuotationsDetailsData.policy_details))
      resetError(['draftQuotationsDetailsStatus'])
    }

    if (completeDraftQuoteStatus === 'success') {
      gTagOnQuoteCreatedBy(
        isGuardianAgentLogin ? QUOTE_CREATED_BY.PIC_SUBMITTED_QUOTE : QUOTE_CREATED_BY.SELF_SUBMITTED_QUOTE,
        getAgentDetailData.agent_code,
        CAR_PROTECTION
      )
      history.push(`/payment/car-protection/${completeDraftQuoteData.id}`)
      resetError(['completeDraftQuoteStatus'])
    } else if (completeDraftQuoteStatusCode === 500) {
      ShowSnackbar.error({
        text: extractValues(completeDraftQuoteStatus),
        visible: true
      })
      resetError(['completeDraftQuoteStatus', 'completeDraftQuoteErrorData', 'completeDraftQuoteStatusCode'])
    } else if (completeDraftQuoteErrorData) {
      ShowSnackbar.error({
        text: extractValues(completeDraftQuoteErrorData),
        visible: true
      })
      resetError(['completeDraftQuoteStatus', 'completeDraftQuoteErrorData'])
    }

    if (getClaimsListStatus === 'success' && size(getClaimsListData?.data)) {
      const [firstItem] = getClaimsListData?.data
      if (firstItem) {
        const { claim_id: claimId, status: claimStatus } = firstItem
        setClaimDetails({
          claimId,
          claimStatus
        })
      }
      resetError(['getClaimsListStatus'])
    }
  }, [
    draftQuotationsDetailsStatus, draftQuotationsDetailsData,
    history, completeDraftQuoteStatus, draftQuoteId, resetError,
    completeDraftQuoteData, getClaimsListData, isMVDraftDetail,
    getClaimsListStatus, isGuardianAgentLogin, getAgentDetailData, completeDraftQuoteErrorData, completeDraftQuoteStatusCode
  ])

  // useEffect(() => {
  //   if (shareDraftQuoteStatus === 'success') {
  //     setShowShareSheet(false)
  //     history.push(`/send/draft/quote/success/${draftQuoteId}`)
  //     resetError(['shareDraftQuoteStatus'])
  //   } else if (shareDraftQuoteStatus) {
  //     if (ShowSnackbar.error) {
  //       ShowSnackbar.error({
  //         visible: true,
  //         text: shareDraftQuoteStatus
  //       })
  //     }
  //     resetError(['sendQuotationStatus'])
  //   }
  // }, [shareDraftQuoteStatus, draftQuoteId, history, resetError])

  // const handleShowQuotationModal = useCallback(() => {
  //   setShowShareSheet(true)
  // }, [])
  
  // const handleSendQuote = useCallback(() => {
  //   const body = {
  //     customer_data: {
  //       ...policy?.customer_data
  //     },
  //     draft_id: draftQuoteId
  //   }
  //   shareDraftQuoteReq({
  //     body
  //   })
  // }, [
  //   shareDraftQuoteReq, draftQuoteId, policy
  // ])

  const convertDate = (timeStamp) => {
    const date = new Date(timeStamp)
    return new Intl.DateTimeFormat('en-UK', { day: 'numeric', month: 'short', year: 'numeric' }).format(date)
  }

  const convertTime = (timeStamp) => {
    const date = new Date(timeStamp)
    return new Intl.DateTimeFormat('en-UK', { hour: 'numeric', minute: 'numeric', second: 'numeric', hour12: false, }).format(date)
  }
  
  const formatValues = (value, label) => {
    switch (label) {
      case LANG_STRINGS.startProtection:
      case LANG_STRINGS.endProtection:
      case LANG_STRINGS.dateOfBirth:
      case LANG_STRINGS.orderDate:
      case LANG_STRINGS.paymentDate:
        return convertDate(value)
      case LANG_STRINGS.orderTime:
      case LANG_STRINGS.paymentTime:
        return convertTime(value)
      case LANG_STRINGS.paymentMethod:
        return PAYMENT_METHOD[value]
      case LANG_STRINGS.policyStatus:
        switch (value) {
          case 'ACTIVE':
          case 'POLICY_CREATED':
            return LANG_STRINGS.active
          case 'CANCELLED':
            return LANG_STRINGS.canceled
          case 'EXPIRED':
            return 'Berakhir'
          case 'REJECTED':
            return LANG_STRINGS.rejected
          default:
        }
        break
      case LANG_STRINGS.typeProtection:
        switch (value) {
          case 'individual':
            return 'Individu'
          case 'family':
            return 'Keluarga'
          default:
        }
        break
      case LANG_STRINGS.numberCovered:
        return `${value.adult + 1} Dewasa${value.kids > 0 ? `, ${value.kids} Anak` : ''}`
      case LANG_STRINGS.destination:
        return value.join(', ')
      case LANG_STRINGS.gender:
        return (value === 'male' ? LANG_STRINGS.male : LANG_STRINGS.female)
      default:
    }
  }

  const formatValuesEw = (value, label) => {
    switch (label) {
      case 'Nomor Plat':
        return value?.split(/[^0-9]/)[0]
      case 'Kode Belakang Plat':
        return value?.split(/[0-9]/)?.filter(Boolean)?.join('')
      case LANG_STRINGS.basicPremium:
      case LANG_STRINGS.adminFee:
      case LANG_STRINGS.stampDuty:
      case LANG_STRINGS.totalTransaction:
        return formatMoney((value), 0)
      default:
        return value
    }
  }

  const getNestedValue = (data, keys) => {
    let value = data
    keys.forEach(key => {
      value = value?.[key]
    })
    if (Array.isArray(value)) {
      return value.join(', ')
    }
    return value
  }
  
  const renderDetailCardEw = (title, data, list) => {
    return (
      <>
        {
          (title) &&
            <CustomText
              color={AgentColorPallette.black}
              weight={700}
              size='15px'
              bottom='12px'
              top='10px'
            >
              {title}
            </CustomText>
        }
        <div className='bg-white data-container'>
          {
            list?.map((item, index) => (
              <CardItemStyle
                border={(index + 1) !== list.length}
                key={index}
              >
                <CardBorderStyle
                  border={(index + 1) !== list.length}
                >
                  <Row
                    align='center'
                    justify='space-between'
                  >
                    <CustomText
                      color={AgentColorPallette.fontGrey}
                      size='12px'
                      weight={700}
                    >
                      {item.label}
                    </CustomText>
                    <CustomText
                      color={AgentColorPallette.regular}
                      size='13px'
                      weight={600}
                    >
                      {item.format ? formatValuesEw(item.value ? item.value : item.key ? data?.[item.key] : getNestedValue(data, item?.keys), item.label) : (item.value ? item.value : item.key ? data?.[item.key] : getNestedValue(data, item?.keys))}
                    </CustomText>
                  </Row>
                </CardBorderStyle>
              </CardItemStyle>
            ))
          }
        </div>
      </>
    )
  }
  const renderDetailCard = (title, data, list) => {
    return (
      <>
        {
          (title) &&
            <CustomText
              color={AgentColorPallette.black}
              weight={700}
              size='15px'
              bottom='12px'
              top='10px'
            >
              {title}
            </CustomText>
        }
        <div className='bg-white data-container'>
          {
            list?.map((item, index) => (
              <CardItemStyle
                border={(index + 1) !== list.length}
                key={index}
              >
                <CardBorderStyle
                  border={(index + 1) !== list.length}
                >
                  <Row
                    align='center'
                    justify='space-between'
                    gap={item.gap || null}
                  >
                    <CustomText
                      color={AgentColorPallette.fontGrey}
                      size='12px'
                      weight={700}
                    >
                      {item.label}
                    </CustomText>
                    <CustomText
                      color={AgentColorPallette.regular}
                      size='13px'
                      weight={600}
                      textAlign={item.align || 'left'}
                    >
                      {item.format ? formatValues(item.value ? item.value : item.key ? data?.[item.key] : getNestedValue(data, item?.keys), item.label) : (item.value ? item.value : item.key ? data?.[item.key] : getNestedValue(data, item?.keys))}
                    </CustomText>
                  </Row>
                </CardBorderStyle>
              </CardItemStyle>
            ))
          }
        </div>
      </>
    )
  }

  const renderDetailCardPhoto = (title, data, list) => {
    return (
      <>
        {
          (title) &&
            <CustomText
              color={AgentColorPallette.black}
              weight={700}
              size='15px'
              bottom='12px'
              top='10px'
            >
              {title}
            </CustomText>
        }
        <div className='bg-white data-container'>
          {
            list?.map((item, index) => (
              <CardItemStyle
                border={(index + 1) !== list.length}
                key={index}
              >
                <CardBorderStyle>
                  <Row
                    align='center'
                    justify='space-between'
                    gap={item.gap || null}
                  >
                    <CustomText
                      color={AgentColorPallette.fontGrey}
                      size='12px'
                      weight={700}
                    >
                      {item.label}
                    </CustomText>
                  </Row>
                  <UploadFileV3
                    height='200px'
                    disabled
                    defaultValue={item.key ? data?.[item.key] : getNestedValue(data, item?.keys)}
                  />
                </CardBorderStyle>
              </CardItemStyle>
            ))
          }
        </div>
      </>
    )
  }

  const handleEwTabClick = (selectedTab) => {
    setActiveEwTab(selectedTab)
  }

  const handleSaveDraft = useCallback((extraData = {}, timer) => {
    savedDraftData.current = {
      ...draftQuotationsDetailsData.policy_details,
      ...savedDraftData.current,
      ...extraData
    }
    if (updateDraftTimer.current) {
      clearTimeout(updateDraftTimer.current)
      updateDraftTimer.current = ''
    }
    if (extraData.package_data) {
      const pkgData = {
        ...extraData.package_data
      }
      delete pkgData.vehicle_type
      savedDraftData.current = {
        provider_branch: (pkgData?.provider_branch || pkgData?.provider?.headquarter_branch),
        ...savedDraftData.current,
        ...savedDraftData.current.addons_data,
        ...pkgData
      }
      delete savedDraftData.current.tnc
      delete savedDraftData.current.add_ons
      delete savedDraftData.current.premium_breakup
      delete savedDraftData.current.claims
      delete savedDraftData.current.benefit
      delete savedDraftData.current.common_deductible_content
    }
    updateDraftTimer.current = setTimeout(() => {
      updateDraftQuoteReq({
        body: {
          section: isReviewQuote ? 'mv_quote_summary' : that.current.section,
          sub_section: isReviewQuote ? 'mv_quote_summary' : that.current.subSection,
          data: savedDraftData.current
        },
        draftQuoteId
      })
    }, timer || 3000)
    // update the new values to local policy
    setPolicy(getMappedQuoteToPolicyData(savedDraftData.current))
  }, [updateDraftQuoteReq, draftQuoteId, draftQuotationsDetailsData, isReviewQuote])

  const handlePayment = useCallback((data) => {
    // handle the payment
    if (isPolicyDetail) {
      onPaymentClick({ discount, isDiscountChange: (discount !== undefined) })
      // history.push(`/payment/car-protection/${policyData.id}`)
      return
    }
    handleSaveDraft({ discount: paymentInfoRef?.current?.getDiscount() }, 1)
    setShowTerms(true)
  }, [isPolicyDetail, discount, onPaymentClick, handleSaveDraft])

  const handleWaitingPage = useCallback(() => {
    history.push(`/payment/status/paylater/${policyData?.id}`)
  }, [history, policyData])

  const handleNext = useCallback(() => {
    completeDraftQuoteReq({
      draftQuoteId
    })
  }, [draftQuoteId, completeDraftQuoteReq])

  const handleToPrevious = useCallback(() => {
    draftPrevSteps({
      section: draftQuotationsDetailsData.section,
      subSection: draftQuotationsDetailsData.sub_section,
      id: draftQuoteId
    })
  }, [draftQuoteId, draftPrevSteps, draftQuotationsDetailsData])

  useEffect(() => {
    if (getPackageDetailStatus === 'success' && discountRef.current.updateDiscount) {
      discountRef.current.updateDiscount = false
      handleSaveDraft({
        discount: discountRef.current.discount,
        package_data: getPackageDetailData
      }, 1)
      resetError(['getPackageDetailStatus'])
    }
  }, [getPackageDetailStatus, getPackageDetailData, handleSaveDraft, resetError])

  const handleDiscountChange = ({ discount }) => {
    // handle the discount changes

    if (isPolicyDetail) {
      updateDiscount(discount)
    } else {
      if (discountRef.current.pkgCallTimer) {
        clearTimeout(discountRef.current.pkgCallTimer)
      }
      discountRef.current.pkgCallTimer = setTimeout(() => {
        clearTimeout(discountRef.current.pkgCallTimer)
        discountRef.current.updateDiscount = true
        discountRef.current.discount = discount
        getPkgDetailsReq({
          body: {
            ...getPackagesReqBody(policy),
            ...getExtraVehicleData(policy),
            discount
          },
          packageCode: policy.provider_package_code
        })
      }, 600)
    }
  }

  return (
    <CircularLoader
      isLoading={
        DRAFT_QUOTATIONS_DETAILS_LOADER || GET_PACKAGE_DETAIL_LOADER ||
        COMPLETE_DRAFT_QUOTE_LOADER || UPDATE_DRAFT_QUOTATION_LOADER
      }
    >
      <ExtendedWarrantyQuoteReviewStyle
        isPolicyDetail={isPolicyDetail}
        height={height}
      >
        <ProductDetail
          policy={policy}
          claimDetails={claimDetails}
          isPaymentAllowed={!isAllowedPaymentBtn}
          // isMVDraftDetail={isMVDraftDetail}
          // onEndorsementDetails={handleEndorsementDetails}
        />
        <>
          <Tabs
            data={TAP_EXTENDED_TABS}
            defaultTab={activeEwTab}
            borderBottom='#333333'
            isSticky
            zIndex
            onClick={handleEwTabClick}
          />
          {
            activeEwTab.value === 'insurance' && (
              <div className='tab-section'>
                {renderDetailCard('Detail Asuransi', policy, insuranceDetailEw)}
                {renderDetailCard('Detail Perlindungan', policy, coverageDetail)}
                {/* {renderPacketCards(getDetailPackets(draftId), 'Detail Paket')} */}
              </div>
            )
          }
          {
            activeEwTab.value === 'insured' && (
              <div className='tab-section'>
                {renderDetailCardEw('Detail Kendaraan', policy, vehicleDetail)}
                {renderDetailCardPhoto('Daftar Dokumen', policy, vehiclePhotos)}
              </div>
            )
          }
          {                             
            activeEwTab.value === 'policy' && (
              <div className='tab-section'>
                {renderDetailCard('Pemegang Polis', policy , customerDetails)}
                {renderDetailCardPhoto('Daftar Dokumen', policy, customerPhotos)}
                {renderDetailCardEw('Detail Transaksi', policy , transactionDetailsEw)}
              </div>
            )                             
          }
        </>
        {
          isMVDraftDetail && (
            <BottomActionContainerStyle padding='0'>
              <div className='btn-wrapper'>
                <Button color={AgentColorPallette.darkCharcoal} onClick={handleToPrevious}>
                  {LANG_STRINGS.previousContinue}
                </Button>
              </div>
            </BottomActionContainerStyle>
          )
        }
        {
          !isHidePaymentBtn && !(productCode === TRAVEL_PROTECTION) && !(policy?.product_code === 'car-protection') && (
            <PolicyPaymentInfo
              policy={{
                ...policy,
                discount: (discount !== undefined ? discount : policy.discount)
              }}
              isPolicyDetail={isPolicyDetail}
              btnText={LANG_STRINGS.payment}
              discountPercent={policy?.product?.discount_percentage}
              maxDiscount={policy?.product?.max_discount}
              commission={policy?.agent_commission}
              onBuyClick={!isAllowedPaymentBtn ? handlePayment : handleWaitingPage}
              showDiscount={isShowEditDiscount || !isPolicyDetail}
              ref={paymentInfoRef}
              grey={isAllowedPaymentBtn}
              onSaveDraft={handleSaveDraft}
              discountLoader={GET_PACKAGE_DETAIL_LOADER}
              onDiscountChange={handleDiscountChange}
            />
          )
        }
        {/* {
          !isHidePaymentBtn && (policy?.product_code === 'car-protection') && (
            <>
            <PolicyPaymentInfo
              policy={{
                ...policy,
                discount: (discount !== undefined ? discount : policy.discount)
              }}
              isPolicyDetail={isPolicyDetail}
              btnText={LANG_STRINGS.payment}
              discountPercent={policy?.product?.discount_percentage}
              maxDiscount={policy?.product?.max_discount}
              commission={policy?.agent_commission}
              onBuyClick={!isAllowedPaymentBtn ? handlePayment : handleWaitingPage}
              onShareClick={handleShowQuotationModal}
              isShareBtn
              showDiscount={isShowEditDiscount || !isPolicyDetail}
              ref={paymentInfoRef}
              grey={isAllowedPaymentBtn}
              onSaveDraft={handleSaveDraft}
              discountLoader={GET_PACKAGE_DETAIL_LOADER}
              onDiscountChange={handleDiscountChange}
            />
            {
              showShareSheet && (
                <ShareQuotation
                  show={showShareSheet}
                  onClose={() => setShowShareSheet(false)}
                  onSend={handleSendQuote}
                  preFilledData={policy?.customer_data}
                  loader={SHARE_DRAFT_QUOTE_LOADER}
                />
              )
            }
            </>
          )
        } */}
        {
          showTerms && (
            <MVReviewTermsConditions
              show={showTerms}
              onClose={() => setShowTerms(false)}
              tncData={policy?.product?.tnc?.data}
              onAcceptClick={handleNext}
            />
          )
        }
        {
          showEditQuote.show && (
            <EditMVPolicyQuote
              show={showEditQuote.show}
              onClose={() => setShowEditQuote(false)}
              policy={policy}
              onSave={(data, timer) => handleSaveDraft(data, (timer || 1))}
              editSection={showEditQuote.editSection}
            />
          )
        }
      </ExtendedWarrantyQuoteReviewStyle>
    </CircularLoader>
  )
}

export default ExtendedWarrantyQuoteReviewContainer
