import { get } from 'lodash'
import { useEffect } from 'react'
import { withRouter } from 'react-router'
import Cookies from 'universal-cookie'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import AgentCommissionPoint from '../../components/AgentCommissionPoint'
import CustomerData from '../../components/CustomerData'
import Transactions from '../../components/Transactions'
import TransactionHeader from '../../components/TransactionHeader'
import TransactionPaymentHeader from '../../components/TransactionPaymentHeader'
import PolicyInfoCard from '../../components/PolicyInfoCard'
import { TransactionDetailStyle } from '../index.style'
import PolicyTransactionInfo from '../../components/PolicyTransactionInfo'
import PropertyInsuredInfo from '../../components/PropertyInsuredInfo'
import PropertyImgsInfo from '../../components/PropertyImgsInfo'
import PolicyPrintAddress from '../../components/PolicyPrintAddress'
import PolicyAddons from '../../components/PolicyAddons'
import PolicyBtns from '../../components/PolicyBtns'
import { IS_TRANSACTION_CHANGE } from '../../../../../constants/cookies'
import { OFFLINE_PACKAGE_CODE } from '../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../lang'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'
import InfoBar from '../../../../../components/InfoBar'
import PolicyInfo from '../../../../../components/PolicyCancelledRejectionInfo'
import InsuranceInfoCardProperty from '../../../../../components/InsuranceInfoCardProperty'

const cookies = new Cookies()

function PropertyTransactionDetail(props) {
  const { policy, history } = props
  const isOfflinePolicy =
    get(policy, 'product.package.code', '') === OFFLINE_PACKAGE_CODE
  const [{ isStaffAgent }] = useUpdateGlobal()

  const isGrossPremiumChanged = get(policy, 'is_gross_premium_changed', false)

  useEffect(() => {
    if (cookies.get(IS_TRANSACTION_CHANGE) === 'true') {
      NotificationManager.success(LANG_STRINGS.transactionTypeHasBeenChange)
      cookies.remove(IS_TRANSACTION_CHANGE, {
        path: '/',
      })
    }
  }, [])

  return (
    <TransactionDetailStyle>
      <PolicyInfo
        remarks={policy?.insurance_details?.remark_details || {}}
        status={policy?.policy_status || ''}
      />
      <TransactionPaymentHeader policy={policy} />
      <TransactionHeader policy={policy} />
      <div className="detail-body">
        {!isStaffAgent && !policy?.is_bulk_business && (
          <AgentCommissionPoint
            policy={policy}
            commission={get(policy, 'agent_commission', 0)}
            points={get(policy, 'agent_points', 0)}
            paymentBy={get(policy, 'payment_by', 0)}
          />
        )}
        <div className="info-card-container">
          <InsuranceInfoCardProperty
            isShowDisclaimer
            tnc={get(policy, 'product.tnc.data', [])}
            benefit={get(policy, 'product.benefit', {})}
            claims={get(policy, 'product.claims', [])}
          />
        </div>
        {isGrossPremiumChanged && (
          <InfoBar
            text={LANG_STRINGS.changeInCommissionsAndPointsAfterEndorsement}
          />
        )}
        <Transactions policy={policy} isOfflinePolicy={isOfflinePolicy} />
        <PolicyTransactionInfo policy={policy} history={history} />
        {!isOfflinePolicy && (
          <>
            <PolicyInfoCard policy={policy} />
            <CustomerData policy={policy} />
            <PropertyInsuredInfo policy={policy} />
            <PropertyImgsInfo policy={policy} />
          </>
        )}

        <PolicyPrintAddress policy={policy} history={history} />
        {!isOfflinePolicy && <PolicyAddons policy={policy} />}

        <PolicyBtns policy={policy} isOfflinePolicy={isOfflinePolicy} />
      </div>
      <NotificationContainer />
    </TransactionDetailStyle>
  )
}

export default withRouter(PropertyTransactionDetail)
