import { CustomText } from '../../../../../../../components'
import { StatusIconSvg, WarningIconWrap } from './index.style'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

export const LINE_COLORS = {
  success: AgentColorPallette.earthGreen,
  pending: AgentColorPallette.primary,
  error: AgentColorPallette.fireRed,
  warning: AgentColorPallette.fontGrey,
  neutral: AgentColorPallette.borderGrey,
}

export const HEADER_ICON_PX = 24
export const STEP_ICON_PX = 16

export function SuccessOutlineIcon({ size }) {
  const green = AgentColorPallette.earthGreen
  return (
    <StatusIconSvg width={size} height={size} viewBox="0 0 24 24" aria-hidden>
      <circle cx="12" cy="12" r="11" fill="none" stroke={green} strokeWidth="2" />
      <path
        d="M7.5 12 L10.5 15 L16.5 9"
        fill="none"
        stroke={green}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </StatusIconSvg>
  )
}

export function PendingRingIcon({ size }) {
  return (
    <StatusIconSvg width={size} height={size} viewBox="0 0 24 24" aria-hidden>
      <circle
        cx="12"
        cy="12"
        r="11"
        fill="none"
        stroke={AgentColorPallette.primary}
        strokeWidth="2"
      />
      <circle cx="12" cy="12" r="4.8" fill={AgentColorPallette.primary} />
    </StatusIconSvg>
  )
}

export function ErrorOutlineIcon({ size }) {
  const red = LINE_COLORS.error
  return (
    <StatusIconSvg width={size} height={size} viewBox="0 0 24 24" aria-hidden>
      <circle cx="12" cy="12" r="10.5" fill="none" stroke={red} strokeWidth="2" />
      <path
        d="M8.25 8.25 L15.75 15.75 M15.75 8.25 L8.25 15.75"
        fill="none"
        stroke={red}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </StatusIconSvg>
  )
}

export function NeutralOutlineIcon({ size, color = AgentColorPallette.saturatedGrey }) {
  return (
    <StatusIconSvg width={size} height={size} viewBox="0 0 24 24" aria-hidden>
      <circle cx="12" cy="12" r="11" fill="none" stroke={color} strokeWidth="2" />
    </StatusIconSvg>
  )
}

function warningExclamationFontSize(sizePx) {
  return `${Math.max(7, Math.round((11 * sizePx) / 24))}px`
}

export function WarningOutlineIcon({ size }) {
  const ring = AgentColorPallette.fontSemiGrey
  return (
    <WarningIconWrap $size={size} aria-hidden>
      <StatusIconSvg
        className="warning-icon-svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        aria-hidden
      >
        <circle cx="12" cy="12" r="11" fill="none" stroke={ring} strokeWidth="2" />
      </StatusIconSvg>
      <div className="warning-icon-label">
        <CustomText
          className="tracker-warning-exclamation"
          color={ring}
          weight={700}
          size={warningExclamationFontSize(size)}
          lineHeight="1"
          bottom="0px"
        >
          !
        </CustomText>
      </div>
    </WarningIconWrap>
  )
}

export function HeaderStatusIcon({ variant }) {
  switch (variant) {
    case 'success':
      return <SuccessOutlineIcon size={HEADER_ICON_PX} />
    case 'error':
      return <ErrorOutlineIcon size={HEADER_ICON_PX} />
    case 'warning':
      return <WarningOutlineIcon size={HEADER_ICON_PX} />
    case 'neutral':
      return <NeutralOutlineIcon size={HEADER_ICON_PX} />
    case 'pending':
    default:
      return <PendingRingIcon size={HEADER_ICON_PX} />
  }
}

export function StepStatusIcon({ variant, state }) {
  if (variant === 'error') {
    return <ErrorOutlineIcon size={STEP_ICON_PX} />
  }
  if (state === 'completed' && variant === 'success') {
    return <SuccessOutlineIcon size={STEP_ICON_PX} />
  }
  if (state === 'current' || variant === 'pending') {
    return <PendingRingIcon size={STEP_ICON_PX} />
  }
  if (variant === 'warning') {
    return <WarningOutlineIcon size={STEP_ICON_PX} />
  }
  return <NeutralOutlineIcon size={STEP_ICON_PX} color={AgentColorPallette.fontGrey} />
}
