import { get } from 'lodash'
import moment from 'moment'
import { CustomText } from '../../../../../components'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { getHardcopyType } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyDetailCard } from '../../pages/index.style'
import TransactionInfoCard from '../TransactionInfoCard'
import { PolicyPrintAddressStyle } from './index.style'

function PolicyPrintAddress (props) {
  const { policy, isCollapsible = false, hideOpsDetails = false } = props

  const getPrintAddress = () => {
    const insuranceDetails = get(policy, 'insurance_details', {})
    const hardCopyDeliveryDate = get(insuranceDetails, 'hard_copy_details.delivery_date', '')
    const hardCopyReceiveDate = get(insuranceDetails, 'hard_copy_details.receive_date', '')
    const hardCopyAddress = get(insuranceDetails, 'hard_copy_address', {})

    let items = [
      {
        head: LANG_STRINGS.receiptNumber,
        value: get(insuranceDetails, 'hard_copy_details.courier_partner_order_id', '-')
      },
      {
        head: LANG_STRINGS.shippingOption,
        value: getHardcopyType(get(insuranceDetails, 'hard_copy_details.proposed_delivery_option', '-'))
      },
      {
        head: LANG_STRINGS.province,
        value: get(hardCopyAddress, 'province_name', '-')
      },
      {
        head: LANG_STRINGS.city,
        value: get(hardCopyAddress, 'city_name', '-')
      },
      {
        head: LANG_STRINGS.postalCode,
        value: get(hardCopyAddress, 'postal_code', '-')
      },
      {
        head: LANG_STRINGS.shippingAddress,
        value: get(hardCopyAddress, 'address', '-'),
        newline: true,
        className: 'break-word-newline'
      }]

    const opsDetails = [
      {
        head: LANG_STRINGS.receiveFromProvider,
        value: hardCopyReceiveDate ? moment(hardCopyReceiveDate).format('DD MMMM YYYY') : '-'
      },
      {
        head: LANG_STRINGS.policySubmitDate,
        value: hardCopyDeliveryDate ? moment(hardCopyDeliveryDate).format('DD MMMM YYYY') : '-'
      },
      {
        head: LANG_STRINGS.policyReceiver,
        value: get(insuranceDetails, 'hard_copy_details.recipient_name', '-')
      },
      {
        head: LANG_STRINGS.activeMobileNumber,
        value: get(insuranceDetails, 'hard_copy_details.recipient_mobile', '-')
      },
      {
        head: LANG_STRINGS.typeOfDelivery,
        value: get(insuranceDetails, 'hard_copy_details.delivery_type', '-')
      },
      {
        head: LANG_STRINGS.remarksSubmitted,
        value: get(insuranceDetails, 'hard_copy_details.remark', '-')
      }
    ]

    if (!hideOpsDetails) {
      items = [
        ...items,
        ...opsDetails
      ]
    }

    return {
      heading: `${LANG_STRINGS.printPolicy}`,
      items: items
    }
  }

  if (!policy.hard_copy_required) {
    if (isCollapsible) {
      return (
        <PolicyPrintAddressStyle>
          <CollapsibleCard
            titleClassName='card-title'
            className='collapse-card'
            title={LANG_STRINGS.printPolicy}
            isOpen
          >
            <CustomText
              className='item-padding'
              color={AgentColorPallette.fontDarkerGrey}
              size='13px'
            >
              {LANG_STRINGS.thisOptionIsNotSelected}
            </CustomText>
          </CollapsibleCard>
        </PolicyPrintAddressStyle>
      )
    } else {
      return (
        <PolicyDetailCard>
          <CustomText className='item-padding' color={AgentColorPallette.black} weight={800} size='15px'>
            {LANG_STRINGS.printPolicy}
          </CustomText>
          <hr />
          <CustomText
            className='item-padding'
            color={AgentColorPallette.fontDarkerGrey}
            size='13px'
          >
            {LANG_STRINGS.thisOptionIsNotSelected}
          </CustomText>
        </PolicyDetailCard>
      )
    }
  }

  const handleTrackDelivery = () => {
    const courierId = get(policy, 'insurance_details.hard_copy_details.courier_id', '')
    props.history.push(`/courier-tracking/${courierId}/${policy.id}`)
  }

  const getSubTitle = () => {
    switch (get(policy, 'insurance_details.hard_copy_details.courier_status', '')) {
      case 'courier-not-reachable':
        return LANG_STRINGS.cannotBeTrackedNotReachable
      default:
        return ''
    }
  }

  const getSubButton = () => {
    const courierStatus = get(policy, 'insurance_details.hard_copy_details.courier_status', '')
    switch (courierStatus) {
      case 'courier-pending':
      case 'courier-sent':
      case 'courier-delivered':
      case 'courier-returned':
        return {
          label: LANG_STRINGS.trackDelivery,
          onClick: handleTrackDelivery,
          id: 'track_delivery'
        }
      default:
        return {}
    }
  }

  return (
    <TransactionInfoCard
      isCollapsible={isCollapsible}
      subTitle={getSubTitle()}
      subButton={getSubButton()}
      data={getPrintAddress()}
    />
  )
}

export default PolicyPrintAddress
