import QuoteSection from '../QuoteSections'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { CustomText } from '../../../../../../../components'
import { AccessoryItemStyle } from './index.style'
import { ACCESSORY } from '../../../../../../../constants/quoatation'
import { formatMoney } from '../../../../../../../helpers/utility'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

function QuoteVehicleModifications ({ policy, className }) {
  if (!policy?.accessories?.length) return null
  return (
    <div className={className}>
      <QuoteSection
        title={LANG_STRINGS.vehicleModification}
        policy={policy}
        marginBtm='20%'
      >
        {
          policy?.accessories?.map(accessory => (
            <AccessoryItemStyle
              gridColumn='60px 1fr 1fr'
              gridGap='1rem'
              key={accessory.name}
            >
              <CustomText
                color={AgentColorPallette.fontDarkerGrey}
                size='0.8em'
                weight={700}
              >
                {ACCESSORY[accessory.accessory_type]}
              </CustomText>
              <CustomText
                color={AgentColorPallette.fontDarkerGrey}
                size='0.8em'
                weight={700}
              >
                {accessory.name}
              </CustomText>
              <CustomText
                color={AgentColorPallette.fontDarkerGrey}
                size='0.8em'
                className='justify-self-end'
                weight={700}
              >
                {formatMoney(accessory.sum_insured, 0)}
              </CustomText>
            </AccessoryItemStyle>
          ))
        }
      </QuoteSection>
    </div>
  )
}

export default QuoteVehicleModifications
