  const convertDate = (timeStamp) => {
    const date = new Date(timeStamp)
    return new Intl.DateTimeFormat('en-UK', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    }).format(date)
  }

  const convertTime = (timeStamp) => {
    const date = new Date(timeStamp)
    return new Intl.DateTimeFormat('en-UK', {
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
      hour12: false,
    }).format(date)
  }

  const formatValues = (value, label) => {
    switch (label) {
      case LANG_STRINGS.startProtection:
      case LANG_STRINGS.endProtection:
      case LANG_STRINGS.dateOfBirth:
      case LANG_STRINGS.orderDate:
      case LANG_STRINGS.paymentDate:
        return convertDate(value)
      case LANG_STRINGS.orderTime:
      case LANG_STRINGS.paymentTime:
        return convertTime(value)
      case LANG_STRINGS.paymentMethod:
        return PAYMENT_METHOD[value]
      case LANG_STRINGS.policyStatus:
        switch (value) {
          case 'ACTIVE':
          case 'POLICY_CREATED':
            return LANG_STRINGS.active
          case 'CANCELLED':
            return LANG_STRINGS.canceled
          case 'EXPIRED':
            return 'Berakhir'
          case 'REJECTED':
            return LANG_STRINGS.rejected
          default:
        }
        break
      case LANG_STRINGS.typeProtection:
        switch (value) {
          case 'individual':
            return 'Individu'
          case 'family':
            return 'Keluarga'
          case 'group':
            return 'Group'
          default:
        }
        break
      case LANG_STRINGS.numberCovered:
        return `${value.adult + 1} Dewasa${value.kids > 0 ? `, ${value.kids} Anak` : ''}`
      case LANG_STRINGS.destination:
        return value.join(', ')
      case LANG_STRINGS.gender:
        return value === 'male' ? LANG_STRINGS.male : LANG_STRINGS.female
      default:
    }
  }

  const getNestedValue = (data, keys) => {
    let value = data
    keys.forEach((key) => {
      value = value?.[key]
    })
    if (Array.isArray(value)) {
      return value.join(', ')
    }
    return value
  }

