import React from 'react'
import CustomText from '../../CustomText'
import { AgentColorPallette } from '../../../configs/colorPallete'

const ClaimsSection = ({ claims }) => {
  // Handle structured claim data
  if (claims && Array.isArray(claims)) {
    return (
      <>
        {claims.map((claimItem, claimIndex) => (
          <div key={`claim_item_${claimIndex}`} style={{ marginBottom: '20px' }}>
            <CustomText 
              size='16px' 
              lineHeight={1.5} 
              color={AgentColorPallette.black}
              style={{ fontWeight: 'bold', marginBottom: '10px' }}
            >
              {claimItem.title}
            </CustomText>
            {
              claimItem.description && (
                <CustomText 
                  size='13px' 
                  lineHeight={1.5} 
                  color={AgentColorPallette.black}
                  style={{ marginBottom: '8px' }}
                >
                  {claimItem.description}
                </CustomText>
              )
            }
            {
              claimItem.items && claimItem.items.length > 0 && (
                <ul style={{ margin: '5px 0', paddingLeft: '20px' }}>
                  {
                    claimItem.items.map((item, itemIndex) => (
                      <li key={`claim_item_list_${claimIndex}_${itemIndex}`}>
                        <CustomText 
                          size='13px' 
                          lineHeight={1.5} 
                          color={AgentColorPallette.black}
                        >
                          {item}
                        </CustomText>
                      </li>
                    ))
                  }
                </ul>
              )
            }
          </div>
        ))}
      </>
    )
  } else {
    return (
      <CustomText size='13px' lineHeight={1.5} color={AgentColorPallette.black}>
        {claims}
      </CustomText>
    )
  }
}

export default ClaimsSection
