import { ProductInfoStyle } from './index.style'
import { ARROW_RIGHT_BLUE } from '../../../../../../../images/imageUrl'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import {
  DisplayFlexCCC,
  Row,
} from '../../../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { formatMoney } from '../../../../../../../helpers/utility'
// import { useGlobalContextValue } from '../../../../../../../contextProvider/GlobalContext/index'
import { useCallback, useMemo } from 'react'
import { useHistory } from 'react-router-dom'
// import MVPolicyInfo from '../../../../../../../components/MVPolicyCancelledRejectionInfo'

function ProductDetail({ policy, isPaymentAllowed, claimDetails }) {
  // const [{ isStaffAgent }] = useGlobalContextValue()
  const history = useHistory()

  const isPrintPolicyStatus = useMemo(() => {
    const courierStatus =
      policy?.insurance_details?.hard_copy_details?.courier_status
    switch (courierStatus) {
      case 'courier-pending':
      case 'courier-sent':
      case 'courier-delivered':
      case 'courier-returned':
        return true
      default:
        return false
    }
  }, [policy])

  const handleTrackDelivery = useCallback(() => {
    const courierId = policy?.insurance_details?.hard_copy_details?.courier_id
    history.push(`/courier-tracking/${courierId}/${policy.id}`)
  }, [history, policy])

  const renderItemAmount = (text, subText, textAlign) => {
    return (
      <div>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size="0.6em"
          weight={700}
          className="text-uppercase"
        >
          {text}
        </CustomText>
        <CustomText
          color={AgentColorPallette.blackGrey}
          size="0.8em"
          weight={700}
          textAlign={textAlign}
        >
          {subText}
        </CustomText>
      </div>
    )
  }
  const handleToPolicyClaim = useCallback(() => {
    const { claimId } = claimDetails
    history.push(`/claim/detail/${claimId}`)
  }, [history, claimDetails])

  return (
    <ProductInfoStyle>
      <DisplayFlexCCC>
        <img
          src={policy?.policy_product?.provider?.logo_url}
          width={68}
          alt="travel icon"
        />
        <CustomText
          size="0.75em"
          top="5px"
          color={AgentColorPallette.fontDarkerGrey}
        >
          {policy?.product?.provider?.name}
        </CustomText>
        <CustomText
          size="1em"
          weight={700}
          bottom="0.8rem"
          color={AgentColorPallette.blackGrey}
        >
          Premier Package
        </CustomText>
      </DisplayFlexCCC>
      {(policy?.policy_status === 'CANCELLED' ||
        policy?.policy_status === 'REJECTED') && (
        <>
          <Row
            align="center"
            justify="space-between"
            className="status-red-header"
          >
            <CustomText
              size="0.75em"
              weight={700}
              color={AgentColorPallette.darkerRed}
              bottom="0"
            >
              Status Pesanan
            </CustomText>
            <CustomText
              size="0.75em"
              weight={700}
              color={AgentColorPallette.darkerRed}
              bottom="0"
            >
              {policy?.policy_status === 'CANCELLED' ? 'Dibatalkan' : 'Ditolak'}
            </CustomText>
          </Row>
          <Row align="center" justify="center" className="status-red-remarks">
            <CustomText
              size="0.75em"
              weight={700}
              textAlign="center"
              color={AgentColorPallette.darkerRed}
              bottom="0"
            >
              {policy?.insurance_details?.remark_details || ''}
            </CustomText>
          </Row>
        </>
      )}
      {isPaymentAllowed && (
        <Row align="center" justify="space-between" className="status-yellow">
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.goldYellow}
            bottom="0"
          >
            Status Pesanan
          </CustomText>
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.goldYellow}
            bottom="0"
          >
            {LANG_STRINGS.waitingForPayment}
          </CustomText>
        </Row>
      )}
      {policy?.application_no && (
        <Row align="center" justify="space-between" className="policy-number">
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.darkCyanBlue}
            bottom="0"
          >
            Polis ID
          </CustomText>
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.darkCyanBlue}
            bottom="0"
          >
            {policy?.application_no}
          </CustomText>
        </Row>
      )}
      {policy?.insurance_details?.insurance_policy_no && (
        <Row align="center" justify="space-between" className="policy-number">
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.darkCyanBlue}
            bottom="0"
          >
            No. Polis Asuransi
          </CustomText>
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.darkCyanBlue}
            bottom="0"
          >
            {policy?.insurance_details?.insurance_policy_no}
          </CustomText>
        </Row>
      )}
      {(policy?.policy_status === 'ACTIVE' ||
        policy?.policy_status === 'POLICY_CREATED' ||
        policy?.policy_status === 'EXPIRED') && (
        <Row
          align="center"
          justify="space-between"
          className={
            policy?.policy_status === 'EXPIRED' ? 'status-grey' : 'status-green'
          }
        >
          <CustomText
            size="0.75em"
            weight={700}
            color={
              policy?.policy_status === 'EXPIRED'
                ? AgentColorPallette.fontGrey
                : AgentColorPallette.irishGreen
            }
            bottom="0"
          >
            Status Polis
          </CustomText>
          <CustomText
            size="0.75em"
            weight={700}
            color={
              policy?.policy_status === 'EXPIRED'
                ? AgentColorPallette.fontGrey
                : AgentColorPallette.irishGreen
            }
            bottom="0"
          >
            {policy?.policy_status === 'EXPIRED' ? 'Berakhir' : 'Aktif'}
          </CustomText>
        </Row>
      )}
      {policy?.application_no && claimDetails?.claimId && (
        <Row
          align="center"
          justify="space-between"
          bgColor={AgentColorPallette.crusieGreen}
          className="policy-status"
          onClick={handleToPolicyClaim}
        >
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.blackGrey}
            bottom="0"
          >
            {LANG_STRINGS.claimStatus}
          </CustomText>
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.blackGrey}
            bottom="0"
          >
            {`${claimDetails?.claimStatus}`}{' '}
            <i className="fas fa-angle-right" />
          </CustomText>
        </Row>
      )}
      {isPrintPolicyStatus && (
        <Row
          align="center"
          justify="space-between"
          className="policy-print"
          onClick={handleTrackDelivery}
        >
          <CustomText
            size="0.75em"
            weight={700}
            color={AgentColorPallette.blueDefault}
            bottom="0"
          >
            {LANG_STRINGS.policyPrintStatus}
          </CustomText>
          <Row align="center">
            <CustomText
              size="0.75em"
              weight={700}
              color={AgentColorPallette.blueDefault}
              bottom="0"
              padRight="0.5rem"
            >
              {policy?.insurance_details?.hard_copy_details?.courier_status}
            </CustomText>
            <div>
              <img src={ARROW_RIGHT_BLUE} alt="" />
            </div>
          </Row>
        </Row>
      )}
      <div className="pkg-item-btm">
        {(policy?.premium?.amount ||
          policy?.product?.basic_premium ||
          policy?.total_premium) && (
          <Row justify="space-between" align="center">
            {renderItemAmount(
              LANG_STRINGS.basicPremium,
              formatMoney(
                policy?.premium?.amount ||
                  policy?.product?.basic_premium ||
                  policy?.total_premium,
                0
              )
            )}
            {renderItemAmount(
              LANG_STRINGS.totalCommission,
              formatMoney(
                policy?.agent_commission || policy?.product?.commission,
                0
              ),
              'right'
            )}
          </Row>
        )}
        <br />
        {
          <Row justify="space-between" align="center">
            {renderItemAmount(
              LANG_STRINGS.policyHolder1,
              policy?.customer_data?.name
            )}
            {renderItemAmount(
              LANG_STRINGS.totalPoints,
              policy?.agent_points || policy?.product?.points,
              'right'
            )}
          </Row>
        }
      </div>
    </ProductInfoStyle>
  )
}

export default ProductDetail
