import { LANG_STRINGS } from '../../../../../../../lang'
import QuoteSection from '../QuoteSections'
import { useMemo, useState, useCallback, useEffect, useRef } from 'react'
import SelectedPkgAddons from '../../../../../Packages/components/SelectedPkgAddons'
import MVPolicyAddonsModal from '../../../../../Packages/components/MVPolicyAddonsModal'
import { useGetPkgDetail, useUpdatePackageStore } from '../../../../../Packages/state/hooks/usePackages'
import { getAddonsMapFromCategory, getExtraVehicleData, getPackagesReqBody } from '../../../../../../../helpers/getPackageBody'
import { getAddressString } from '../../../../../../../helpers/utility'

function QuotePkgSection ({ policy, className, onSaveDraft, isReviewPage, isPolicyDetail }) {
  const [showAddonsModal, setShowAddonsModal] = useState(false)
  const [{ getPackageDetailData = {} }, getPkgDetailsReq] = useGetPkgDetail()
  const [, updatePkgStore] = useUpdatePackageStore()
  const that = useRef({ })

  const pkg = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.insuranceProvider,
        value: policy?.product?.provider?.name
      },
      {
        title: LANG_STRINGS.productName,
        value: policy?.product?.name
      }
    ]
  }, [policy])

  const providerBranch = useMemo(() => {
    const providerBranch = policy?.provider_branch || policy?.insurance_details?.provider_branch
    return [
      {
        title: LANG_STRINGS.nameOfPolicyProviderOffice,
        value: (providerBranch?.name)
      },
      {
        title: LANG_STRINGS.addressOfPolicyProviderOffice,
        value: getAddressString(providerBranch?.location || {})
      }
    ]
  }, [policy])

  const addonsPolicyData = useMemo(() => {
    const policyData = {
      ...policy.product,
      policy_detail: {
        ...policy,
        ...policy.addons_data
      }
    }
    return policyData
  }, [policy])

  const handleEditAddons = useCallback(() => {
    // handle addons modal
    setShowAddonsModal(true)
  }, [])

  useEffect(() => {
    if (getPackageDetailData.code) {
      onSaveDraft({
        package_data: { ...getPackageDetailData },
        addons_data: that.current.addonsData
      }, 1)
      updatePkgStore({
        getPackageDetailData: undefined
      })
    }
  }, [getPackageDetailData, updatePkgStore, onSaveDraft])

  const handleSubmit = useCallback((addonsData) => {
    // addons data from the addons modal
    const addonsMap = getAddonsMapFromCategory(addonsData)
    that.current.addonsData = {
      ...addonsMap
    }
    getPkgDetailsReq({
      body: {
        ...getPackagesReqBody(policy),
        ...getExtraVehicleData(policy),
        ...addonsMap
      },
      packageCode: policy.provider_package_code
    })
    setShowAddonsModal(false)
  }, [getPkgDetailsReq, policy])

  return (
    <>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.pkgDetails}
          data={pkg}
        />
      </div>
      {
        <div className={className}>
          <QuoteSection
            title={LANG_STRINGS.policyPublishingOffice}
            data={providerBranch}
          />
        </div>
      }
      {
        (!!policy?.product?.add_ons_cat?.length || isReviewPage) && (
          <div className={`${className} quote-margin-btm`}>
            <QuoteSection
              title={LANG_STRINGS.additionalProtection}
              data={[]}
              onEditClick={handleEditAddons}
              isEdit={!isPolicyDetail}
            />
            <SelectedPkgAddons className='quote-margin-btm' addonsData={policy.product.add_ons_cat} />
          </div>
        )
      }
      {
        showAddonsModal && (
          <MVPolicyAddonsModal
            showModal={showAddonsModal}
            onClose={() => setShowAddonsModal(false)}
            onSubmit={handleSubmit}
            productCode={policy.provider_package_code}
            applicationData={addonsPolicyData}
          />
        )
      }
    </>
  )
}

export default QuotePkgSection
