import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import {
  CAR_PROTECTION,
  RENEW_PURCHASE,
  MV_RENEWAL_FLOW,
  MV_RENEWAL_STATUS,
} from '../../../../../../../constants/pkgCode'
import { ERROR_LANG } from '../../../../../../../lang'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import { useGetMvRenewalDetails } from '../../../../state/hooks/usePolicyState'
import { useUpdateGlobal } from '../../../../../../../state/globalState/hooks/useGlobalContext'
import { checkIsLvAgent } from '../../../../../../../helpers/checkAgentTags'

function useRenewalPolicy() {
  const history = useHistory()

  const [{ agentDetails = {} }] = useUpdateGlobal()
  const [{ getMvRenewalDetailsData }, getMvRenewalDetailsRequest] = useGetMvRenewalDetails()
  const [{ getMvRenewalDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const isRenewable = useCallback((policy) => {
    if (!checkIsLvAgent(agentDetails)) return false
    return (
      policy?.insurance_details?.renewal_status === MV_RENEWAL_STATUS.RENEWAL ||
      policy?.insurance_details?.renewal_status === MV_RENEWAL_STATUS.REACTIVATION
    )
  }, [agentDetails])

  const handleCreateMvRenewalPolicy = useCallback(
    (policy) => {
      getMvRenewalDetailsRequest({
        query: {
          chasis_number: policy.chasis_number,
          flow: MV_RENEWAL_FLOW.SHORTCUT,
        },
      })
    },
    [getMvRenewalDetailsRequest]
  )

  useEffect(() => {
    if (getMvRenewalDetailsData?.data && Object.keys(getMvRenewalDetailsData?.data).length > 0) {
      history.push({
        pathname: '/motor_vehicle/v2',
        state: {
          productCode: CAR_PROTECTION,
          purchaseType: RENEW_PURCHASE,
          purchaseRenewFlow: MV_RENEWAL_FLOW.SHORTCUT,
          vehicleData: getMvRenewalDetailsData?.data,
        },
      })
    }
  }, [history, getMvRenewalDetailsData])

  useEffect(() => {
    if (!!getMvRenewalDetailsStatus && getMvRenewalDetailsStatus !== 'success') {
      ShowSnackbar.error({ text: ERROR_LANG.generalErrorTryAgain })
      resetError(['getMvRenewalDetailsStatus'])
    }
  }, [getMvRenewalDetailsStatus, resetError])

  return { isRenewable, handleCreateMvRenewalPolicy }
}

export default useRenewalPolicy
