import React from 'react'
import CustomText from '../../CustomText'
import { AgentColorPallette } from '../../../configs/colorPallete'
import isEmpty from 'lodash/isEmpty'

const BenefitSection = ({ benefit, benefitType }) => {
  // Handle structured benefit data
  if (benefit && typeof benefit === 'object' && benefit.data) {
    return (
      <>
        {benefit.data.map((benefitSection, sectionIndex) => (
          <div key={`benefit_section_${sectionIndex}`} style={{ marginBottom: '20px' }}>
            <CustomText 
              size='16px' 
              lineHeight={1.5} 
              color={AgentColorPallette.black}
              style={{ fontWeight: 'bold', marginBottom: '10px' }}
            >
              {benefitSection.main_heading}
            </CustomText>
            {
              benefitSection.benefit_list && benefitSection.benefit_list.map((benefitItem, itemIndex) => (
                <div key={`benefit_item_${sectionIndex}_${itemIndex}`} style={{ marginBottom: '15px', paddingLeft: '10px' }}>
                  <CustomText 
                    size='14px' 
                    lineHeight={1.5} 
                    color={AgentColorPallette.black}
                    style={{ fontWeight: '600', marginBottom: '5px' }}
                  >
                    {benefitItem.title}
                  </CustomText>
                  {
                    benefitItem.description && (
                      <CustomText 
                        size='13px' 
                        lineHeight={1.5} 
                        color={AgentColorPallette.black}
                        style={{ marginBottom: '8px' }}
                      >
                        {benefitItem.description}
                      </CustomText>
                    )
                  }
                  {
                    benefitItem.image_url && benefitItem.image_url.trim() !== '' && (
                    <div style={{ marginBottom: '8px' }}>
                      <img 
                        src={benefitItem.image_url} 
                        alt={benefitItem.title}
                        style={{ 
                          maxWidth: '100%', 
                          height: 'auto',
                          borderRadius: '4px'
                        }}
                      />
                    </div>
                  )}
                  {
                    benefitItem.items && benefitItem.items.length > 0 && (
                      <ul style={{ margin: '5px 0', paddingLeft: '20px' }}>
                        {
                          benefitItem.items.map((item, itemListIndex) => (
                            <li key={`benefit_item_list_${sectionIndex}_${itemIndex}_${itemListIndex}`}>
                              <CustomText 
                                size='13px' 
                                lineHeight={1.5} 
                                color={AgentColorPallette.black}
                              >
                                {item}
                              </CustomText>
                            </li>
                          ))
                        }
                      </ul>
                    )
                  }
                </div>
              ))
            }
          </div>
        ))}
      </>
    )
  } else if (benefitType === 'list' && benefit) {
    return (
      <>
        {benefit.map((terms, index) => {
          return (
            <React.Fragment key={`benefit_list_${index}`}>
              {
                terms.title &&
                  <CustomText
                    color={AgentColorPallette.black}
                    size='13px'
                    bottom='10px'
                    lineHeight={1.5}
                    weight={800}
                  >
                    {terms.title}
                  </CustomText>
              }
              {
                !isEmpty(terms) &&
                  <ul className='m-0'>
                    {
                      terms.terms.map((term, i) => {
                        return (
                          <li key={i}>
                            <CustomText
                              color={AgentColorPallette.black}
                              size='13px'
                            >
                              {term}
                            </CustomText>
                          </li>
                        )
                      })
                    }
                  </ul>
              }
              {
                terms.description &&
                  <CustomText
                    color={AgentColorPallette.fontDarkerGrey}
                    size='10px'
                    bottom='20px'
                    className='pl-35'
                  >
                    {terms.description}
                  </CustomText>
              }
            </React.Fragment>
          )
        })}
      </>
    )
  } else {
    return (
      <CustomText size='13px' lineHeight={1.5} color={AgentColorPallette.black}>
        {benefit}
      </CustomText>
    )
  }
}

export default BenefitSection
