import { get } from 'lodash'
import { MitraCard } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'
import { formatMoney } from '../../../../../helpers/utility'
import { ImageUrl } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { AgentCmisnPointStyle } from './index.style'

function AgentCommissionPoint (props) {
  const { commission, points, paymentBy, policy } = props
  const isPropertyPolicy = get(policy, 'policy_detail.product_code', '') === PROPERTY_PROTECTION
  
  const renderCard = (image, heading, value) => (
    <MitraCard className='agent-info-card'>
      <img src={image} width={28} alt='card-img' />
      <CustomText top='4px' color={AgentColorPallette.fontSemiGrey} textAlign='center' size='10px'>
        {heading}
      </CustomText>
      <CustomText color={AgentColorPallette.black} size='14px' textAlign='center' weight={700}>
        {value}
      </CustomText>
    </MitraCard>
  )

  return (
    <>
      <AgentCmisnPointStyle align='center' justify='space-evenly'>
        {
          renderCard(
            ImageUrl.applicationWallet,
            'Komisi Agen',
            formatMoney(commission, 0)
          )
        }
        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
        {isPropertyPolicy ? renderCard(
          ImageUrl.applicationMedal,
          'Total Point',
          `${formatMoney(points, 3, '')} Pts`
        ) :
          renderCard(
            ImageUrl.applicationMedal,
            'Komisi Poin',
            `${formatMoney(points, 3, '')} Pts`
          )
        }
      </AgentCmisnPointStyle>
      {!isPropertyPolicy &&
        paymentBy === 'AGENT' && (
          <CustomText
            size='12px'
            bottom='22px'
            color={AgentColorPallette.fontDarkerGrey}
            textAlign='center'
          >
            {LANG_STRINGS.agentCommissionNotAddedStatement}
          </CustomText>
        )
      }
    </>
  )
}

export default AgentCommissionPoint
