import moment from 'moment'
import { PAID_BY, PAYMENT_METHOD } from '../../../../../constants/payment'
import { LANG_STRINGS } from '../../../../../lang'
import TransactionInfoCard from '../TransactionInfoCard'
import { getPaymentStatus } from '../../../../../helpers/data'
import { get } from 'lodash'
import { TRANSACTION_CHANGE_STATUS } from '../../constants'
import { Row } from '../../../../../commonStyle/index.style'
import CustomText from '../../../../../components/CustomText/index'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

function PolicyTransactionInfo (props) {
  const { policy, history, isCollapsible = false, className } = props
  const showTransactionChange = get(policy, 'pay_later_enabled', false) && !policy.use_pay_later && TRANSACTION_CHANGE_STATUS.includes(policy.status)

  const handleChangeTransaction = () => {
    // open change transaction Page
    history.push({
      pathname: `/transaction/type/${get(policy, 'id', '')}`
    })
  }

  const renderTransactionDetail = () => {
    const paymentStatus = getPaymentStatus(policy.payment_status)
    const transactionDate = policy.transaction_date ? policy.transaction_date : policy.application_date

    return {
      heading: `${LANG_STRINGS.transactionDetail}`,
      items: [
        {
          head: LANG_STRINGS.paymentStatus,
          value: paymentStatus.text,
          color: paymentStatus.color
        },
        ...(policy.proof_upload_time ? [{
          head: LANG_STRINGS.paymentUploadTime,
          render: () => {
            return (
              <div className='item-padding'>
                <Row
                  align='stretch'
                  justify='space-between'
                >
                  <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey}>
                    {LANG_STRINGS.paymentUploadTime}
                  </CustomText>
                  <CustomText
                    className='value-container'
                    textAlign='right'
                    color={AgentColorPallette.regular}
                    weight={800}
                  >
                    {moment(policy.proof_upload_time).format('DD MMMM YYYY, HH:MM:SS')}
                  </CustomText>
                </Row>
                {
                  policy.commission_disbursement_time &&
                    <div className='render-disburse-notification'>
                      {LANG_STRINGS.yourCommissionMaxDisburseOnTheDate}&nbsp;<b>{moment(policy.commission_disbursement_time).format('DD MMMM YYYY, HH:MM:SS')}</b>
                    </div>
                }
              </div>
            )
          },
          value: moment(policy.proof_upload_time).format('DD MMMM YYYY, HH:MM:SS')
        }] : []),
        {
          head: ((policy?.payment_date) ? LANG_STRINGS.paymentDate : LANG_STRINGS.transactionDate),
          value: ((policy?.payment_date) ? moment(policy.payment_date).format('DD MMMM YYYY') : transactionDate ? moment(transactionDate).format('DD MMMM YYYY') : '')
        },
        {
          head: LANG_STRINGS.paidBy,
          value: PAID_BY[policy.payment_by]
        },
        {
          head: LANG_STRINGS.paymentMethod,
          value: PAYMENT_METHOD[policy.payment_method]
        },
        {
          head: LANG_STRINGS.transactionType,
          value: !showTransactionChange ? (policy.use_pay_later ? 'Pay Later' : 'Normal') : 'mitraNotAvilable'
        }
      ]
    }
  }

  return (
    <TransactionInfoCard
      isCollapsible={isCollapsible}
      className={`${className} ${!policy.payment_method && 'border-red'}`}
      data={renderTransactionDetail()}
      handleChangeTransaction={handleChangeTransaction}
      showTransactionType={showTransactionChange}
    />
  )
}

export default PolicyTransactionInfo
