export const getPolicyActionContent = (policyStatus, commissionStatus, paymentStatus) => {
  const isPayable = PAYABLE_STATUSES.includes(paymentStatus)
  const isPaid = PAID_STATUSES.includes(paymentStatus)
  const isPaymentFailed = FAILED_PAYMENT_STATUSES.includes(paymentStatus)
  const isPolicyActive = policyStatus === POLICY_STATUS.ACTIVE
  const isPolicyCancelled = policyStatus === POLICY_STATUS.CANCELLED

  if (isPayable) {
    return [DATA_MAPPING.ONLINE_PAYMENT, DATA_MAPPING.PAYMENT_PROOF]
  }

  if (isPaid && commissionStatus === COMMISSION_STATUS.PENDING) {
    return [DATA_MAPPING.CONTACT_RM]
  }

  if (isPaid && commissionStatus === COMMISSION_STATUS.PAID && isPolicyActive) {
    return [DATA_MAPPING.DOWNLOAD_POLICY, DATA_MAPPING.ENDORSEMENT, DATA_MAPPING.CLAIM]
  }

  if (isPaymentFailed && isPolicyCancelled && commissionStatus === COMMISSION_STATUS.CANCELLED) {
    return [DATA_MAPPING.BUY_AGAIN, DATA_MAPPING.CONTACT_RM]
  }

  if (paymentStatus === PAYMENT_STATUS.EXPIRED && isPolicyCancelled) {
    return [DATA_MAPPING.BUY_AGAIN, DATA_MAPPING.CONTACT_RM]
  }

  return []
}
