import { CardContainer, HeaderSection, DetailsSection, DetailCell } from './index.style'

const CONTENTS = [
  { key: 'order-no', label: 'No. Pesanan', value: (policyData) => policyData?.application_no },
  {
    key: 'policy-no',
    label: 'No. Polis',
    value: (policyData) => policyData?.insurance_policy_no,
  },
  {
    key: 'insurance-type',
    label: 'Jenis Asuransi',
    value: (policyData) => policyData?.policy_detail?.package?.product?.name,
  },
  {
    key: 'package-name',
    label: 'Paket Asuransi',
    value: (policyData) => policyData?.policy_detail?.package?.name,
  },
]

function PolicySummary({ policyData }) {
  return (
    <CardContainer data-testid="policy-summary">
      <HeaderSection>
        <img
          className="product-icon"
          src={policyData?.policy_detail?.package?.provider?.logo_url}
          alt={policyData?.policy_detail?.package?.provider?.name}
          data-testid="policy-summary-product-icon"
        />
        <div className="customer-name" data-testid="policy-summary-customer-name">
          {policyData?.customer_data?.name || '-'}
        </div>
      </HeaderSection>
      <hr />
      <DetailsSection>
        {CONTENTS.map((cell, index) => (
          <DetailCell key={cell.label} $alignRight={index % 2 === 1}>
            <span className="label">{cell.label}</span>
            <span className="value" data-testid={`policy-summary-${cell.key}`}>
              {cell.value(policyData) || '-'}
            </span>
          </DetailCell>
        ))}
      </DetailsSection>
    </CardContainer>
  )
}

export default PolicySummary
