import { useCallback, useState, useEffect, useRef } from 'react'
import moment from 'moment'
import Calendar from 'react-calendar'
import Button from '../../components/Button'
import BottomActionSheet from '../../components/BottomActionSheet'
import { AgentColorPallette } from '../../configs/colorPallete'
import { formatDate } from '../../helpers/formatDate'
import { LANG_STRINGS } from '../../lang'
import { INFO_CIRCLE_BLACK } from '../../images'
import { DatePickerStyle, DatePickerCalendarContainer } from './index.style'

function DateBottomSheet({
  show,
  title,
  subtitle,
  defaultValue,
  dateFormat = 'YYYY-MM-DD',
  minDate,
  maxDate,
  disabled,
  submitLoading,
  onClose,
  onSubmit,
}) {
  const ref = useRef(null)

  const [selectedValue, setSelectedValue] = useState()

  // Convert string dates to Date objects
  const getMinDate = () => {
    if (!minDate) return null
    return moment(minDate).toDate()
  }

  const getMaxDate = () => {
    if (!maxDate) return null
    return moment(maxDate).toDate()
  }

  useEffect(() => {
    if (defaultValue) {
      const _defaultValue = formatDate(defaultValue, dateFormat)
      if (_defaultValue !== selectedValue) {
        setSelectedValue(_defaultValue)
      }
    }
  }, [defaultValue, dateFormat, selectedValue])

  const handleOnChange = useCallback(
    (value) => {
      const _value = formatDate(value, dateFormat)
      setSelectedValue(_value)
    },
    [dateFormat]
  )

  const handleClickOutside = useCallback((event) => {
    if (ref.current && !ref.current.contains(event.target)) {
      setSelectedValue(null)
    }
  }, [])

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)
    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [handleClickOutside])

  const getCalendarValue = () => {
    if (!selectedValue) return null
    return moment(selectedValue).toDate()
  }

  const handleSubmit = () => {
    onSubmit(selectedValue)
  }

  if (!show) return null

  return (
    <DatePickerStyle ref={ref} disabled={disabled}>
      <BottomActionSheet
        show={show}
        showHeader
        title={title}
        backGroundColor={AgentColorPallette.darkYellow}
        onCloseSheet={onClose}
        zIndex={10}
      >
        {subtitle && (
          <div className="subtitle">
            <img src={INFO_CIRCLE_BLACK} alt="" />
            <div>{subtitle}</div>
          </div>
        )}
        <DatePickerCalendarContainer>
          <Calendar
            minDetail="month"
            defaultView="month"
            showNeighboringMonth={false}
            next2Label={null}
            prev2Label={null}
            minDate={getMinDate()}
            maxDate={getMaxDate()}
            value={getCalendarValue()}
            onChange={handleOnChange}
            tileClassName={({ date, view }) => {
              if (view === 'month' && date.getDay() === 0) {
                return 'sunday'
              }
            }}
            formatShortWeekday={(_locale, date) => {
              return new Intl.DateTimeFormat('id-ID', {
                weekday: 'long',
              })
                .format(date)
                .substring(0, 1)
            }}
          />
        </DatePickerCalendarContainer>
        <div className="button-container">
          <Button
            variant="filled"
            disabled={!selectedValue}
            loading={submitLoading}
            onClick={handleSubmit}
          >
            {LANG_STRINGS.select}
          </Button>
        </div>
      </BottomActionSheet>
    </DatePickerStyle>
  )
}

export default DateBottomSheet
