import { useCallback } from 'react'
import { useHistory } from 'react-router'
import { useGetAgentDetails } from '../../../../../../../state/globalState/hooks/useGlobalContext.js'
import { getPolicyActionContent } from './helpers'
import { PolicyActionContainer, PolicyActionCard } from './index.style'

function PolicyActions({ policyData }) {
  const history = useHistory()
  const [{ getAgentDetailData = {} }] = useGetAgentDetails()

  const actions = getPolicyActionContent(
    policyData?.policy_status,
    policyData?.commission_status,
    policyData?.payment_status
  )
  const count = actions.length

  const handleActionClick = useCallback(
    (action) => action?.action?.({ history, policyData, getAgentDetailData }),
    [policyData, history, getAgentDetailData]
  )

  if (count === 0) return null

  return (
    <PolicyActionContainer>
      {actions.map((action, i) => (
        <PolicyActionCard
          key={i}
          count={count}
          disabled={action?.disabled}
          onClick={() => handleActionClick(action)}
        >
          {action?.tag && <div className="tag">{action?.tag}</div>}
          <img className="icon" src={action?.icon} alt="" />
          <div className="label">{action?.label}</div>
          <div className="subtext">{action?.subtext}</div>
        </PolicyActionCard>
      ))}
    </PolicyActionContainer>
  )
}

export default PolicyActions
