import { useCallback, useState, useEffect, useRef } from 'react'
import { useHistory } from 'react-router-dom'
import { connect } from 'react-redux'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { DetailWrapper } from '../../index.style'
import PolicyActions from '../../../../../redux/policy/action'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import ConfirmationModalV2 from '../../../../../components/ConfirmationModalV2'
import { LANG_STRINGS } from '../../../../../lang/index'
import { CustomText } from '../../../../../components'
import { RENEW_PURCHASE } from '../../../../../constants/pkgCode'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { useUpdateDiscount, useUpdatePolicyDiscount } from '../../state/hooks/usePolicyState'
import { ONE_POINT_RP } from '../../../../../constants/payment'
import TravelQuoteReview from './component/TravelQuoteReview'

const {
  getApplicationDetail, resetPolicyStore,
  getDownloadPdfRequest
} = PolicyActions

function ExtendedWarrantyTransactionDetail ({ policy, product }) {
  const history = useHistory()
  const that = useRef({
    isDiscountCall: false
  })
  const [paymentModalState, setPaymentModalState] = useState(false)
  const [, updateDiscountState] = useUpdateDiscount()
  const [, updatePolicyDiscountRequest] = useUpdatePolicyDiscount()
  const [{ updatePolicyDiscountStatus = '' }] = useErrorContextValue()
  const { resetError } = useResetError()

  const handleAgreePayment = useCallback(() => {
    history.push({
      pathname: `/payment/car-protection/${policy.id}`,
      state: {
        previous: history.location.pathname,
        policyStatus: policy.policy_status
      }
    })
  }, [policy, history])

  const handlePayment = useCallback((data = {}) => {
    // handle the payment old status here
    if (data.isDiscountChange && !that.current.isDiscountCall) {
      that.current.isDiscountCall = true
      updatePolicyDiscountRequest({
        body: {
          discount: data.discount
        },
        policyId: policy.id
      })
      return
    }
    const {
      payment_status: paymentStatus,
      payment_by: paymentBy,
      // use_pay_later: usePayLater,
      policy_detail: policyDetail,
      transaction_ids: transactionIdsMap = {},
      bank_va: bankVa,
      id,
      status,
      policy_status: policyStatus
    } = policy
    let path = ''
    if (bankVa && transactionIdsMap.agent && (paymentStatus === 'COMPLETED')) {
      return history.push(`/agent/va/detail/${transactionIdsMap.agent}/${id}`)
    } else if (['QUOTATION', 'INITIATED'].includes(status)) {
      if (policyDetail.purchase_type === RENEW_PURCHASE) {
        path = `/motor_vehicle/renewal/policy/form/${id}/${policyDetail.org_policy_ref_id}` // `/motor_vehicle/packages/${id}/form`
      } else {
        path = `/motor_vehicle/packages/${id}/form`
      }
    } else if (
      (status === 'APPLICATION_COMPLETED') ||
      (
        (
          (
            ['PAYMENT_PENDING', 'POLICY_CREATED'].includes(status) &&
            ['WAITING_FOR_PAYMENT', 'NO_PAYMENT_MADE', 'ACTIVE', 'EXPIRED', 'FAILED'].includes(paymentStatus)) ||
          (['CUSTOMER_EMAIL', 'CUSTOMER'].includes(paymentBy) && paymentStatus !== 'ACTIVE')
        )
      )
    ) {
      handleAgreePayment()
    } else if (status === 'PAYMENT_PENDING' && transactionIdsMap.agent) {
      path = `/agent/payment/success/${transactionIdsMap.agent}/${id}`
    }
    if (path === '') {
      handleAgreePayment()
    }
    history.push({
      pathname: path,
      state: {
        status,
        policyStatus,
        token: id,
        policyId: id,
        transactionId: policy.transaction_id,
        paymentTransactionId: transactionIdsMap.agent,
        createPolicyData: policy,
        applicationNo: policy.application_no,
        previous: history.location.pathname
      }
    })
  }, [
    policy, handleAgreePayment, history, updatePolicyDiscountRequest
  ])

  useEffect(() => {
    if (updatePolicyDiscountStatus === 'success') {
      updateDiscountState(0)
      handlePayment()
      resetError(['updatePolicyDiscountStatus'])
    } else if (updatePolicyDiscountStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updatePolicyDiscountStatus
      })
      resetError(['updatePolicyDiscountStatus'])
    }
  }, [
    resetError, updateDiscountState,
    updatePolicyDiscountStatus, handlePayment
  ])

  return (
    <DetailWrapper padBtm='0'>
      {
        (policy?.application_no && !policy?.migrated_draft_id) && (
          <TravelQuoteReview
            policyData={{
              ...policy,
              ...policy?.policy_detail,
              policy_product: policy.product,
              customer_data: (policy.customer_data || policy?.policy_detail?.customer_data),
              point_used: policy.point_used ? (policy.point_used / ONE_POINT_RP) : 0,
              survey_response: policy.survey_response
            }}
            isShowEditDiscount={false}
            onPaymentClick={handlePayment}
            productCode={product}
            height='auto'
            top='48px'
            isPolicyDetail
          />
        )
      }
      <ConfirmationModalV2
        title={LANG_STRINGS.information}
        okText={LANG_STRINGS.okay}
        visible={paymentModalState}
        onCancel={() => setPaymentModalState(false)}
        onOk={handleAgreePayment}
      >
        <CustomText
          color={AgentColorPallette.blackGrey}
          size='0.85em'
        >
          {LANG_STRINGS.agentDoingPaymentConfirmation}
        </CustomText>
      </ConfirmationModalV2>
    </DetailWrapper>
  )
}

export default connect(state => ({
  agentDetails: state.User.agentDetails,
  isStaffAgent: state.User.isStaffAgent,
  applicationDetail: state.Policy.applicationDetail,
  agentPayingData: state.Policy.agentPayingData,
  agentPayingMsg: state.Policy.agentPayingMsg,
  agentPayingError: state.Error.AGENT_PAYING,
  agentPayingLoading: state.Loading.AGENT_PAYING,
  applicationDetailLoading: state.Loading.GET_APPLICATION_DETAIL,
  pdfDownloadLoading: state.Loading.GET_DOWNLOAD_PDF
}), {
  getApplicationDetail,
  getDownloadPdfRequest,
  resetPolicyStore
})(ExtendedWarrantyTransactionDetail)
