import { get } from 'lodash'
import { formatMoney } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import TransactionInfoCard from '../TransactionInfoCard'
import { has } from 'lodash/object'

function MVInsuredInfo (props) {
  const { policy, isShowKTPSTNKAddress } = props

  const renderInsuredData = () => {
    const { policy_detail: policyDetail = {}, product = {} } = policy
    return {
      heading: `${LANG_STRINGS.insuredObject}`,
      items: [
        { head: 'Tipe Benefit', value: get(product, 'package.name', '') },
        { head: 'Pengunaan', value: get(policyDetail, 'usage', '') },
        { head: 'Harga Kendaraan', value: formatMoney(get(product, 'vehicle_sum_insured', ''), 0) },
        { head: 'Jenis Kendaraan', value: get(product, 'vehicle_type', '') },
        { head: 'Tahun Pembuatan', value: policyDetail.year },
        { head: 'Nomor Plat', value: policyDetail.vehicle_plate_no },
        { head: 'Merek Kendaraan', value: policyDetail.brand },
        { head: 'Model Kendaran', value: policyDetail.variant },
        { head: 'Nomor Rangka', value: policyDetail.chasis_number },
        { head: 'Nomor Mesin', value: policyDetail.machine_number },
        { head: 'Transmisi', value: policyDetail.transmission_type },
        { head: 'Warna', value: policyDetail.color },
        {
          head: LANG_STRINGS.stnkPhoto,
          value: (has(policyDetail, 'stnk_url') || isShowKTPSTNKAddress) ? policyDetail.stnk_url : 'mitraNotAvilable',
          type: 'img'
        }
      ]
    }
  }

  return (
    <TransactionInfoCard
      data={renderInsuredData()}
    />
  )
}

export default MVInsuredInfo
