import { Grid, Row } from '../../commonStyle/index.style'
import { PolicyPaymentInfoStyle } from './index.style'
import CustomText from '../CustomText/index'
import { LANG_STRINGS } from '../../lang/index'
import { AgentColorPallette } from '../../configs/colorPallete'
import { convertTo3digitFloat, formatMoney } from '../../helpers/utility'
import Button from '../Button/index'
import { useState, useCallback, useImperativeHandle, forwardRef, useMemo, useEffect } from 'react'
import PaymentBottomSheet from './components/PaymentBottomSheet'
import { ONE_POINT_RP } from '../../constants/payment'
import { MANUAL_ORDER } from '../../constants/pkgCode'
import LoaderSvg from '../CircularLoader/LoaderSvg'
import { usePaymentStatus } from '../../containers/Private/Policy/hooks/payment/usePaymentStatus'

function PolicyPaymentInfo(
  {
    policy,
    btnText = LANG_STRINGS.buy,
    isUseInstalment,
    isShareBtn,
    showDiscount,
    discountPercent,
    maxDiscount,
    commission,
    paymentBy = {},
    agentPayment = {},
    instalmentPayment = {},
    onShareClick = () => {},
    onBuyClick = () => {},
    onSaveDraft = () => {},
    onFinalPayment = () => {},
    onGetFinalPayment = () => {},
    onCloseReview = () => {},
    onDiscountChange,
    paymentReview = false,
    serviceChargeData = {},
    paymentLoader = false,
    className,
    discountLoader,
    showFinalCommissionWord,
    grey,
  },
  parentRef
) {
  const [openPayment, setOpenPayment] = useState(false)
  const [discount, setDiscount] = useState(policy?.discount || 0)
  const [disabled, setDisabled] = useState(false)
  const paymentMap = useMemo(() => {
    return {
      basic_premium: isUseInstalment
        ? instalmentPayment?.payable_amount
        : policy?.policy_detail?.protection_case === MANUAL_ORDER
          ? policy.net_premium
          : policy?.basic_premium || 0,
      add_on_premium: isUseInstalment
        ? instalmentPayment?.add_on_premium
        : policy?.add_on_premium || 0,
      sub_total: isUseInstalment
        ? instalmentPayment?.payable_amount
        : policy?.policy_detail?.protection_case === MANUAL_ORDER
          ? policy.net_premium
          : policy?.sub_total || 0,
      tax: isUseInstalment ? agentPayment.tax : agentPayment.tax || policy?.total_tax || 0,
      service_fee: serviceChargeData.service_charge || policy?.service_fee || 0,
      commission_used: agentPayment.useCommission || policy?.commission_used || 0,
      point_used: agentPayment.usePoints || policy?.point_used || 0,
      printing_fee: policy?.printing_fee || 0,
      discount: isUseInstalment ? instalmentPayment.discount : discount || policy?.discount || 0,
      current_commission_used: isUseInstalment
        ? instalmentPayment.current_commission_used - (instalmentPayment.discount || 0)
        : policy?.current_commission_used
          ? policy.agent_commission - (policy.discount || 0)
          : policy?.current_commission_used,

      // FEES NEW APPROACH
      fees: policy?.fees || [],
    }
  }, [agentPayment, policy, discount, serviceChargeData, instalmentPayment, isUseInstalment])

  const { isPaymentActive } = usePaymentStatus(policy)

  useEffect(() => {
    setDiscount(policy.discount)
  }, [policy.discount])

  const handleDiscount = useCallback(
    (discount) => {
      setDiscount(discount)
      if (onDiscountChange) {
        onDiscountChange({
          discount,
        })
      } else {
        onSaveDraft({
          discount,
        })
      }
    },
    [onDiscountChange, onSaveDraft]
  )

  const handleBuy = useCallback(() => {
    setOpenPayment(false)
    onBuyClick()
  }, [onBuyClick])

  const getTotalBill = useMemo(() => {
    // this is used to calculate the total BIll
    if (isUseInstalment) {
      const totalBill =
        instalmentPayment.payable_amount -
        (instalmentPayment.current_commission_used || 0) +
        (instalmentPayment.stamp_duty || 0) +
        (instalmentPayment.admin_fee || 0)
      const tax = paymentMap.tax || 0
      if (serviceChargeData.payable_amount) {
        onGetFinalPayment(serviceChargeData.payable_amount)
        return serviceChargeData.payable_amount
      }
      return totalBill + tax
    }
    const totalBill = policy.total_premium || policy.total_bill
    if (serviceChargeData.payable_amount) {
      onGetFinalPayment(serviceChargeData.payable_amount)
      return serviceChargeData.payable_amount
    }
    let payAbleAmount = parseFloat(paymentBy?.payableAmount || 0)
    if (!payAbleAmount) {
      payAbleAmount = totalBill - parseFloat(paymentMap.discount)
    }
    const finalPayAbleAmount = convertTo3digitFloat(
      payAbleAmount +
        paymentMap.tax -
        (paymentMap.commission_used + paymentMap.point_used * ONE_POINT_RP)
    )
    if (finalPayAbleAmount < 0 || finalPayAbleAmount < 1) {
      onGetFinalPayment(0)
      return 0
    }
    if (!paymentBy?.id && policy.payment_by === 'AGENT') {
      const pay = finalPayAbleAmount - paymentMap.current_commission_used
      onGetFinalPayment(pay)
      return pay
    } else if (policy.payable_premium && !paymentBy?.payableAmount) {
      const pay = policy.payable_premium
      onGetFinalPayment(pay)
      return pay
    }
    onGetFinalPayment(finalPayAbleAmount)
    return finalPayAbleAmount
  }, [
    paymentBy,
    policy,
    serviceChargeData,
    paymentMap,
    onGetFinalPayment,
    isUseInstalment,
    instalmentPayment,
  ])

  useImperativeHandle(parentRef, () => ({
    getDiscount: () => discount,
    getPayableAmount: () => getTotalBill,
  }))

  const isPolicyCancelledOrRejected = () => {
    return ['REJECTED', 'CANCELLED'].includes(policy?.policy_status)
  }

  const getGridColumns = () => {
    const isCancelledOrRejected = isPolicyCancelledOrRejected()
    let column = ''
    if (isShareBtn) {
      column = isCancelledOrRejected ? '1fr 1fr' : '1fr 1fr 1fr'
    } else if (paymentReview) {
      column = isCancelledOrRejected ? '' : '1fr'
    } else {
      column = isCancelledOrRejected ? '1fr' : '1fr 2fr'
    }
    return column
  }

  useEffect(() => {
    if (!isPaymentActive) {
      setDisabled(true)
    }
  }, [isPaymentActive])

  return (
    <PolicyPaymentInfoStyle className={className}>
      <Grid gridColumn={getGridColumns()} gridGap="0.8rem" className="action-grid">
        {!paymentReview && (
          <div onClick={() => setOpenPayment((oldValue) => !oldValue)}>
            <CustomText color={AgentColorPallette.fontDarkerGrey} size="0.7em" weight={700}>
              {isUseInstalment
                ? `${LANG_STRINGS.totalBill} ${LANG_STRINGS.instalment} ${instalmentPayment.serial_number}`
                : LANG_STRINGS.totalBill}
            </CustomText>
            <Row justify="space-between">
              <CustomText color={AgentColorPallette.bloodRed} size="0.75em" weight={700}>
                {formatMoney(getTotalBill, 0)}
              </CustomText>
              <CustomText color={AgentColorPallette.fontDarkerGrey}>
                <i
                  className={`fas fa-angle-up ${openPayment ? 'caret-rotate-up' : 'caret-rotate-down'}`}
                />
              </CustomText>
            </Row>
          </div>
        )}
        {discountLoader ? (
          <Row justify="center" align="center">
            <LoaderSvg size="32px" isLoader />
          </Row>
        ) : (
          isShareBtn &&
          !paymentReview && (
            <Button
              className="send-offer-btn"
              onClick={onShareClick}
              id="mobil-detail-offer-click"
              color={AgentColorPallette.blackGrey}
            >
              {LANG_STRINGS.share}
            </Button>
          )
        )}
        {!['REJECTED', 'CANCELLED'].includes(policy?.policy_status) && !discountLoader && (
          <Button
            className="button"
            onClick={paymentReview ? onFinalPayment : handleBuy}
            id="mobil-detail-agent-buy-pkg-click"
            color={grey ? AgentColorPallette.white : AgentColorPallette.blackGrey}
            backgroundColor={grey ? AgentColorPallette.fontSemiGrey : ''}
            disabled={disabled}
          >
            {paymentReview ? LANG_STRINGS.makePayment : btnText}
          </Button>
        )}
      </Grid>
      {(openPayment || paymentReview) && (
        <PaymentBottomSheet
          show={openPayment || paymentReview}
          onClose={() => (paymentReview ? onCloseReview(false) : setOpenPayment(false))}
          policy={{
            ...policy,
            payment_by: paymentBy.id || policy.payment_by,
            total_bill: getTotalBill,
          }}
          setDisabled={setDisabled}
          showDiscount={showDiscount}
          discountPercent={discountPercent}
          commission={commission}
          maxDiscount={maxDiscount}
          paymentMap={paymentMap}
          onDiscountChange={handleDiscount}
          loader={paymentLoader}
          instalmentPayment={instalmentPayment}
          isUseInstalment={isUseInstalment}
          showFinalCommissionWord={showFinalCommissionWord}
        />
      )}
    </PolicyPaymentInfoStyle>
  )
}

export default forwardRef(PolicyPaymentInfo)
