import { TabsWithIconStyle, TabsIcon } from './index.style'
import { useCallback, useState } from 'react'

function TabsWithIcon ({ isSticky, borderColor ,defaultTab, top, data = [], onClick = () => {} }) {
  const [selectedTab, setSelectedTab] = useState(defaultTab || '')

  const handleTabSelect = useCallback((tab) => {
    setSelectedTab(tab)
    onClick(tab)
  }, [onClick])

  return (
    <TabsWithIconStyle isSticky={isSticky} top={top}>
      {
        data.map((tab, index) => (
          <TabsIcon
            key={`tabs-${index}`}
            selected={selectedTab.value === tab.value}
            onClick={() => handleTabSelect(tab)}
            borderColor={borderColor}
          >
            {
              tab.icon && (
                <>
                  <img src={tab.icon} width={24} alt='' />&nbsp;
                </>
              )
            }
            {
              (selectedTab.value === tab.value) && tab.title
            }
          </TabsIcon>
        ))
      }
    </TabsWithIconStyle>
  )
}

export default TabsWithIcon
