import { Button } from '../../../../../../components'
import { EditMVQuoteStyle } from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang/index'
import { useCallback, useState, useRef, useMemo } from 'react'
import VehicleDocumentSection from '../../MVPolicyVehicleForm/components/VehicleDocumentSection'
import VehicleDetails from '../../MVPolicyVehicleForm/components/VehicleDetails'
import VehiclePhotos from '../../MVPolicyVehicleForm/components/VehiclePhotos'
import VehicleDamageSection from '../../MVPolicyVehicleForm/components/VehicleDamageSection'
import VehicleModificationPhoto from '../../MVPolicyVehicleForm/components/VehicleModificationPhoto'
import CustomerDocument from '../../MVPolicyCustomerData/components/CustomerDocument'
import CustomerNameSection from '../../MVPolicyCustomerData/components/CustomerNameSection'
import CustomerAddress from '../../MVPolicyCustomerData/components/CustomerAddress'
import HardCopySection from '../../MVPolicyCustomerData/components/HardCopySection'
import { SEND_TO_CUSTOMER } from '../../../../../../constants/hardCopy'

function EditMVQuoteContainer ({ policy, editSection = {}, onSave = () => {}, onClose }) {
  const [error, setError] = useState({})
  const [btnEnable, setBtnEnable] = useState(false)
  const that = useRef({})
  const vehicleDetailRef = useRef()
  const vehiclePhotosRef = useRef()
  const vehicleModPhotosRef = useRef()
  const vehicleDamageRef = useRef()
  const customerDocRef = useRef()
  const customerNameRef = useRef()
  const customerAddressRef = useRef()
  const hardCopyRef = useRef()

  const hardCopyData = useMemo(() => {
    if (!policy) return {}
    return {
      hard_copy_required: policy?.hard_copy_required,
      hard_copy_sent_to: policy?.hard_copy_sent_to,
      customer_address: policy?.customer_data?.customer_address,
      customer_name: policy?.customer_data?.name,
      mobile_no: policy?.customer_data?.mobile_no,
      hard_copy_address: policy?.hard_copy_address,
      hard_copy_recipient: policy?.hard_copy_recipient || (policy.hard_copy_sent_to === SEND_TO_CUSTOMER ? policy?.customer_data?.name : ''),
      hard_copy_recipient_mobile: policy?.hard_copy_recipient_mobile || (policy.hard_copy_sent_to === SEND_TO_CUSTOMER ? policy?.customer_data?.mobile_no : '')
    }
  }, [policy])

  const handleSave = useCallback(() => {
    if ((editSection.section === LANG_STRINGS.document) && policy.stnk_url && !that.current.stnk_url) {
      setError({
        stnk_url: LANG_STRINGS.required
      })
      return
    } else if ((editSection.section === LANG_STRINGS.detailObject)) {
      const vehicleDetails = vehicleDetailRef.current.validateFormValues()
      if (!vehicleDetails) return
    } else if (editSection.section === LANG_STRINGS.vehiclePhoto) {
      const vehiclePhotos = vehiclePhotosRef.current.validateFormValues()
      if (!vehiclePhotos) return
    } else if (editSection.section === LANG_STRINGS.vehicleModificationPhotos) {
      const accessories = vehicleModPhotosRef.current.validateFormValues()
      if (!accessories) return
    } else if (editSection.section === LANG_STRINGS.vehicleDamage) {
      const vehicleDamages = vehicleDamageRef.current.validateFormValues()
      if (!vehicleDamages) return
    } else if (editSection.section === LANG_STRINGS.customerDocument) {
      const customerDoc = customerDocRef.current.validateFormValues()
      if (!customerDoc || customerDoc?.ktp_no === ERROR_LANG.ktpError) return
      that.current = {
        ...that.current,
        customer_data: {
          ...policy.customer_data,
          ...that.current
        }
      }
    } else if (editSection.section === LANG_STRINGS.nameAndContactInfo) {
      const customerName = customerNameRef.current.validateFormValues()
      if (!customerName || customerName?.name === 'Nama tidak boleh ada digit' || customerName?.email === 'Format Email Salah') return
      that.current = {
        ...that.current,
        customer_data: {
          ...policy.customer_data,
          ...that.current.customer_data
        }
      }
    } else if (editSection.section === LANG_STRINGS.residenceAddress) {
      const customerAddress = customerAddressRef.current.validateFormValues()
      if (!customerAddress) return
      that.current = {
        ...that.current,
        customer_data: {
          ...policy.customer_data,
          customer_address: {
            ...that.current.customer_address
          }
        }
      }
    } else if (editSection.section === LANG_STRINGS.printPolicy) {
      const hardCopyAddress = hardCopyRef.current && hardCopyRef.current.validateHardCopyAddress()
      if (!hardCopyAddress || (hardCopyAddress.hard_copy_required && !hardCopyAddress.isValid)) return
      if (hardCopyAddress.hard_copy_required) {
        that.current = {
          ...hardCopyAddress
        }
      } else {
        that.current = {
          hard_copy_required: false,
          hard_copy_sent_to: '',
          hard_copy_address: {},
          hard_copy_recipient: '',
          hard_copy_sent_to_name: '',
          hard_copy_recipient_mobile: ''
        }
      }
    }
    onClose()
    onSave({
      ...that.current
    })
  }, [onSave, onClose, policy, editSection.section])

  const handleChange = useCallback((data) => {
    // data after change comes here
    that.current = {
      ...that.current,
      ...data
    }
    setBtnEnable(true)
  }, [])

  const renderEditSection = useCallback(() => {
    switch (editSection.section) {
      case LANG_STRINGS.document:
        return (
          <VehicleDocumentSection
            policy={policy}
            error={error.stnk_url}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.detailObject:
        return (
          <VehicleDetails
            ref={vehicleDetailRef}
            quoteData={policy}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.vehiclePhoto:
        return (
          <VehiclePhotos
            ref={vehiclePhotosRef}
            images={policy.images}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.vehicleModificationPhotos:
        return (
          <VehicleModificationPhoto
            ref={vehicleModPhotosRef}
            accessories={policy.accessories}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.vehicleDamage:
        return (
          <VehicleDamageSection
            ref={vehicleDamageRef}
            damageData={{
              damage_remarks: policy.damage_remarks,
              damage_photos: policy.damage_photos
            }}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.customerDocument:
        return (
          <CustomerDocument
            ref={customerDocRef}
            customerData={{
              ...policy.customer_data,
              ktp_no: policy?.ktp_no,
              ktp_url: policy?.ktp_url
            }}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.nameAndContactInfo:
        return (
          <CustomerNameSection
            ref={customerNameRef}
            customerData={policy.customer_data}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.residenceAddress:
        return (
          <CustomerAddress
            ref={customerAddressRef}
            customerAddress={policy.customer_address}
            onChange={handleChange}
          />
        )
      case LANG_STRINGS.printPolicy:
        return (
          <HardCopySection
            ref={hardCopyRef}
            policy={policy}
            onChange={handleChange}
            preFilledData={hardCopyData}
            isHideSendToPP={policy?.provider_branch?.tags ? !policy?.provider_branch?.tags.includes('HEADQUARTER') : false}
            proposedAdminFee={policy?.package_data?.proposed_admin_fee || policy?.proposed_admin_fee}
            isHardCopyRequired={policy?.package_data?.always_charge_hard_copy}
          />
        )
      default:
        break
    }
  }, [policy, hardCopyData, error, editSection, handleChange])

  return (
    <EditMVQuoteStyle>
      <div className='edit-container'>
        {
          renderEditSection()
        }
      </div>
      <Button onClick={handleSave} disabled={!btnEnable}>
        {LANG_STRINGS.saveNew}
      </Button>
    </EditMVQuoteStyle>
  )
}

export default EditMVQuoteContainer
