import isEmpty from 'lodash/isEmpty'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { Benefit, Button, CustomText } from '../../../../../components'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { PaylaterBadge } from '../../../../../components/ContentBox/index.style'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import ZoomImg from '../../../../../components/zoomImg'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PHOTO } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { CollapsibleCardWrapper, PolicyDetailCard, RenderDetailContent } from '../../pages/index.style'

function TransactionInfoCard (props) {
  const {
    data, className, usePaylater, showTransactionType,
    handleChangeTransaction, isCollapsible = false, subTitle = '',
    subButton = {}
  } = props

  const getNoImgContainer = (widthClass) => {
    return (
      <DisplayFlexCCC className={`no-img ${widthClass}`}>
        <img alt='dashboard-img' src={PHOTO} className='uploaded-image' />
      </DisplayFlexCCC>
    )
  }

  const getValueContainer = (item = {}) => {
    if (item.type === 'img') {
      return item.value ? (
        <ZoomImg
          src={item.value}
          imgContainer={
            <SingleImgContainer
              minWidth='50px'
              imgUrl={item.value}
              imgClassName='single-img-margin'
              showVerified
            />
          }
        />
      ) : getNoImgContainer('single-img-margin')
    }
    const text = (item.head === 'Manfaat') ? item.value.description : item.value
    return (
      <CustomText
        size='13px'
        className={`item-value ${item.className ? item.className : ''}`}
        textAlign={item.newline ? 'left' : 'right'}
        color={item.color || AgentColorPallette.regular}
        weight={800}
      >
        {text || '-'}
      </CustomText>
    )
  }

  const getFlexDirection = (item) => {
    const itemHead = item.head
    if (item.newline) {
      return 'column'
    }
    switch (itemHead) {
      case 'Manfaat':
      case 'Foto KTP':
      case 'Foto STNK':
        return 'column'
      default: return 'row'
    }
  }

  const renderContent = () => {
    return (
      <>
        {
          data.items.map((item, index) => {
            const renderSeparator = (index !== data.items.length - 1) || showTransactionType
            if (item.value === 'mitraNotAvilable') return null
            return (
              <RenderDetailContent
                key={index}
                onClick={item.onClick ? item.onClick : () => {}}
                border={renderSeparator}
                isClick={!!item.onClick}
                bgColor={item.isSubHead}
              >
                {
                  item.isSubHead ? (
                    <CustomText
                      size='13px'
                      weight={600}
                      className='subhead-item-padding'
                      color={AgentColorPallette.fontDarkerGrey}
                    >
                      {item.head}
                    </CustomText>
                  ) : (
                    item.render
                      ? (
                        <div>
                          {item.render()}
                        </div>
                      )
                      : (
                        <Row
                          className='item-padding'
                          align='stretch'
                          flexDirection={() => getFlexDirection(item)}
                          justify='space-between'
                          flexGrow='1'
                        >
                          <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey}>
                            {item.head}
                          </CustomText>
                          {
                            item.head === 'Manfaat'
                              ? (
                                <div>
                                  <Benefit benefitData={item.value} />
                                </div>
                              )
                              : (
                                <div
                                  className={getFlexDirection(item) === 'column' ? 'text-align-left' : 'value-container'}
                                >
                                  {getValueContainer(item)}
                                </div>
                              )
                          }
                        </Row>
                      )
                  )
                }
                {
                  item.onClick && (
                    <span className='arrow-right'>
                      <i className='fas fa-angle-right' />
                    </span>
                  )
                }
              </RenderDetailContent>
            )
          })
        }
        {
          showTransactionType && (
            <Row className='transaction-container item-padding' align='center' justify='space-between' onClick={handleChangeTransaction}>
              <div>
                <CustomText color={AgentColorPallette.fontDarkerGrey}>
                  {LANG_STRINGS.transactionType}
                </CustomText>
                <CustomText size='10px' color={AgentColorPallette.fontDarkerGrey}>
                  {LANG_STRINGS.youCanChangeTheTypeOfTransaction}
                </CustomText>
              </div>
              <Row className='transaction-type' justify='space-between'>
                {
                  getValueContainer({ value: 'Normal' })
                }
                <i className='fas fa-angle-right' />
              </Row>
            </Row>
          )
        }
      </>
    )
  }

  if (isCollapsible) {
    return (
      <CollapsibleCardWrapper className={className}>
        <CollapsibleCard
          titleClassName='card-title'
          className='collapse-card'
          title={data.heading}
          subTitle={subTitle}
          subButton={subButton}
          isOpen
        >
          {
            renderContent()
          }
        </CollapsibleCard>
      </CollapsibleCardWrapper>
    )
  } else {
    return (
      <PolicyDetailCard className={className}>
        <CustomText className='item-padding' color={AgentColorPallette.black} weight={800} size='15px'>
          {data.heading}
          {
            subTitle &&
              <CustomText
                size='10px'
                color={AgentColorPallette.regular}
                top='5px'
              >
                {subTitle}
              </CustomText>
          }
          {
            !isEmpty(subButton) &&
              <Button id={subButton.id} className='sub-button' onClick={() => subButton.onClick()}>
                {subButton.label}
              </Button>
          }
        </CustomText>
        {
          usePaylater && (
            <PaylaterBadge>
              {LANG_STRINGS.paylater}
            </PaylaterBadge>
          )
        }
        <hr />
        {
          renderContent()
        }
      </PolicyDetailCard>
    )
  }
}

export default TransactionInfoCard
