import { useState, useCallback, useEffect, useRef, useMemo } from 'react'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import size from 'lodash/size'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import PolicyPaymentInfo from '../../../../../../components/PolicyPaymentInfo'
import TabsWithIcon from '../../../../../../components/TabWithIcon'
import ProductInfo from '../components/ProductInfo'
import QuoteCustomerData from '../components/QuoteCustomerData'
import QuotePkgSection from '../components/QuotePkgSection'
import QuoteProtectionSection from '../components/QuoteProtectionSection'
import VehicleCriteria from '../components/VehicleCriteria'
import VehicleDocumentAndDetails from '../components/VehicleDocumentAndDetails'
import { POLICY_TABS, POLICY_DETAILS_TAB } from '../constants'
import { MVQuoteReviewStyle, RenewalButtonContainer } from './index.style'
import { LANG_STRINGS } from '../../../../../../lang/index'
import MVReviewTermsConditions from '../components/MVReviewTermsConditions'
import {
  useCompleteDraftQuote,
  useGetDraftQuoteDetails,
  useUpdateDiscount,
  useUpdateDraftQuote,
  useClaimsList,
} from '../../../state/hooks/usePolicyState'
import { getMappedQuoteToPolicyData } from '../../../helpers'
import CircularLoader from '../../../../../../components/CircularLoader'
import EditMVPolicyQuote from '../../EditMVPolicyQuoteBottomSheet'
import ShowSnackbar from '../../../../../../components/ShowNotification/index'
import PolicyDetailSection from '../components/PolicyDetail'
import QuoteVehicleModifications from '../components/QuoteVehicleModifications'
import { BottomActionContainerStyle } from '../../../../../../commonStyle/index.style'
import { Button } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import {
  CAR_PROTECTION,
  MV_QUOTE_STEPS_SECTIONS,
  EXTENDED_WARRANTY_PROTECTION,
} from '../../../../../../constants/pkgCode'
import { useDraftPrevSteps } from '../../../../../../state/commonState/hooks/useDraftPrevSteps'
import { gTagOnQuoteCreatedBy } from '../../../../../../tagManager'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext/index'
import { QUOTE_CREATED_BY } from '../../../../../../constants/appConstants'
import {
  useGetPkgDetail,
  useShareDraftQuoteToCustomer,
} from '../../../../Packages/state/hooks/usePackages'
import { getPackagesReqBody, getExtraVehicleData } from '../../../../../../helpers/getPackageBody'
import { extractValues } from '../../../../../../helpers/utility'
import ShareQuotation from '../../../../Packages/components/ShareQuotation'
import useRenewalPolicy from '../hooks/useRenewalPolicy'

function MVQuoteReviewContainer({
  policyData = {},
  isPolicyDetail,
  height,
  isShowEditDiscount,
  top,
  onPaymentClick = () => {},
  isMVDraftDetail,
  isReviewQuote,
  productCode,
}) {
  const that = useRef({
    tabsData: [...(isPolicyDetail ? POLICY_DETAILS_TAB : []), ...POLICY_TABS],
  })
  const paymentRef = useRef()
  const paymentInfoRef = useRef()
  const history = useHistory()
  const { draftQuoteId } = useParams()

  const [showShareSheet, setShowShareSheet] = useState(false)
  const [activeTab, setActiveTab] = useState(that.current.tabsData[0])
  const [showTerms, setShowTerms] = useState(false)
  const [showEditQuote, setShowEditQuote] = useState({
    editSection: '',
    show: false,
  })
  const [claimDetails, setClaimDetails] = useState({
    claimId: null,
    claimStatus: null,
  })

  const [{ getPackageDetailData = {} }, getPkgDetailsReq] = useGetPkgDetail()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [{ completeDraftQuoteData }, completeDraftQuoteReq] = useCompleteDraftQuote()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{ discount }, updateDiscount] = useUpdateDiscount()
  const [, shareDraftQuoteReq] = useShareDraftQuoteToCustomer()
  const [{ getClaimsListData }, getClaimsListRequest] = useClaimsList()
  const [{ getAgentDetailData, isGuardianAgentLogin }] = useGlobalContextValue()
  const [
    {
      GET_PACKAGE_DETAIL_LOADER,
      COMPLETE_DRAFT_QUOTE_LOADER,
      UPDATE_DRAFT_QUOTATION_LOADER,
      SHARE_DRAFT_QUOTE_LOADER,
      DRAFT_QUOTATIONS_DETAILS_LOADER,
    },
  ] = useLoaderContextValue()
  const [
    {
      getPackageDetailStatus,
      draftQuotationsDetailsStatus,
      completeDraftQuoteStatus,
      completeDraftQuoteStatusCode,
      completeDraftQuoteErrorData,
      shareDraftQuoteStatus,
      getClaimsListStatus,
    },
  ] = useErrorContextValue()
  const { resetError } = useResetError()

  const [policy, setPolicy] = useState(() => {
    return draftQuotationsDetailsData.policy_details
      ? getMappedQuoteToPolicyData(draftQuotationsDetailsData.policy_details)
      : policyData
  })

  const { isRenewable, handleCreateMvRenewalPolicy } = useRenewalPolicy()

  const isAllowedPaymentBtn = useMemo(() => {
    if (isMVDraftDetail) return true
    if (isPolicyDetail) {
      if (
        policy.policy_status === 'PENDING_DORMANT_COVERAGE' &&
        productCode === EXTENDED_WARRANTY_PROTECTION
      ) {
        return false
      }

      return (
        !['PROVISIONAL_ISSUED', 'PENDING'].includes(policy.policy_status) ||
        ['COMPLETED', 'PROOF_SUBMITTED'].includes(policy.payment_status)
      )
    }
    return false
  }, [policy, isPolicyDetail, isMVDraftDetail, productCode])

  const isHidePaymentBtn = useMemo(() => {
    if (isMVDraftDetail) return true
    if (isPolicyDetail) {
      return ['COMPLETED', 'PROOF_SUBMITTED'].includes(policy.payment_status)
    }
    return false
  }, [policy, isPolicyDetail, isMVDraftDetail])

  const savedDraftData = useRef({})
  const updateDraftTimer = useRef()
  const discountRef = useRef({
    pkgCallTimer: '',
  })
  const draftPrevSteps = useDraftPrevSteps()

  useEffect(() => {
    if (policy.application_no && process.env.REACT_APP_SHOW_CLAIM === 'true') {
      getClaimsListRequest({ applicationNo: policy.application_no })
    }
  }, [policy.application_no, getClaimsListRequest])

  useEffect(() => {
    if (!isPolicyDetail) {
      getDraftQuoteDetailsReq({
        draftQuoteId: draftQuoteId,
      })
    }
  }, [getDraftQuoteDetailsReq, draftQuoteId, isPolicyDetail])

  useEffect(() => {
    if (draftQuotationsDetailsStatus === 'success' && draftQuotationsDetailsData?.policy_details) {
      if (isMVDraftDetail) {
        if (draftQuotationsDetailsData?.policy_application_id) {
          history.replace(
            `/transactions/${draftQuotationsDetailsData.policy_application_id}/details`
          )
          return
        }
        that.current.section = draftQuotationsDetailsData.section
        that.current.subSection = draftQuotationsDetailsData.sub_section
        const sectionData = MV_QUOTE_STEPS_SECTIONS[draftQuotationsDetailsData.section] || {}
        const tabsData = [...that.current.tabsData]
        that.current.tabsData = tabsData.filter((item) => sectionData.tabsData[item.value])
      }
      setPolicy(getMappedQuoteToPolicyData(draftQuotationsDetailsData.policy_details))
      resetError(['draftQuotationsDetailsStatus'])
    }

    if (completeDraftQuoteStatus === 'success' && !!completeDraftQuoteData?.id) {
      gTagOnQuoteCreatedBy(
        isGuardianAgentLogin
          ? QUOTE_CREATED_BY.PIC_SUBMITTED_QUOTE
          : QUOTE_CREATED_BY.SELF_SUBMITTED_QUOTE,
        getAgentDetailData.agent_code,
        CAR_PROTECTION
      )
      resetError(['completeDraftQuoteStatus'])
      history.push(`/payment/car-protection/${completeDraftQuoteData.id}`)
    } else if (completeDraftQuoteStatusCode === 500) {
      ShowSnackbar.error({
        text: extractValues(completeDraftQuoteStatus),
        visible: true,
      })
      resetError([
        'completeDraftQuoteStatus',
        'completeDraftQuoteErrorData',
        'completeDraftQuoteStatusCode',
      ])
    } else if (completeDraftQuoteErrorData) {
      ShowSnackbar.error({
        text: extractValues(completeDraftQuoteErrorData),
        visible: true,
      })
      resetError(['completeDraftQuoteStatus', 'completeDraftQuoteErrorData'])
    }

    if (getClaimsListStatus === 'success' && size(getClaimsListData?.data)) {
      const [firstItem] = getClaimsListData?.data
      if (firstItem) {
        const { claim_id: claimId, status: claimStatus } = firstItem
        setClaimDetails({
          claimId,
          claimStatus,
        })
      }
      resetError(['getClaimsListStatus'])
    }
  }, [
    draftQuotationsDetailsStatus,
    draftQuotationsDetailsData,
    history,
    completeDraftQuoteStatus,
    draftQuoteId,
    resetError,
    completeDraftQuoteData,
    getClaimsListData,
    isMVDraftDetail,
    getClaimsListStatus,
    isGuardianAgentLogin,
    getAgentDetailData,
    completeDraftQuoteErrorData,
    completeDraftQuoteStatusCode,
  ])

  useEffect(() => {
    if (shareDraftQuoteStatus === 'success') {
      setShowShareSheet(false)
      history.push(`/send/draft/quote/success/${draftQuoteId}`)
      resetError(['shareDraftQuoteStatus'])
    } else if (shareDraftQuoteStatus) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: shareDraftQuoteStatus,
        })
      }
      resetError(['sendQuotationStatus'])
    }
  }, [shareDraftQuoteStatus, draftQuoteId, history, resetError])

  const handleShowQuotationModal = useCallback(() => {
    setShowShareSheet(true)
  }, [])

  const handleSendQuote = useCallback(() => {
    const body = {
      customer_data: {
        ...policy?.customer_data,
      },
      draft_id: draftQuoteId,
    }
    shareDraftQuoteReq({
      body,
    })
  }, [shareDraftQuoteReq, draftQuoteId, policy])

  const handleTabClick = useCallback((selectedTab) => {
    setActiveTab(selectedTab)
  }, [])

  const handleSaveDraft = useCallback(
    (extraData = {}, timer) => {
      savedDraftData.current = {
        ...draftQuotationsDetailsData.policy_details,
        ...savedDraftData.current,
        ...extraData,
      }
      if (updateDraftTimer.current) {
        clearTimeout(updateDraftTimer.current)
        updateDraftTimer.current = ''
      }
      if (extraData.package_data) {
        const pkgData = {
          ...extraData.package_data,
        }
        delete pkgData.vehicle_type
        savedDraftData.current = {
          provider_branch: pkgData?.provider_branch || pkgData?.provider?.headquarter_branch,
          ...savedDraftData.current,
          ...savedDraftData.current.addons_data,
          ...pkgData,
        }
        delete savedDraftData.current.tnc
        delete savedDraftData.current.add_ons
        delete savedDraftData.current.premium_breakup
        delete savedDraftData.current.claims
        delete savedDraftData.current.benefit
        delete savedDraftData.current.common_deductible_content
      }
      updateDraftTimer.current = setTimeout(() => {
        updateDraftQuoteReq({
          body: {
            section: isReviewQuote ? 'mv_quote_summary' : that.current.section,
            sub_section: isReviewQuote ? 'mv_quote_summary' : that.current.subSection,
            data: savedDraftData.current,
          },
          draftQuoteId,
        })
      }, timer || 3000)
      // update the new values to local policy
      setPolicy(getMappedQuoteToPolicyData(savedDraftData.current))
    },
    [updateDraftQuoteReq, draftQuoteId, draftQuotationsDetailsData, isReviewQuote]
  )

  const handleEditClick = useCallback((data, subSection, section) => {
    that.current.subSection = subSection
    that.current.section = section
    setShowEditQuote({
      show: true,
      editSection: data,
    })
  }, [])

  const handlePayment = useCallback(
    (data) => {
      // handle the payment
      if (isPolicyDetail) {
        onPaymentClick({ discount, isDiscountChange: discount !== undefined })
        // history.push(`/payment/car-protection/${policyData.id}`)
        return
      }
      handleSaveDraft({ discount: paymentInfoRef?.current?.getDiscount() }, 1)
      setShowTerms(true)
    },
    [isPolicyDetail, discount, onPaymentClick, handleSaveDraft]
  )

  const handleWaitingPage = useCallback(() => {
    history.push(`/payment/status/paylater/${policyData?.id}`)
  }, [history, policyData])

  const handleEndorsementDetails = useCallback(() => {
    paymentRef.current.showEndorsementDetails(true)
    const ele = document.getElementById('endorsementInfo')
    ele.scrollIntoView({
      behavior: 'smooth',
      inline: 'nearest',
    })
  }, [])

  const handleNext = useCallback(() => {
    completeDraftQuoteReq({
      draftQuoteId,
    })
  }, [draftQuoteId, completeDraftQuoteReq])

  const handleToPrevious = useCallback(() => {
    draftPrevSteps({
      section: draftQuotationsDetailsData.section,
      subSection: draftQuotationsDetailsData.sub_section,
      id: draftQuoteId,
    })
  }, [draftQuoteId, draftPrevSteps, draftQuotationsDetailsData])

  useEffect(() => {
    if (getPackageDetailStatus === 'success' && discountRef.current.updateDiscount) {
      discountRef.current.updateDiscount = false
      handleSaveDraft(
        {
          discount: discountRef.current.discount,
          package_data: getPackageDetailData,
        },
        1
      )
      resetError(['getPackageDetailStatus'])
    }
  }, [getPackageDetailStatus, getPackageDetailData, handleSaveDraft, resetError])

  const handleDiscountChange = ({ discount }) => {
    // handle the discount changes

    if (isPolicyDetail) {
      updateDiscount(discount)
    } else {
      if (discountRef.current.pkgCallTimer) {
        clearTimeout(discountRef.current.pkgCallTimer)
      }
      discountRef.current.pkgCallTimer = setTimeout(() => {
        clearTimeout(discountRef.current.pkgCallTimer)
        discountRef.current.updateDiscount = true
        discountRef.current.discount = discount
        getPkgDetailsReq({
          body: {
            ...getPackagesReqBody(policy),
            ...getExtraVehicleData(policy),
            discount,
          },
          packageCode: policy.provider_package_code,
        })
      }, 600)
    }
  }

  return (
    <CircularLoader
      isLoading={
        DRAFT_QUOTATIONS_DETAILS_LOADER ||
        GET_PACKAGE_DETAIL_LOADER ||
        COMPLETE_DRAFT_QUOTE_LOADER ||
        UPDATE_DRAFT_QUOTATION_LOADER
      }
    >
      <MVQuoteReviewStyle isPolicyDetail={isPolicyDetail} height={height}>
        <ProductInfo
          policy={policy}
          claimDetails={claimDetails}
          isMVDraftDetail={isMVDraftDetail}
          onEndorsementDetails={handleEndorsementDetails}
        />
        <>
          <TabsWithIcon
            data={that.current.tabsData}
            defaultTab={activeTab}
            onClick={handleTabClick}
            isSticky
            top={top || '0'}
          />
          {activeTab.value === 'policyDetails' && (
            <PolicyDetailSection
              policy={policy}
              paymentRef={paymentRef}
              className="quote-section"
            />
          )}
          {activeTab.value === 'protection' && (
            <>
              <QuoteProtectionSection
                policy={policy}
                isPolicyDetail={isPolicyDetail}
                className="quote-section"
              />
              <VehicleCriteria
                isPolicyDetail={isPolicyDetail}
                policy={policy}
                className="quote-section"
              />
              <QuoteVehicleModifications
                policy={policy}
                isPolicyDetail={isPolicyDetail}
                className="quote-section"
              />
            </>
          )}
          {activeTab.value === 'pkgInsurance' && (
            <>
              <QuotePkgSection
                policy={policy}
                isPolicyDetail={isPolicyDetail}
                className="quote-section"
                onSaveDraft={handleSaveDraft}
                isReviewPage={!isPolicyDetail}
              />
            </>
          )}
          {activeTab.value === 'insuredObject' && (
            <>
              <VehicleDocumentAndDetails
                className="quote-section"
                policy={policy}
                isPolicyDetail={isPolicyDetail}
                onEditClick={handleEditClick}
              />
            </>
          )}
          {activeTab.value === 'customerData' && (
            <>
              <QuoteCustomerData
                policy={policy}
                isPolicyDetail={isPolicyDetail}
                className="quote-section"
                onEditClick={handleEditClick}
              />
            </>
          )}
        </>
        {isMVDraftDetail && (
          <BottomActionContainerStyle padding="0">
            <div className="btn-wrapper">
              <Button color={AgentColorPallette.darkCharcoal} onClick={handleToPrevious}>
                {LANG_STRINGS.previousContinue}
              </Button>
            </div>
          </BottomActionContainerStyle>
        )}
        {!isHidePaymentBtn && (
          <>
            <PolicyPaymentInfo
              policy={{
                ...policy,
                discount: discount !== undefined ? discount : policy.discount,
              }}
              isPolicyDetail={isPolicyDetail}
              btnText={LANG_STRINGS.payment}
              discountPercent={policy?.product?.discount_percentage}
              maxDiscount={policy?.product?.max_discount}
              commission={policy?.agent_commission}
              onBuyClick={!isAllowedPaymentBtn ? handlePayment : handleWaitingPage}
              onShareClick={handleShowQuotationModal}
              isShareBtn
              showDiscount={isShowEditDiscount || !isPolicyDetail}
              ref={paymentInfoRef}
              grey={isAllowedPaymentBtn}
              onSaveDraft={handleSaveDraft}
              discountLoader={GET_PACKAGE_DETAIL_LOADER}
              onDiscountChange={handleDiscountChange}
            />
            {showShareSheet && (
              <ShareQuotation
                show={showShareSheet}
                onClose={() => setShowShareSheet(false)}
                onSend={handleSendQuote}
                preFilledData={policy?.customer_data}
                loader={SHARE_DRAFT_QUOTE_LOADER}
              />
            )}
          </>
        )}
        {showTerms && (
          <MVReviewTermsConditions
            show={showTerms}
            onClose={() => setShowTerms(false)}
            tncData={policy?.product?.tnc?.data}
            onAcceptClick={handleNext}
          />
        )}
        {showEditQuote.show && (
          <EditMVPolicyQuote
            show={showEditQuote.show}
            onClose={() => setShowEditQuote(false)}
            policy={policy}
            onSave={(data, timer) => handleSaveDraft(data, timer || 1)}
            editSection={showEditQuote.editSection}
          />
        )}
        {isPolicyDetail && isRenewable(policy) && (
          <RenewalButtonContainer>
            <Button variant="filled" onClick={() => handleCreateMvRenewalPolicy(policy)}>
              {LANG_STRINGS.renewalPolicy}
            </Button>
          </RenewalButtonContainer>
        )}
      </MVQuoteReviewStyle>
    </CircularLoader>
  )
}

export default MVQuoteReviewContainer
