import { useEffect, useMemo, useState } from 'react'
import { useHistory } from 'react-router'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import DateBottomSheet from '../../../../../components/DateBottomSheet'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { dateAdd } from '../../../../../helpers/formatDate'
import { NEW_ARROW_RIGHT, INFO_CIRCLE_FIRERED } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import PaymentTime from '../../../../Public/Customer/CustomerPolicySummary/components/PaymentTime'
import { useUpdatePolicyStartDate } from '../../state/hooks/usePolicyState'
import { TRANSACTION_CHANGE_STATUS } from '../../constants'
import { TransactionPaymentHeaderStyle } from './index.style'
import { usePaymentStatus } from '../../hooks/payment/usePaymentStatus'

function TransactionPaymentHeader({ policy }) {
  const history = useHistory()
  const { isPaymentActive, isUsingPaylater, hasDoPayment, isPolicyRejected } =
    usePaymentStatus(policy)
  const [showChangeStartDate, setShowChangeStartDate] = useState(false)

  const [, updatePolicyStartDateReq] = useUpdatePolicyStartDate()
  const [{ updatePolicyStartDateStatus, updatePolicyStartDateErrorData }] = useErrorContextValue()
  const [{ UPDATE_POLICY_START_DATE_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const isChangeToPaylaterAllowed = useMemo(() => {
    return (
      !hasDoPayment &&
      // to know if the product is allowed to use paylater
      policy?.pay_later_enabled &&
      // to know if the policy is already using paylater
      !policy.use_pay_later &&
      TRANSACTION_CHANGE_STATUS.includes(policy.status)
    )
  }, [policy])

  const handleChangeToPaylater = () => {
    history.push(`/transaction/type/${policy?.id}`)
  }

  const handleChangeStartDate = (date) => {
    updatePolicyStartDateReq({
      policyId: policy?.id,
      body: {
        application_date: policy?.application_date,
        start_date: date,
      },
    })
  }

  useEffect(() => {
    if (!updatePolicyStartDateStatus) return

    if (updatePolicyStartDateStatus === 'success') {
      setShowChangeStartDate(false)
      ShowSnackbar.success({ text: 'Berhasil mengubah tanggal mulai polis' })
      resetError(['updatePolicyStartDateStatus'])
    } else {
      setShowChangeStartDate(false)
      ShowSnackbar.error({ text: updatePolicyStartDateErrorData?.error })
      resetError(['updatePolicyStartDateStatus'])
    }
  }, [resetError, updatePolicyStartDateStatus, updatePolicyStartDateErrorData])

  return (
    <TransactionPaymentHeaderStyle>
      {!hasDoPayment && (
        <>
          {isPaymentActive ? (
            <>
              <div className="timer-section ppw-active">
                <div>Batas Waktu Pembayaran</div>
                <PaymentTime
                  scenario="inline"
                  time={policy.application_date}
                  expiryDate={policy.payment_period?.end_date}
                />
              </div>
              <div className="info-section ppw-active">
                <img src={INFO_CIRCLE_FIRERED} alt="" />
                <div>Lakukan pembayaran sekarang sebelum waktu pembayaran berakhir.</div>
              </div>
            </>
          ) : (
            <>
              <div className="timer-section ppw-expired">
                <div>Batas Waktu Pembayaran</div>
                <div>00D : 00H : 00M: 00S</div>
              </div>
              <div className="info-section ppw-expired">
                <div>
                  {`Polis telah batal secara otomatis dikarenakan tidak ada pembayaran dalam waktu ${policy?.payment_period?.total_days || 0} hari.`}
                  {/* enable next feature ppw*/}
                  {/* {isCanUpdatePolicyStartDate
                    ? `Waktu pembayaran telah berakhir. Silakan pilih tanggal mulai
                  polis baru untuk mengaktifkan pembayaran kembali.`
                    : 'Waktu pembayaran telah berakhir.'}*/}
                </div>
              </div>
              {/* enable next feature ppw*/}
              {/* {isCanUpdatePolicyStartDate && (
                <div className="change-start-date-section">
                  <Button
                    variant="filled"
                    disabled
                    onClick={() => setShowChangeStartDate(true)}
                  >
                    Pilih Tanggal mulai Polis
                  </Button>
                </div>
              )}*/}
            </>
          )}
        </>
      )}

      {isChangeToPaylaterAllowed && isPaymentActive && (
        <div className="paylater-section" onClick={handleChangeToPaylater}>
          <div>Ubah metode pembayaran menjadi Paylater</div>
          <img src={NEW_ARROW_RIGHT} alt="" />
        </div>
      )}
      <DateBottomSheet
        show={showChangeStartDate}
        title={LANG_STRINGS.policyStartDate}
        subtitle="Tanggal mulai polis maksimal adalah 30 hari dari tanggal pengajuan polis."
        minDate={policy?.policy_detail?.start_date}
        maxDate={dateAdd(policy?.policy_detail?.start_date, 30, 'days')}
        onClose={() => setShowChangeStartDate(false)}
        onSubmit={handleChangeStartDate}
        submitLoading={UPDATE_POLICY_START_DATE_LOADER}
      />
    </TransactionPaymentHeaderStyle>
  )
}

export default TransactionPaymentHeader
