export const getCommissionStyle = (status) => {
  const statusUpper = status?.toUpperCase()
  switch (statusUpper) {
    case 'PENDING':
      return { color: '#FFC800', textDecoration: 'none' }
    case 'PAID':
      return { color: '#00B432', textDecoration: 'none' }
    case 'CANCELLED':
      return { color: '#FA3232', textDecoration: 'line-through' }
    default:
      return { color: '#333', textDecoration: 'none' }
  }
}
