import BottomActionSheet from '../../../BottomActionSheet'
import { PaymentBottomSheetStyle } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import { Row } from '../../../../commonStyle/index.style'
import { CustomText } from '../../..'
import { formatMoney } from '../../../../helpers/utility'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { forwardRef, useEffect } from 'react'
import PaymentBreakup from '../PaymentBreakup'

function PaymentBottomSheet ({
  show, onClose, paymentMap, policy, showDiscount,
  discountPercent, maxDiscount, commission, loader = false, setDisabled = () => {},
  onDiscountChange = () => {}, isUseInstalment, instalmentPayment, showFinalCommissionWord
}, parentRef) {
  useEffect(() => {
    if (show) {
      document.body.style.overflowY = 'hidden'
    }

    return () => {
      document.body.style.overflowY = 'auto'
    }
  }, [show])

  return (
    <PaymentBottomSheetStyle>
      <BottomActionSheet
        loader={loader}
        show={show}
        onCloseSheet={onClose}
        headerTextAlign='start'
        bottom='58px'
        title={
          <div className='payment-header'>
            <span className='payment-total-bill'>
              {isUseInstalment ? `${LANG_STRINGS.totalBill} ${LANG_STRINGS.instalment} ${instalmentPayment?.serial_number}` : LANG_STRINGS.totalBill}
            </span>
            <Row justify='space-between'>
              <CustomText
                color={AgentColorPallette.blackGrey}
                size='0.9em'
                weight={700}
              >
                {
                  formatMoney((policy.total_bill), 0)
                }
              </CustomText>
            </Row>
          </div>
        }
        showHeader
      >
        <div className='payment-amount-container'>
          <PaymentBreakup
            paymentMap={paymentMap}
            policy={policy}
            isUseInstalment={isUseInstalment}
            instalmentPayment={instalmentPayment}
            showDiscount={showDiscount}
            maxDiscount={maxDiscount}
            commission={commission}
            discountPercent={discountPercent}
            setDisabled={setDisabled}
            onDiscountChange={onDiscountChange}
            ref={parentRef}
            showFinalCommissionWord={showFinalCommissionWord}
          />
        </div>
      </BottomActionSheet>
    </PaymentBottomSheetStyle>
  )
}

export default forwardRef(PaymentBottomSheet)
