import QuoteSection from '../QuoteSections'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { useMemo, useCallback } from 'react'
import moment from 'moment'

function QuoteCustomerData ({ policy, className, onEditClick, isPolicyDetail }) {
  const document = useMemo(() => {
    const { customer_data: customerData = {} } = policy
    return [
      {
        title: LANG_STRINGS.ktpNumber,
        value: customerData.ktp_no || policy.ktp_no
      },
      {
        title: LANG_STRINGS.photoKTP,
        type: 'img',
        value: customerData?.ktp?.ktp || customerData?.ktp_url || policy.ktp_url
      }
    ]
  }, [policy])

  const customerInfo = useMemo(() => {
    const { customer_data: customerData } = policy
    return [
      {
        title: LANG_STRINGS.fullNameAsPerKtp,
        value: customerData?.name
      },
      {
        title: LANG_STRINGS.customerPhone,
        value: customerData?.mobile_no
      },
      {
        title: LANG_STRINGS.emailAddress,
        value: customerData?.email
      }
    ]
  }, [policy])

  const customerAddress = useMemo(() => {
    const { customer_data: customerData } = policy
    return [
      {
        title: LANG_STRINGS.province,
        value: customerData?.customer_address?.province_name
      },
      {
        title: LANG_STRINGS.city,
        value: customerData?.customer_address?.city_name
      },
      {
        title: LANG_STRINGS.postalCode,
        value: customerData?.customer_address?.postal_code
      },
      {
        title: LANG_STRINGS.address,
        value: customerData?.customer_address?.address
      }
    ]
  }, [policy])

  const hardCopy = useMemo(() => {
    let recipientInfo = []
    const receiptInfo = []
    let opsDetails = []
    const insuranceDetails = policy?.insurance_details
    const hardCopyDeliveryDate = insuranceDetails?.hard_copy_details.delivery_date
    const hardCopyReceiveDate = insuranceDetails?.hard_copy_details.receive_date
    // const hardCopyAddress = insuranceDetails?.hard_copy_address

    if (insuranceDetails) {
      receiptInfo.push(
        {
          title: LANG_STRINGS.receiptNumber,
          value: insuranceDetails?.hard_copy_details?.courier_partner_order_id
        }
      )
    }
    if (policy.hard_copy_recipient && policy.hard_copy_recipient_mobile) {
      recipientInfo = [
        {
          title: LANG_STRINGS.recipientName,
          value: policy.hard_copy_recipient
        },
        {
          title: LANG_STRINGS.activeMobileNumber,
          value: policy.hard_copy_recipient_mobile
        }
      ]
    }
    if (insuranceDetails) {
      opsDetails = [
        {
          title: LANG_STRINGS.receiveFromProvider,
          value: hardCopyReceiveDate ? moment(hardCopyReceiveDate).format('DD MMMM YYYY') : '-'
        },
        {
          title: LANG_STRINGS.policySubmitDate,
          value: hardCopyDeliveryDate ? moment(hardCopyDeliveryDate).format('DD MMMM YYYY') : '-'
        },
        {
          title: LANG_STRINGS.policyReceiver,
          value: insuranceDetails?.hard_copy_details.recipient_name
        },
        {
          title: LANG_STRINGS.activeMobileNumber,
          value: insuranceDetails?.hard_copy_details.recipient_mobile
        },
        {
          title: LANG_STRINGS.typeOfDelivery,
          value: insuranceDetails?.hard_copy_details.delivery_type
        },
        {
          title: LANG_STRINGS.remarksSubmitted,
          value: insuranceDetails?.hard_copy_details.remark
        }
      ]
    }
    return [
      ...receiptInfo,
      {
        title: LANG_STRINGS.shippingOption,
        value: policy.hard_copy_sent_to_name
      },
      {
        title: LANG_STRINGS.province,
        value: policy.hard_copy_address?.province_name
      },
      {
        title: LANG_STRINGS.city,
        value: policy.hard_copy_address?.city_name
      },
      {
        title: LANG_STRINGS.postalCode,
        value: policy.hard_copy_address?.postal_code
      },
      {
        title: LANG_STRINGS.shippingAddress,
        value: policy.hard_copy_address?.address
      },
      ...recipientInfo,
      ...opsDetails
    ]
  }, [policy])

  const surveyResponse = useMemo(() => {
    if (!policy.survey_response) return []
    if (policy.survey_response?.map) {
      return policy.survey_response?.map(item => {
        return {
          title: item.head,
          value: item.value
        }
      })
    }
    const res = []
    for (const key in policy.survey_response) {
      const item = policy.survey_response[key]
      if (Object.hasOwnProperty.call(item.value, 'address')) {
        res.push({
          title: LANG_STRINGS.province,
          value: item.value.province_name
        })
        res.push({
          title: LANG_STRINGS.city,
          value: item.value.city_name
        })
        res.push({
          title: LANG_STRINGS.postalCode,
          value: item.value.postal_code
        })
        res.push({
          title: LANG_STRINGS.address,
          value: item.value.address
        })
      } else {
        res.push({
          title: item.head,
          value: item.value
        })
      }
    }
    return res
  }, [policy])

  const handleEditClick = useCallback((section, subSection) => {
    onEditClick({
      section
    }, subSection, 'customer_data')
  }, [onEditClick])

  return (
    <>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.document}
          data={document}
          onEditClick={() => handleEditClick(LANG_STRINGS.customerDocument, 'customer_document')}
          isEdit={!isPolicyDetail}
        />
      </div>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.nameAndContactInfo}
          data={customerInfo}
          onEditClick={() => handleEditClick(LANG_STRINGS.nameAndContactInfo, 'customer_information')}
          isEdit={!isPolicyDetail}
        />
      </div>
      <div className={className}>
        <QuoteSection
          title={LANG_STRINGS.residenceAddress}
          data={customerAddress}
          onEditClick={() => handleEditClick(LANG_STRINGS.residenceAddress, 'customer_address')}
          isEdit={!isPolicyDetail}
        />
      </div>
      {
        (isPolicyDetail ? policy.hard_copy_required : true) && (
          <div className={className}>
            <QuoteSection
              title={LANG_STRINGS.printPolicy}
              data={hardCopy}
              onEditClick={() => handleEditClick(LANG_STRINGS.printPolicy, 'hard_copy')}
              isEdit={!isPolicyDetail}
              marginBtm={policy.survey_response ? '0' : '20%'}
            />
          </div>
        )
      }
      {
        policy.survey_response && (
          <div className={className}>
            <QuoteSection
              title={LANG_STRINGS.vehicleSurvey}
              data={surveyResponse}
              onEditClick={() => handleEditClick(LANG_STRINGS.vehicleSurvey, 'vehicle_survey')}
              isEdit={!isPolicyDetail}
              marginBtm='20%'
            />
          </div>
        )
      }
    </>
  )
}

export default QuoteCustomerData
