import { get } from 'lodash'
import isEmpty from 'lodash/isEmpty'
import moment from 'moment'
import { useCallback } from 'react'
import { CustomText } from '../../../../../components'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { HEALTH_FULL_PROTECTION, PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'
import { getPolicyStatus, paymentStatusBahasa, POLICY_TYPE } from '../../../../../helpers/data'
import { formatMoney } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import TransactionInfoCard from '../TransactionInfoCard'
import { PolicyInfoCardStyle } from './index.style'

function PolicyInfoCard (props) {
  const {
    policy, isRenewalPolicyFlow, className,
    isCollapsible = false, isShowJenisType = true
  } = props
  const isPropertyPolicy = get(policy, 'policy_detail.product_code', '') === PROPERTY_PROTECTION

  const handleClick = useCallback((path) => {
    // handle click data
    props.history.push({
      pathname: path
    })
  }, [props.history])

  const renderBenifitFWD = useCallback((benefit) => {
    return (
      benefit.map((terms, index) => {
        return (
          <>
            {
              terms.title &&
                <CustomText
                  color={AgentColorPallette.black}
                  size='14px'
                  key={`terms_${index}`}
                  weight={800}
                  className='pl-35'
                >
                  {terms.title}
                </CustomText>
            }
            {
              !isEmpty(terms) &&
                <ul className='m-0'>
                  {
                    terms.terms.map((term, i) => {
                      return (
                        <li key={i}>
                          <CustomText
                            color={AgentColorPallette.black}
                            size='13px'
                            key={`termssub_${index}`}
                          >
                            {term}
                          </CustomText>
                        </li>
                      )
                    })
                  }
                </ul>
            }
            {
              terms.description &&
                <CustomText
                  color={AgentColorPallette.fontDarkerGrey}
                  size='10px'
                  bottom='20px'
                  key={`terms_${index}`}
                  className='pl-35'
                >
                  {terms.description}
                </CustomText>
            }
          </>
        )
      })
    )
  }, [])

  const renderPolicyDetail = useCallback(() => {
    const policyStatus = getPolicyStatus(policy?.expired ? 'EXPIRED' : policy.policy_status)
    const purchaseType = policy?.policy_detail?.purchase_type
    const insuranceDetails = policy?.insurance_details || {}
    const productCode = policy?.product?.package?.product?.code || ''
    const isHealthProtection = (productCode === HEALTH_FULL_PROTECTION)

    let newRenewalData = []
    if (isRenewalPolicyFlow && insuranceDetails.child_data?.app_no) {
      newRenewalData = [
        ...newRenewalData,
        {
          head: LANG_STRINGS.renewalPolicy,
          newline: true,
          onClick: () => handleClick(`/transactions/${insuranceDetails.child_data?.reference_id}/details`),
          value: insuranceDetails.child_data?.app_no
        },
        {
          head: LANG_STRINGS.extendedPolicyStatus,
          value: getPolicyStatus(insuranceDetails.child_data?.policy_status).text
        },
        {
          head: LANG_STRINGS.renewalPolicyPaymentStatus,
          value: paymentStatusBahasa(insuranceDetails.child_data?.payment_status)
        }
      ]
    }
    // TODO: Need to check details Data
    if (purchaseType === 'renew-purchase') {
      newRenewalData.push({
        head: LANG_STRINGS.policyExtensionFrom,
        newline: true,
        onClick: () => handleClick(`/transactions/${insuranceDetails.parent_data?.reference_id}/details`),
        value: insuranceDetails.parent_data?.app_no
      })
    }
    return {
      heading: `${LANG_STRINGS.policyDetail}`,
      items: [
        ...(
          isShowJenisType ? [{
            head: LANG_STRINGS.policyType,
            newline: true,
            value: POLICY_TYPE[purchaseType]
          }] : []
        ),
        ...newRenewalData,
        {
          head: LANG_STRINGS.policyStatus,
          value: policyStatus.text,
          color: policyStatus.color
        },
        {
          head: LANG_STRINGS.yearlyPremium,
          value: formatMoney(get(policy, 'product.sub_total', 0) - policy.discount, 0),
          color: AgentColorPallette.mustard
        },
        {
          head: LANG_STRINGS.policyNumber,
          newline: true,
          value: isPropertyPolicy
            ? policy?.application_no
            : get(policy, 'insurance_details.insurance_policy_no', policy?.application_no)
        },
        ...(
          get(policy, 'policy_detail.start_date', '')
            ? [{
              head: LANG_STRINGS.policyStartDate,
              value: moment(get(policy, 'policy_detail.start_date', ''), 'YYYY-MM-DD').format('DD MMMM YYYY')
            }] : []
        ),
        {
          head: LANG_STRINGS.protectionPeriod,
          value: `${get(policy, 'policy_detail.premium.period', 12)} bulan`
        },
        ...(
          !isPropertyPolicy
            ? [{
              head: LANG_STRINGS.benefit,
              value: get(policy, 'product.benefit.data', []),
              render: isHealthProtection
                ? () => (
                  <CollapsibleCard
                    title={LANG_STRINGS.benefit}
                    titleClassName='manfaat-title'
                    className='collapse-card'
                  >
                    {renderBenifitFWD(get(policy, 'product.benefit.data', []))}
                  </CollapsibleCard>
                )
                : false
            }]
            : []
        )
      ]
    }
  }, [isRenewalPolicyFlow, policy, handleClick,
    isShowJenisType, renderBenifitFWD
  ])

  return (
    <PolicyInfoCardStyle>
      <TransactionInfoCard
        data={renderPolicyDetail()}
        isCollapsible={isCollapsible}
        className={className}
      />
    </PolicyInfoCardStyle>
  )
}

export default PolicyInfoCard
