import { isEmpty } from 'lodash'
import { useState } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import TitleError from '../../../../../components/TitleError'
import ZoomImg from '../../../../../components/zoomImg'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PHOTO } from '../../../../../images'
import { BuildingUploadImg } from '../../../../CommonContainer/PropertyDetailForm/components/BuildImgUpload/index.style'
import { BUILDING_IMGS, BUILDING_IMGS_COUNT } from '../../../../CommonContainer/PropertyDetailForm/constants'
import { PROPERTY_LANG } from '../../../Property/lang'
import { PolicyDetailCard } from '../../pages/index.style'

function PropertyImgsInfo (props) {
  const { policy } = props
  const { policy_detail: policyDetails } = policy
  const [isImgsNotUpload, setIsImgsNotUpload] = useState(false)

  const renderImgs = (images = {}, title) => {
    const container = []
    if (isEmpty(images)) {
      if (!isImgsNotUpload) {
        setIsImgsNotUpload(true)
      }
      BUILDING_IMGS_COUNT.forEach(item => {
        container.push(
          <BuildingUploadImg
            url={PHOTO}
            className='building-empty-img'
          />
        )
      })
    }
    for (const key in images) {
      const imgUrl = images[key]
      if (imgUrl) {
        container.push(
          <ZoomImg
            src={imgUrl}
            imgContainer={
              <SingleImgContainer
                minWidth='60px'
                height='60px'
                imgUrl={imgUrl}
                imgClassName='single-img-margin'
                showVerified
              />
            }
            imgClassName='building-img'
          />
        )
      }
    }
    return container
  }

  return (
    <PolicyDetailCard className={isImgsNotUpload && 'border-red'}>
      <CustomText className='item-padding' color={AgentColorPallette.black} weight={800} size='15px'>
        {PROPERTY_LANG.photoOfInsuredObjV2}
      </CustomText>
      <hr />
      <div className='item-padding'>
        {
          BUILDING_IMGS.map(buildingImg => (
            <div key={buildingImg.type}>
              <TitleError title={buildingImg.title} />
              <Row align='center' className='summary-images'>
                {
                  renderImgs(policyDetails[buildingImg.type], buildingImg.title)
                }
              </Row>
            </div>
          ))
        }
      </div>
    </PolicyDetailCard>
  )
}

export default PropertyImgsInfo
