import { useMemo, useCallback } from 'react'
import { useHistory } from 'react-router-dom'
import moment from 'moment'
import MVPremiumBreakdown from '../../../../../../../components/MVPremiumBreakdown'
import CustomText from '../../../../../../../components/CustomText/index'
import { Row } from '../../../../../../../commonStyle/index.style'
import { TRANSACTION_CHANGE_STATUS } from '../../../../constants'
import { PAID_BY, PAYMENT_METHOD } from '../../../../../../../constants/payment'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { getPaymentStatus, getPolicyStatus, POLICY_TYPE } from '../../../../../../../helpers/data'
import { MINI_INFO } from '../../../../../../../images'
import { LANG_STRINGS } from '../../../../../../../lang'
import { usePaymentStatus } from '../../../../hooks/payment/usePaymentStatus'
import QuoteSection from '../QuoteSections'

function PolicyDetailSection({ policy, className, isShowEditDiscount, paymentRef }) {
  const history = useHistory()
  // const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const { hasDoPayment, isPaymentActive } = usePaymentStatus(policy)

  const isChangeTransactionType = useMemo(() => {
    return (
      isPaymentActive &&
      !hasDoPayment &&
      policy?.pay_later_enabled &&
      !policy.use_pay_later &&
      TRANSACTION_CHANGE_STATUS.includes(policy.status)
    )
  }, [policy])

  const policyDetail = useMemo(() => {
    const showTransactionChange =
      policy.pay_later_enabled &&
      !policy.use_pay_later &&
      TRANSACTION_CHANGE_STATUS.includes(policy.status)
    return [
      {
        title: LANG_STRINGS.policyType,
        value: POLICY_TYPE[policy.purchase_type],
      },
      {
        title: LANG_STRINGS.policyStatus,
        value: getPolicyStatus(policy?.expired ? 'EXPIRED' : policy.policy_status).text,
      },
      {
        title: LANG_STRINGS.paymentStatus,
        value: getPaymentStatus(policy.payment_status).text,
      },
      {
        title: LANG_STRINGS.transactionType,
        value: !showTransactionChange
          ? policy.use_pay_later
            ? 'Pay Later'
            : 'Normal'
          : 'mitraNotAvilable',
      },
    ]
  }, [policy])

  const policyPayment = useMemo(() => {
    const paymentCommission = []
    if (policy.proof_upload_time) {
      paymentCommission.push({
        title: LANG_STRINGS.paymentUploadTime,
        value: moment(policy.proof_upload_time).format('DD/MM/YYYY - HH:MM:SS'),
      })
    }
    return [
      {
        title: LANG_STRINGS.paymentBy,
        value: PAID_BY[policy.payment_by],
      },
      {
        title: LANG_STRINGS.paymentMethod,
        value: PAYMENT_METHOD[policy.payment_method] || '-',
      },
      {
        title: policy?.payment_date ? LANG_STRINGS.paymentDate : LANG_STRINGS.transactionDate,
        value: policy?.payment_date
          ? moment(policy.payment_date).format('DD MMMM YYYY')
          : policy.transaction_date
            ? moment(policy.transaction_date).format('DD MMMM YYYY')
            : '',
      },
      ...paymentCommission,
    ]
  }, [policy])

  const handleChangeTransaction = useCallback(() => {
    // open change transaction Page
    history.push({
      pathname: `/transaction/type/${policy?.id}`,
    })
  }, [history, policy])

  return (
    <>
      <div className={className}>
        <QuoteSection title={LANG_STRINGS.policyDetail} data={policyDetail} />
        {isChangeTransactionType && (
          <Row align="start">
            <div>
              <img src={MINI_INFO} alt="" />
              &nbsp;&nbsp;
            </div>
            <div>
              <CustomText fontColor={AgentColorPallette.fontGrey} size="0.75em">
                {LANG_STRINGS.changeTransactionType}
              </CustomText>
              <CustomText
                fontColor={AgentColorPallette.buddhaGold}
                size="0.7em"
                weight={700}
                top="4px"
                className="text-uppercase"
                onClick={handleChangeTransaction}
              >
                {LANG_STRINGS.changeToPayLater}
              </CustomText>
            </div>
          </Row>
        )}
      </div>
      <div className={className}>
        <QuoteSection title={LANG_STRINGS.transactionDetails} data={policyPayment} />
        {policy.commission_disbursement_time && (
          <Row align="start" className="margin-btm">
            <div>
              <img src={MINI_INFO} alt="" />
              &nbsp;&nbsp;
            </div>
            <CustomText fontColor={AgentColorPallette.fontGrey} size="0.75em">
              {LANG_STRINGS.yourCommissionMaxDisburseOnTheDate}&nbsp;
              <b>{moment(policy.commission_disbursement_time).format('DD MMMM YYYY, HH:MM:SS')}</b>
            </CustomText>
          </Row>
        )}
        <div className="premium-breakdown-wrapper">
          <MVPremiumBreakdown policyDetails={policy} />
        </div>
      </div>
    </>
  )
}

export default PolicyDetailSection
