import CustomText from '../CustomText'
import { MVPolicyInfoStyle } from './index.style'
import PropTypes from 'prop-types'
import { LANG_STRINGS } from '../../lang'
import { AgentColorPallette } from '../../configs/colorPallete'
import { INFORMATION_NEW } from '../../images'

function MVPolicyInfo (props) {
  const { status, remarks, marginTop = '' } = props

  // TODO: CONFIRM REJECTED STATUS FROM BACKEND
  if (status === 'CANCELLED' || status === 'REJECTED') {
    return (
      <MVPolicyInfoStyle marginTop={marginTop}>
        {
          <div className='remark-box'>
            <div className='info-icon'>
              <img src={INFORMATION_NEW} alt='info' />
            </div>
            <div className='remark-deails'>
              <CustomText
                weight={800}
                size='13px'
                color={AgentColorPallette.black}
              >
                {status === 'REJECTED' ? LANG_STRINGS.policyRejected : LANG_STRINGS.policyCancelled || ''}
              </CustomText>
              <CustomText
                weight={700}
                size='10px'
                top='5px'
                color={AgentColorPallette.black}
              >
                {status === 'REJECTED' ? LANG_STRINGS.policyReasonRejected : LANG_STRINGS.policyReasonCancellation || ''}
              </CustomText>
              <CustomText
                size='13px'
                color={AgentColorPallette.black}
              >
                {remarks?.reason || ''}
              </CustomText>
            </div>
          </div>
        }
      </MVPolicyInfoStyle>
    )
  } else {
    return null
  }
}

MVPolicyInfo.propTypes = {
  remarks: PropTypes.object
}

export default MVPolicyInfo
