import { CustomText, Button } from '../../../../../components'
import DiscountModal from '../../../../../containers/Private/Application/components/DiscountModal'
import AmountTitle from '../../../../../components/AmountTitle'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  formatMoney,
  getConvertedCurrency,
  getTotalPolicyPremium,
} from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyDetailCard } from '../../pages/index.style'
import { Row } from '../../../../../commonStyle/index.style'
import { useState, useEffect, useRef, useCallback, useMemo } from 'react'
import { DOWN_ARROW_GOLD, ImageUrl } from '../../../../../images'
import PolicyActions from '../../../../../redux/policy/action'
import { connect } from 'react-redux'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import InfoBar from '../../../../../components/InfoBar'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { getEndorsementStatus } from '../../constants'
import { FLEET_POLICY, PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'
import { get } from 'lodash'

const { updatePolicyQuotationDiscount, getApplicationDetail, resetPolicyStore } = PolicyActions

function Transactions(props) {
  const {
    policy = {},
    updatePolicyQuotationDiscountMsg,
    updatePolicyQuotationDiscount,
    getApplicationDetail,
    resetPolicyStore,
    isManualOrder,
  } = props
  const isFleetPolicy = useMemo(
    () => policy?.policy_detail.protection_case === FLEET_POLICY,
    [policy]
  )
  const [{ getAgentDetailData = {} }] = useUpdateGlobal()
  const {
    product,
    id,
    status,
    endorsement_discount_status: endorsementDiscountStatus = '',
    total_invoice_before_endorsement: totalInvBeforeEndorsement = '',
    total_premium_change: totalPremiumChange = '',
    total_endorsement_fee: totalEndorsementFee = '',
  } = policy

  const [showDiscountModal, setShowDiscountModal] = useState(false)
  const [showEndorDetail, setShowEndorDetail] = useState(false)
  const [showCurrencyChangeDetails, setShowCurrencyChangeDetails] = useState(false)

  const totalGrey = useRef([
    'PAYMENT_FAILED',
    'PAID',
    'EXPIRED',
    'POLICY_CREATED',
    'POLICY_CREATION_FAILED',
    'PROVISIONAL_FAILED',
    'APPLICATION_CANCELLED',
    'APPLICATION_INVALID',
  ])

  useEffect(() => {
    if (updatePolicyQuotationDiscountMsg === 'success') {
      setShowDiscountModal(false)
      getApplicationDetail({ policyId: id, includeInsuranceDetail: true })
    } else if (updatePolicyQuotationDiscountMsg) {
      NotificationManager.error(updatePolicyQuotationDiscountMsg)
    }
    return () => {
      resetPolicyStore(['updatePolicyQuotationDiscountMsg'])
    }
  }, [updatePolicyQuotationDiscountMsg, id, getApplicationDetail, resetPolicyStore])

  const getTotalPremium = useCallback(
    (applicationDetails) => {
      let tax = 0
      // let agentCommission = 0
      if (applicationDetails.payment_by === 'AGENT' && !getAgentDetailData.advance_balance) {
        tax = applicationDetails.total_tax
      }

      return getTotalPolicyPremium(
        [
          applicationDetails.total_premium, // this array contains summation values
          tax,
        ],
        [
          applicationDetails.discount, // this array contains subtraction values
        ]
      )
    },
    [getAgentDetailData.advance_balance]
  )

  const getAmountTitle = ({
    title,
    amount,
    amountColor,
    prefix = 'Rp',
    titleColor = AgentColorPallette.fontDarkerGrey,
    bgColor = AgentColorPallette.white,
    showText,
    convertAmount = true,
  }) => {
    if (!amount) return null
    if (
      policy.policy_detail.currency_label !== 'IDR' &&
      (isManualOrder || isFleetPolicy) &&
      convertAmount === true &&
      title !== LANG_STRINGS.conversionRate
    ) {
      amount = getConvertedCurrency(amount, policy?.policy_detail.exchange_rate)
      prefix = policy?.policy_detail.currency_symbol
    }
    return (
      <AmountTitle
        color={titleColor}
        amountColor={amountColor || AgentColorPallette.black}
        title={title}
        amountPrefix={prefix}
        size="13px"
        amount={amount}
        className="item-padding"
        bgColor={bgColor}
        showText={showText}
      />
    )
  }

  const handleShowModal = () => {
    setShowDiscountModal(true)
  }

  const handleCloseDiscountModal = () => {
    setShowDiscountModal(false)
  }

  const handleDiscountSubmit = (discount) => {
    updatePolicyQuotationDiscount({
      discount: discount,
      token: policy.id,
    })
  }
  const handleEditDiscount = () => {
    setShowDiscountModal(true)
  }

  const renderDiscount = (title, amount, amountColor) => {
    let showDiscountEdit = true

    switch (policy.status) {
      case 'QUOTATION':
      case 'INITIATED':
      case 'APPLICATION_COMPLETED':
      case 'PAYMENT_PENDING':
        showDiscountEdit = true
        break
      default:
        showDiscountEdit = false
    }

    if (policy.use_pay_later) {
      showDiscountEdit = false
    }

    const productCode =
      get(policy, 'product.package.product.code', '') ||
      get(policy, 'policy_detail.product_code', '')
    if (productCode === PROPERTY_PROTECTION) {
      showDiscountEdit = false
    }

    if (showDiscountEdit || amount) {
      return (
        <div>
          <Row className="item-padding" align="stretch" justify="space-between">
            <CustomText size="13px" color={AgentColorPallette.fontDarkerGrey}>
              {title}{' '}
              {showDiscountEdit && !!amount && (
                <img
                  className="vertical-align-bottom"
                  onClick={handleEditDiscount}
                  width="24px"
                  height="24px"
                  src={ImageUrl.editButtonIcon}
                  alt=""
                />
              )}
            </CustomText>
            <CustomText
              size="13px"
              textAlign="right"
              color={amountColor || AgentColorPallette.regular}
              weight={800}
            >
              {amount ? (
                (isManualOrder || isFleetPolicy) &&
                policy.policy_detail.currency_label &&
                policy.policy_detail.currency_label !== 'IDR' ? (
                  `${policy?.policy_detail.currency_symbol || 'Rp'} ${getConvertedCurrency(amount, policy?.policy_detail.exchange_rate)}`
                ) : (
                  `- ${formatMoney(amount)}`
                )
              ) : (
                <Button className="add-discount-btn" handleClick={handleShowModal}>
                  {' '}
                  {LANG_STRINGS.add}{' '}
                </Button>
              )}
            </CustomText>
          </Row>
          {endorsementDiscountStatus && (
            <div className="item-padding">
              <InfoBar
                text={
                  endorsementDiscountStatus === 'changed'
                    ? LANG_STRINGS.changeInDiscountAfterEndorsement
                    : LANG_STRINGS.additionalDiscountAfterEndorsement
                }
              />
            </div>
          )}
        </div>
      )
    } else {
      return null
    }
  }

  const handleShowEndorsementDetail = () => {
    setShowEndorDetail(true)
  }

  const {
    commission,
    discount_percentage: discountPercent,
    sub_total: subTotal,
    max_discount: maxDiscount,
  } = product
  return (
    <PolicyDetailCard>
      {showDiscountModal && (
        <DiscountModal
          showDiscountModal={showDiscountModal}
          onClose={handleCloseDiscountModal}
          commission={commission}
          maxDiscount={maxDiscount}
          subTotal={subTotal}
          comissionPercent={discountPercent}
          onSubmitDiscount={handleDiscountSubmit}
        />
      )}
      <CustomText
        className="item-padding"
        color={AgentColorPallette.black}
        weight={800}
        size="15px"
      >
        {LANG_STRINGS.transactionDetails}
      </CustomText>
      <hr />
      {getAmountTitle({
        title: LANG_STRINGS.basicPremium,
        amount: isManualOrder || isFleetPolicy ? policy.net_premium : product.basic_premium,
      })}
      {(isManualOrder || isFleetPolicy) &&
        policy?.policy_detail?.currency_symbol &&
        policy?.policy_detail?.currency_symbol !== 'Rp' &&
        getAmountTitle({
          title: LANG_STRINGS.conversionRate,
          amount: `Rp ${policy?.policy_detail.exchange_rate}/${policy?.policy_detail.currency_symbol}1`,
          showText: true,
        })}
      {(isManualOrder || isFleetPolicy) &&
        getAmountTitle({
          title: LANG_STRINGS.additionalPackage,
          amount: policy.policy_detail.additional_sum_insured,
        })}
      {Boolean(totalPremiumChange) &&
        getAmountTitle({
          title: LANG_STRINGS.changeInPremiumAfterEndorsement,
          amount: totalPremiumChange,
          amountColor: AgentColorPallette.orangePink,
          titleColor: AgentColorPallette.orangePink,
        })}
      {!(isManualOrder || isFleetPolicy) &&
        getAmountTitle({ title: LANG_STRINGS.additionalPackage, amount: product.add_on_premium })}
      <hr />
      {getAmountTitle({
        title: LANG_STRINGS.subTotal,
        amount: isManualOrder || isFleetPolicy ? policy.net_premium : product.sub_total,
        titleColor: AgentColorPallette.fontDarkerGrey,
        bgColor: AgentColorPallette.fontLightGrey,
      })}
      <hr />
      {Boolean(totalEndorsementFee) &&
        getAmountTitle({
          title: LANG_STRINGS.totalEndorsementFee,
          amount: totalEndorsementFee,
          amountColor: AgentColorPallette.orangePink,
          titleColor: AgentColorPallette.orangePink,
        })}
      {(product?.fees || policy?.fees || [])?.map((fee, idx) => (
        <div key={fee?.key || idx}>
          {getAmountTitle({ title: fee?.label, amount: fee?.value })}
          <hr />
        </div>
      ))}
      {policy.payment_by === 'AGENT' &&
        !getAgentDetailData.advance_balance &&
        getAmountTitle({ title: LANG_STRINGS.tax, amount: policy.total_tax })}

      {renderDiscount(LANG_STRINGS.discount, policy.discount, AgentColorPallette.errorDark)}
      <hr />
      {policy.payment_by === 'AGENT' &&
        !getAgentDetailData.advance_balance &&
        getAmountTitle({
          title: LANG_STRINGS.transactionCommission,
          amount: policy.current_commission_used
            ? policy.agent_commission - policy.discount
            : policy.current_commission_used,
          amountColor: AgentColorPallette.errorDark,
          prefix: '- Rp ',
        })}
      {getAmountTitle({
        title: LANG_STRINGS.useOfBalance,
        amount: policy.commission_used,
        amountColor: AgentColorPallette.errorDark,
        prefix: '- Rp ',
      })}
      {getAmountTitle({
        title: LANG_STRINGS.useOfPoint,
        amount: policy.point_used,
        titleColor: AgentColorPallette.errorDark,
        prefix: '- Rp ',
      })}
      {!!(policy.commission_used || policy.point_used || policy.payment_by === 'AGENT') && <hr />}
      {totalGrey.current.includes(status)
        ? getAmountTitle({
            title: LANG_STRINGS.totalBill,
            amount: `${getTotalPremium(policy)}`,
            titleColor: AgentColorPallette.fontDarkerGrey,
            bgColor: AgentColorPallette.fontLightGrey,
          })
        : getAmountTitle({
            title: LANG_STRINGS.totalBill,
            amount: `${getTotalPremium(policy)}`,
            amountColor: AgentColorPallette.white,
            titleColor: AgentColorPallette.white,
            bgColor: AgentColorPallette.maroonRed,
          })}
      {(isManualOrder || isFleetPolicy) &&
        policy?.policy_detail.currency_symbol &&
        policy?.policy_detail.currency_symbol !== 'Rp' && (
          <CustomText
            color={AgentColorPallette.uiGold}
            size="13px"
            fontWeight="800"
            textAlign="right"
            className="item-padding currency-type-container"
            onClick={() => setShowCurrencyChangeDetails(true)}
          >
            {LANG_STRINGS.currencyChangeDetails}
            <img src={DOWN_ARROW_GOLD} alt="" width="20px" />
          </CustomText>
        )}
      {showCurrencyChangeDetails && (
        <BottomActionSheet
          showHeader
          show={showCurrencyChangeDetails}
          onCloseSheet={() => setShowCurrencyChangeDetails(false)}
          title={
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size="13px"
              fontWeight="800"
              className="item-padding"
              bgColor={AgentColorPallette.dustyGrey}
              onClick={() => setShowCurrencyChangeDetails(true)}
            >
              {LANG_STRINGS.currencyChangeDetails}
            </CustomText>
          }
        >
          {getAmountTitle({
            title: LANG_STRINGS.conversionRate,
            amount: `Rp ${policy?.policy_detail.exchange_rate}/${policy?.policy_detail.currency_symbol}1`,
            showText: true,
          })}
          {getAmountTitle({
            title: LANG_STRINGS.basicPremium + ' (IDR)',
            amount: isManualOrder || isFleetPolicy ? policy.net_premium : product.basic_premium,
            convertAmount: false,
          })}
          {getAmountTitle({
            title: LANG_STRINGS.basicPremium + ' (USD)',
            amount: isManualOrder || isFleetPolicy ? policy.net_premium : product.basic_premium,
          })}
        </BottomActionSheet>
      )}
      {totalPremiumChange + totalEndorsementFee > 0 && (
        <>
          <div className="endorsement-calc item-padding">
            <Row justify="space-between">
              <CustomText color={AgentColorPallette.lighterPink} size="10px">
                {LANG_STRINGS.totalBillAfterEndorsement}
              </CustomText>
              <CustomText color={AgentColorPallette.lighterPink} size="10px">
                {formatMoney(totalInvBeforeEndorsement)}
              </CustomText>
            </Row>
            <Row justify="space-between">
              <CustomText color={AgentColorPallette.lighterPink} size="10px">
                {LANG_STRINGS.difference}
              </CustomText>
              <CustomText color={AgentColorPallette.lighterPink} size="10px">
                {formatMoney(totalPremiumChange + totalEndorsementFee)}
              </CustomText>
            </Row>
          </div>
          <Row
            className="item-padding"
            onClick={handleShowEndorsementDetail}
            justify="end"
            align="center"
          >
            <CustomText color={AgentColorPallette.uiGold} weight={800} size="13px" padRight="3px">
              {LANG_STRINGS.viewEndorsementDetails}
            </CustomText>
            <div className="up-down">
              <i className="fas fa-angle-down right-caret" />
            </div>
          </Row>
          {
            <BottomActionSheet
              show={showEndorDetail}
              onCloseSheet={() => setShowEndorDetail(false)}
            >
              <Row justify="space-between">
                <CustomText
                  size="13px"
                  weight="800"
                  className="item-padding"
                  color={AgentColorPallette.fontDarkerGrey}
                >
                  {LANG_STRINGS.endorsementDetails}
                </CustomText>
                <CustomText
                  size="15px"
                  weight="800"
                  className="item-padding"
                  color={AgentColorPallette.fontDarkerGrey}
                  onClick={() => setShowEndorDetail(false)}
                >
                  X
                </CustomText>
              </Row>
              <div>
                {getAmountTitle({
                  title: LANG_STRINGS.premiumChange,
                  amount: policy?.endorsement_breakup?.premium_delta,
                })}
                {getAmountTitle({
                  title: LANG_STRINGS.totalEndorsementFee,
                  amount: policy?.endorsement_breakup?.endorsement_fee,
                })}
                <Row
                  justify="space-between"
                  className="item-padding"
                  bgColor={AgentColorPallette.white}
                >
                  <CustomText color={AgentColorPallette.fontDarkerGrey} size="13px">
                    {LANG_STRINGS.additionalPremiumPaymentStatus}
                  </CustomText>
                  <CustomText
                    color={
                      policy?.endorsement_breakup?.last_endorsement_status ===
                      'ADDITIONAL_BILL_PAID'
                        ? AgentColorPallette.greenDarker
                        : AgentColorPallette.black
                    }
                    size="13px"
                    weight={800}
                  >
                    {getEndorsementStatus(policy?.endorsement_breakup?.last_endorsement_status)}
                  </CustomText>
                </Row>
              </div>
            </BottomActionSheet>
          }
        </>
      )}
      <NotificationContainer />
    </PolicyDetailCard>
  )
}

export default connect(
  (state) => ({
    applicationDetail: state.Policy.applicationDetail,
    updatePolicyQuotationDiscountMsg: state.Policy.updatePolicyQuotationDiscountMsg,
  }),
  {
    updatePolicyQuotationDiscount,
    getApplicationDetail,
    resetPolicyStore,
  }
)(Transactions)
