import { TransactionDetailStyle } from '../index.style'
import InfoHeader from '../../../../../components/InfoHeader/index'
import { CustomText } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang/index'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  BottomActionContainerStyle,
  Row,
  SectionStyle,
} from '../../../../../commonStyle/index.style'
import TransactionHeader from '../../components/TransactionHeader'
import Transactions from '../../components/Transactions'
import OfflinePolicyData from '../../../../CommonContainer/OfflinePolicyContainer/components/OfflinePolicyData'
import OfflinePolicyAddonsData from '../../../../CommonContainer/OfflinePolicyContainer/components/OfflineAddonsData'
import OfflineTransportationType from '../../../../CommonContainer/OfflinePolicyContainer/components/OfflineTransportationType'
import VehicleModificationData from '../../../../CommonContainer/OfflinePolicyContainer/components/VehicleModificationData'
import VehicleData from '../../../../CommonContainer/OfflinePolicyContainer/components/VehicleData'
import VehiclePhotoData from '../../../../CommonContainer/OfflinePolicyContainer/components/VehiclePhotoData'
import VehicleAttachmentData from '../../../../CommonContainer/OfflinePolicyContainer/components/VehicleAttachmentData'
import PolicyHolderInfo from '../../../../CommonContainer/OfflinePolicyContainer/components/PolicyHolderInfo'
import PrintPolicyData from '../../../../CommonContainer/OfflinePolicyContainer/components/PrintPolicyData'
import PolicyBtns from '../../components/PolicyBtns'
import { useCallback, useEffect, useMemo } from 'react'
import {
  ADDITIONAL_INFORMATION_REQUIRED,
  CAR_PROTECTION,
  MANUAL_ORDER,
  MV_RENEWAL_FLOW,
  RENEW_PURCHASE,
} from '../../../../../constants/pkgCode'
import PolicyTransactionInfo from '../../components/PolicyTransactionInfo'
import AgentCommissionPoint from '../../components/AgentCommissionPoint'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
import PolicyInfo from '../../../../../components/PolicyCancelledRejectionInfo'
import InstalmentsInfoContainer from '../../components/InstalmentsInfoContainer'
import PolicyCoinsuranceInfo from '../../components/PolicyCoinsuranceInfo'
import OfflinePolicyQuote from '../OfflinePolicyReviewForm/components/OfflinePolicyQuote'
import { useGetMvRenewalDetails } from '../../state/hooks/usePolicyState'
import { useHistory } from 'react-router'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import { SEND_GOLD_ICON } from '../../../../../images'
import { MV_RENEWAL_STATUS } from '../../../../../constants/pkgCode'

function OfflineToOnlineTransactionDetail({
  policy,
  productCode,
  policyType = '',
}) {
  const history = useHistory()
  const [{ isStaffAgent }] = useGlobalContextValue()
  const [{ getMvRenewalDetailsData }, getMvRenewalDetailsRequest] =
    useGetMvRenewalDetails()
  const handleToAdditionalInfo = useCallback(() => {
    history.push(`/offline/quotes/additional/info/${policy.id}`)
  }, [history, policy.id])

  const isManualOrder = useMemo(() => {
    return policy?.policy_detail.protection_case === MANUAL_ORDER
  }, [policy])

  const isRenewable = useMemo(() => {
    return (
      policy?.insurance_details?.renewal_status === MV_RENEWAL_STATUS.RENEWAL ||
      policy?.insurance_details?.renewal_status ===
        MV_RENEWAL_STATUS.REACTIVATION
    )
  }, [policy])

  const isCarProtection = useMemo(() => {
    return productCode === CAR_PROTECTION
  }, [productCode])

  const checkChasisNumber = () => {
    getMvRenewalDetailsRequest({
      query: {
        chasis_number: policy?.policy_detail?.chasis_number,
        flow: MV_RENEWAL_FLOW.EXISTING_CAR,
      },
    })
  }

  useEffect(() => {
    if (getMvRenewalDetailsData) {
      history.push({
        pathname: `/${CAR_PROTECTION}/form/1`,
        state: {
          package_type: policy?.policy_detail?.package_type,
          name: 'Mobil',
          productCode: CAR_PROTECTION,
          purchaseType: RENEW_PURCHASE,
          purchaseRenewFlow: MV_RENEWAL_FLOW.O2O,
          vehicleData: getMvRenewalDetailsData.data,
          isSameAgent: getMvRenewalDetailsData?.is_same_agent,
        },
      })
    }
  }, [getMvRenewalDetailsData, history])

  return (
    <TransactionDetailStyle>
      <PolicyInfo
        remarks={policy?.insurance_details?.remark_details || {}}
        status={policy?.policy_status || ''}
      />
      {policy.status === ADDITIONAL_INFORMATION_REQUIRED && (
        <>
          <InfoHeader info={LANG_STRINGS.someAdditionalInfoRequired} />
          <Row
            justify="space-between"
            align="center"
            className="additional-info-btn"
            onClick={handleToAdditionalInfo}
          >
            <CustomText
              size="14px"
              color={AgentColorPallette.black}
              weight={700}
            >
              {LANG_STRINGS.additionalInfo}
            </CustomText>
            <CustomText color={AgentColorPallette.fontSecondary} weight={700}>
              <i className="fas fa-angle-right" />
            </CustomText>
          </Row>
        </>
      )}
      <TransactionHeader
        policy={policy}
        documentUrl={policy?.policy_detail?.policy_document.url}
        showDownload
      />
      <SectionStyle padTop="20px">
        {!isStaffAgent && !policy?.is_bulk_business && (
          <AgentCommissionPoint
            commission={policy?.agent_commission}
            points={policy?.agent_points}
            paymentBy={policy?.payment_by}
          />
        )}
        <Transactions policy={policy} isManualOrder={isManualOrder} />
        {isManualOrder && policy.policy_detail?.isCoinsurance && (
          <PolicyCoinsuranceInfo
            providerData={policy.policy_detail?.prov_maps}
          />
        )}
        <PolicyTransactionInfo policy={policy} history={history} />
        {policy?.use_instalment && <InstalmentsInfoContainer policy={policy} />}
        {policy?.policy_detail?.reviewFormData ? (
          <OfflinePolicyQuote
            policyData={policy?.policy_detail}
            isTransactionDetail
          />
        ) : (
          <>
            <OfflinePolicyData
              policy={{
                ...policy.policy_detail,
                policy_status: policy.policy_status,
              }}
              isManualOrder={isManualOrder}
              isTransactionDetail
            />
            {isCarProtection && (
              <OfflinePolicyAddonsData policyData={policy.policy_detail} />
            )}
            {isManualOrder && isCarProtection && (
              <>
                <OfflineTransportationType policyData={policy.policy_detail} />
                <VehicleData policyData={policy.policy_detail} />
              </>
            )}
            {isCarProtection && (
              <>
                <VehicleModificationData policyData={policy.policy_detail} />
                <VehiclePhotoData policyData={policy.policy_detail} />
                <VehicleAttachmentData
                  policyData={policy.policy_detail}
                  isManualOrder
                />
              </>
            )}
            <PolicyHolderInfo policyData={policy.policy_detail} isManualOrder />
            <PrintPolicyData policy={policy} />
          </>
        )}
      </SectionStyle>

      {isRenewable ? (
        <BottomActionContainerStyle>
          <ButtonWithIcon
            text={LANG_STRINGS.renewalPolicy}
            iconRight
            icon={SEND_GOLD_ICON}
            onClick={() => checkChasisNumber()}
            color={AgentColorPallette.blackGrey}
          />
        </BottomActionContainerStyle>
      ) : (
        <PolicyBtns policy={policy} isOfflinePolicy={false} />
      )}
    </TransactionDetailStyle>
  )
}

export default OfflineToOnlineTransactionDetail
