import { get } from 'lodash'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyDetailCard } from '../../pages/index.style'
import { PolicyAddonsStyle } from './index.style'

function PolicyAddons (props) {
  const { policy = {} } = props
  const addons = get(policy, 'product.add_ons', []) || []

  const renderAddonsData = () => {
    return addons.map(addon => (
      <Row className='addon-padding' align='center' justify='space-between' key={addon.add_on_code}>
        <CustomText
          color={AgentColorPallette.regular}
          size='13px'
          weight={800}
        >
          {addon.add_on_name}
        </CustomText>
        <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey} bottom='8px'>
          <i className='fa fa-check' />
        </CustomText>
      </Row>
    ))
  }

  // if addons not exist
  if (!addons.length) return null

  return (
    <PolicyDetailCard>
      <PolicyAddonsStyle>
        <CustomText className='item-padding' color={AgentColorPallette.black} weight={800} size='15px'>
          {LANG_STRINGS.additionalProtection}
        </CustomText>
        <hr />
        {renderAddonsData()}
      </PolicyAddonsStyle>
    </PolicyDetailCard>
  )
}

export default PolicyAddons
