import { ProductInfoStyle } from './index.style'
import {
  MOTOR_VEHICLE_NEW,
  INFORMATION_NEW,
  ARROW_RIGHT_BLUE,
} from '../../../../../../../images/imageUrl'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { DisplayFlexCCC, Grid, Row } from '../../../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { formatMoney } from '../../../../../../../helpers/utility'
import { useGlobalContextValue } from '../../../../../../../contextProvider/GlobalContext/index'
import { useCallback, useMemo } from 'react'
import { useHistory } from 'react-router-dom'
import MVPolicyInfo from '../../../../../../../components/MVPolicyCancelledRejectionInfo'

function ProductInfo({ policy, onEndorsementDetails, isMVDraftDetail, claimDetails }) {
  const [{ isStaffAgent }] = useGlobalContextValue()
  const history = useHistory()

  const isPrintPolicyStatus = useMemo(() => {
    const courierStatus = policy?.insurance_details?.hard_copy_details?.courier_status
    switch (courierStatus) {
      case 'courier-pending':
      case 'courier-sent':
      case 'courier-delivered':
      case 'courier-returned':
        return true
      default:
        return false
    }
  }, [policy])

  const handleTrackDelivery = useCallback(() => {
    const courierId = policy?.insurance_details?.hard_copy_details?.courier_id
    history.push(`/courier-tracking/${courierId}/${policy.id}`)
  }, [history, policy])

  const renderItemAmount = (text, subText) => {
    return (
      <div>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size="0.6em"
          weight={700}
          className="text-uppercase"
        >
          {text}
        </CustomText>
        <CustomText color={AgentColorPallette.blackGrey} size="0.8em" weight={700}>
          {subText}
        </CustomText>
      </div>
    )
  }
  const handleToPolicyClaim = useCallback(() => {
    const { claimId } = claimDetails
    history.push(`/claim/detail/${claimId}`)
  }, [history, claimDetails])

  return (
    <ProductInfoStyle>
      <DisplayFlexCCC>
        <img src={MOTOR_VEHICLE_NEW} alt="motor Icon" />
        <CustomText size="0.75em" color={AgentColorPallette.fontDarkerGrey}>
          {policy?.product?.provider?.name}
        </CustomText>
        <CustomText size="0.9em" weight={700} bottom="0.8rem" color={AgentColorPallette.blackGrey}>
          {`${policy?.customer_data?.name ? `${policy?.customer_data?.name} / ` : ''}${policy?.region_code} ${policy?.vehicle_plate_no}`}
        </CustomText>
      </DisplayFlexCCC>
      <MVPolicyInfo
        remarks={policy?.insurance_details?.remark_details || {}}
        status={policy?.policy_status || ''}
      />
      {policy?.application_no && (
        <Row align="center" justify="space-between" className="policy-number">
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {LANG_STRINGS.policyNumber}
          </CustomText>
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {policy?.application_no}
          </CustomText>
        </Row>
      )}
      {policy?.insurance_details?.insurance_policy_no && (
        <Row align="center" justify="space-between" className="policy-number">
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {LANG_STRINGS.inusrancePolicyNumber}
          </CustomText>
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {policy?.insurance_details?.insurance_policy_no}
          </CustomText>
        </Row>
      )}
      {policy?.application_no && claimDetails?.claimId && (
        <Row
          align="center"
          justify="space-between"
          bgColor={AgentColorPallette.crusieGreen}
          className="policy-status"
          onClick={handleToPolicyClaim}
        >
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {LANG_STRINGS.claimStatus}
          </CustomText>
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blackGrey} bottom="0">
            {`${claimDetails?.claimStatus}`} <i className="fas fa-angle-right" />
          </CustomText>
        </Row>
      )}
      {isPrintPolicyStatus && (
        <Row
          align="center"
          justify="space-between"
          className="policy-print"
          onClick={handleTrackDelivery}
        >
          <CustomText size="0.75em" weight={700} color={AgentColorPallette.blueDefault} bottom="0">
            {LANG_STRINGS.policyPrintStatus}
          </CustomText>
          <Row align="center">
            <CustomText
              size="0.75em"
              weight={700}
              color={AgentColorPallette.blueDefault}
              bottom="0"
              padRight="0.5rem"
            >
              {policy?.insurance_details?.hard_copy_details?.courier_status}
            </CustomText>
            <div>
              <img src={ARROW_RIGHT_BLUE} alt="" />
            </div>
          </Row>
        </Row>
      )}
      {policy?.is_gross_premium_changed && (
        <Grid gridColumn="30px 1fr" gridGap="0.5rem" className="commission-info">
          <div>
            <img src={INFORMATION_NEW} alt="" />
          </div>
          <div>
            <CustomText color={AgentColorPallette.darkCharcoal} size="0.9em">
              {LANG_STRINGS.changeInCommissionsAndPointsAfterEndorsement}
            </CustomText>
            <CustomText
              color={AgentColorPallette.buddhaGold}
              size="0.8em"
              weight={700}
              top="0.4rem"
              onClick={onEndorsementDetails}
            >
              {LANG_STRINGS.seeDetails}
            </CustomText>
          </div>
        </Grid>
      )}
      <div className="pkg-item-btm">
        {(policy?.premium?.amount || policy?.product?.basic_premium || policy?.total_premium) && (
          <Row justify="space-between" align="center">
            {renderItemAmount(
              `${LANG_STRINGS.premium} ${policy?.premium?.period || 12} ${LANG_STRINGS.months}`,
              formatMoney(
                policy?.premium?.amount || policy?.product?.basic_premium || policy?.total_premium,
                0
              )
            )}
            {!isStaffAgent && !policy.is_bulk_business && (
              <div className="amount-section">
                {renderItemAmount(
                  LANG_STRINGS.commission,
                  formatMoney(policy?.agent_commission || policy?.product?.commission, 0)
                )}
                {renderItemAmount(
                  LANG_STRINGS.point,
                  policy?.agent_points || policy?.product?.points
                )}
              </div>
            )}
          </Row>
        )}
        <div className="separator" />
        <Row justify="space-between" align="center">
          <CustomText color={AgentColorPallette.fontDarkerGrey}>
            {LANG_STRINGS.valueOfCoverage}
          </CustomText>
          <CustomText color={AgentColorPallette.fontDarkerGrey}>
            {formatMoney(policy?.total_sum_insured, 0)}
          </CustomText>
        </Row>
      </div>
    </ProductInfoStyle>
  )
}

export default ProductInfo
