import { useCallback, useEffect, useMemo } from 'react'
import { useHistory, useRouteMatch } from 'react-router'
import { Container } from '../../../../components'
import { CONFIG_TEMPLATE } from '../constants'
import { useGetPurchaseFlowConfig } from '../services'
import TransactionDetailV1 from '../templates/TransactionDetailV1'
import { getPageData } from './helpers'
import { PageContainer } from './index.style'

function DynamicTransactionDetailContainer({ policyData }) {
  const history = useHistory()
  const { params } = useRouteMatch()
  const { policyId, pageKey } = params
  const productCode = policyData?.product_key

  const {
    state: { getPurchaseFlowConfigData },
    request: getPurchaseFlowConfigReq,
  } = useGetPurchaseFlowConfig()
  const configData = getPurchaseFlowConfigData?.data

  useEffect(() => {
    getPurchaseFlowConfigReq({ productCode })
  }, [getPurchaseFlowConfigReq, productCode])

  const { pageData } = useMemo(() => getPageData(configData, pageKey), [configData, pageKey])

  const renderPageByTemplate = useCallback(() => {
    switch (pageData?.template) {
      case CONFIG_TEMPLATE.TRANSACTION_DETAIL_V1:
        return (
          <TransactionDetailV1
            productCode={productCode}
            pageData={pageData}
            policyId={policyId}
            policyData={policyData}
          />
        )
      default:
        return <div />
    }
  }, [productCode, policyId, pageData, policyData])

  return (
    <Container
      title={configData?.product_name}
      loader={!policyData}
      showInnerHeader
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() => history.push('/transactions')}
    >
      <PageContainer>{renderPageByTemplate()}</PageContainer>
    </Container>
  )
}

export default DynamicTransactionDetailContainer
