import { LANG_STRINGS } from '../../../../../lang'
import TransactionInfoCard from '../TransactionInfoCard'

function SurveyInfo (props) {
  const { isCollapsible = false, className = '', policy } = props
  const renderSurveyDetail = () => {
    return {
      heading: `${LANG_STRINGS.vehicleSurvey}`,
      items: policy.survey_response.map((d) => (
        {
          ...d,
          newline: !d.head
        }
      ))

    }
  }

  return (
    <TransactionInfoCard
      isCollapsible={isCollapsible}
      className={`${className}`}
      data={renderSurveyDetail()}
    />
  )
}

export default SurveyInfo
