import { AgentColorPallette } from '../../configs/colorPallete'
import { LANG_STRINGS } from '../../lang'
import CollapsibleCard from '../CollapsibleCard'
import CustomText from '../CustomText'
import { InsuranceInfoCardStyle } from './index.style'
import PropTypes from 'prop-types'
import ProviderBranchSelect from '../ProviderBranchSelect'
import DisclaimerBox from '../DisclaimerBox'
import { BenefitSection, TermsConditionsSection, ClaimsSection } from './components'

function InsuranceInfoCardProperty (props) {
  const { className = '', showBranchOption, selectedBranch = {}, onBranchSelect, providerCode, isShowDisclaimer } = props


  return (
    <InsuranceInfoCardStyle className={className}>
      <CustomText
        size='15px'
        color={AgentColorPallette.black}
        weight={700}
        className='insur-info'
      >
        {LANG_STRINGS.insuranceInfo}
      </CustomText>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.benefit}
        titleClassName='card-title'
        className='collapse-card'
      >
        <BenefitSection benefit={props.benefit} benefitType={props.benefitType} />
      </CollapsibleCard>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.termsConditions}
        titleClassName='card-title'
        className='collapse-card'
      >
        {
          isShowDisclaimer &&
            <>
              <DisclaimerBox /><br />
            </>
        }
        <TermsConditionsSection tnc={props.tnc} />
      </CollapsibleCard>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.claimMethos}
        titleClassName='card-title'
        className='collapse-card'
        isOpen
      >
        <ClaimsSection claims={props.claims} />
      </CollapsibleCard>
      {
        showBranchOption &&
          <>
            <hr className='separator' />
            <ProviderBranchSelect
              hideBoxShadow
              selectedBranch={selectedBranch}
              onBranchSelect={onBranchSelect}
              providerCode={providerCode}
            />
          </>
      }
    </InsuranceInfoCardStyle>
  )
}

InsuranceInfoCardProperty.propTypes = {
  claims: PropTypes.oneOfType([PropTypes.string, PropTypes.array]),
  benefit: PropTypes.oneOfType([PropTypes.string, PropTypes.object]),
  tnc: PropTypes.array
}
export default InsuranceInfoCardProperty
