import { MVAccessoriesStyle } from './index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang/index'
import { CustomText } from '../../../../../components'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import { ACCESSORY } from '../../../../../constants/quoatation'
import { PolicyDetailCard } from '../../pages/index.style'

export default function MVAccessories (props) {
  const { policy } = props

  function renderAccessory (text, size, weight, color, bottom = '2px') {
    return (
      <CustomText size={size} weight={weight} color={color} bottom={bottom}>
        {text}
      </CustomText>
    )
  }

  return (
    <PolicyDetailCard>
      <MVAccessoriesStyle>
        <CustomText className='item-padding' color={AgentColorPallette.black} weight={800} size='15px'>
          {LANG_STRINGS.additionalAccessories}
        </CustomText>
        <hr />
        {
          policy.policy_detail &&
          policy.policy_detail.accessories.map((accessory, index) =>
            <div className='row-accessories item-padding' key={index}>
              {
                accessory.img &&
                  <div className='img-container'>
                    <SingleImgContainer
                      imgUrl={accessory.img}
                      showVerified
                    />
                  </div>
              }
              <div>
                {renderAccessory(LANG_STRINGS.accessoriesType, '12px', 700, AgentColorPallette.fontDarkerGrey)}
                {renderAccessory(ACCESSORY[accessory.accessory_type], '14px', 700, AgentColorPallette.regular, '8px')}
                {renderAccessory(LANG_STRINGS.accessoriesName, '12px', 700, AgentColorPallette.fontDarkerGrey)}
                {renderAccessory(accessory.name, '14px', 700, AgentColorPallette.regular, '8px')}
                {renderAccessory(LANG_STRINGS.accessoriesPrice, '12px', 700, AgentColorPallette.fontDarkerGrey)}
                {renderAccessory(accessory.sum_insured, '14px', 700, AgentColorPallette.regular, '8px')}
              </div>
            </div>
          )
        }
      </MVAccessoriesStyle>
    </PolicyDetailCard>
  )
}
