import { useCallback, useMemo, useState } from 'react'
import Tabs from '../../../../../components/Tabs'
import TransactionPaymentHeader from '../../../Policy/components/TransactionPaymentHeader'
import FormFieldDisplay from '../../../DynamicPurchaseFlow/components/tabSections/FormFieldDisplay'
import RichTextContent from '../../../DynamicPurchaseFlow/components/tabSections/RichTextContent'
import { TAB_SECTION_TYPE } from '../../constants'
import PolicySummary from './components/PolicySummary'
import PolicyActions from './components/PolicyActions'
import TrackerPolicyStatus from './components/TrackerPolicyStatus'
import TrackerPaymentStatus from './components/TrackerPaymentStatus'
import TrackerCommission from './components/TrackerCommission'
import { mapTabData } from './helpers'
import { ConfirmationContainer, ActiveTabContainer, MiddleSection } from './index.style'

function TransactionDetailV1(props) {
  const { policyId, productCode, policyData, pageData } = props

  const draftData = useMemo(
    () => ({
      ...policyData?.policy_detail,
      status: policyData?.policy_status ?? policyData?.policy_detail?.status,
    }),
    [policyData]
  )
  const packageData = useMemo(() => draftData?.package, [draftData])

  const tabsData = useMemo(() => mapTabData(pageData), [pageData])
  const [activeTab, setActiveTab] = useState(tabsData[0])

  const renderSectionContent = useCallback(
    (section, idx) => {
      switch (section?.type) {
        case TAB_SECTION_TYPE.FORM_FIELD_DISPLAY:
          return <FormFieldDisplay key={idx} sectionData={section} draftData={draftData} />
        case TAB_SECTION_TYPE.RICH_TEXT:
          return <RichTextContent key={idx} sectionData={section} packageData={packageData} />
        case TAB_SECTION_TYPE.ADDON_LIST:
        case TAB_SECTION_TYPE.HARDCOPY_CHECKBOX:
        default:
          return <div key={idx} />
      }
    },
    [draftData, packageData]
  )

  const renderFooter = useCallback(() => {
    switch (pageData?.footer_type) {
      // case TEMPLATE_FOOTERS.PREMIUM_BREAKDOWN_V1:
      //   return (
      //     <PremiumBreakdownFooterV1
      //       productCode={productCode}
      //       draftId={draftId}
      //       pageData={pageData}
      //       draftData={draftData}
      //       packageData={packageData}
      //       onSaveDraft={onSaveDraft}
      //       onClickNextPage={handleClickNextPage}
      //     />
      //   )
      default:
        return <div />
    }
  }, [productCode, policyId, pageData, draftData, packageData])

  return (
    <>
      <ConfirmationContainer>
        <TransactionPaymentHeader policy={policyData} />

        <PolicySummary policyData={policyData} />
        <MiddleSection>
          <PolicyActions policyData={policyData} />
          <TrackerPaymentStatus trackerData={policyData?.payment_status_tracker} />
          <TrackerPolicyStatus trackerData={policyData?.policy_status_tracker} />
          <TrackerCommission trackerData={policyData} />
        </MiddleSection>

        <Tabs
          data={tabsData}
          defaultTab={tabsData[0]}
          onClick={(tab) => setActiveTab(tab)}
          isSticky
        />
        {tabsData?.map((tab) => {
          if (activeTab.value !== tab?.value) return null
          const sections = pageData?.tabs?.[activeTab.value]?.sections
          console.log('sections in TransactionDetailV1', sections)
          return (
            <ActiveTabContainer key={tab?.value}>
              {sections.map((section, idx) => renderSectionContent(section, idx))}
            </ActiveTabContainer>
          )
        })}
        {renderFooter()}
      </ConfirmationContainer>
    </>
  )
}

export default TransactionDetailV1
