import {
  PaymentBreakUpStyle,
  DiscountInputContainer,
  EndorsementStyle,
} from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../lang/index'
import {
  useCallback,
  useState,
  useRef,
  forwardRef,
  useImperativeHandle,
  useMemo,
} from 'react'
import RadioV2 from '../../../RadioV2'
import NumericInput from '../../../NumericInput/index'
import { CustomText } from '../../..'
import { Error, Row } from '../../../../commonStyle/index.style'
import { formatMoney, getConvertedCurrency } from '../../../../helpers/utility'
// import { ONE_POINT_RP } from '../../../../constants/payment'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { CARET_GOLD } from '../../../../images'
import { getEndorsementStatus } from '../../../../containers/Private/Policy/constants'
import { MANUAL_ORDER } from '../../../../constants/pkgCode'

function PaymentBreakup(
  {
    paymentMap,
    policy,
    showDiscount,
    discountPercent,
    maxDiscount,
    commission,
    onDiscountChange = () => {},
    showTotalBill = false,
    showPaidAmount = false,
    isUseInstalment,
    instalmentPayment = {},
    showFinalCommissionWord,
    setDisabled = () => {},
  },
  parentRef
) {
  const [showAddDiscount, setShowAddDiscount] = useState(!!paymentMap.discount)
  const [discountType, setDiscountType] = useState('nominal')
  const discountInputRef = useRef()
  const [discount, setDiscount] = useState(paymentMap.discount)
  const [discountError, setDiscountError] = useState()
  const [showEndorsement, setShowEndorsement] = useState(false)

  useImperativeHandle(parentRef, () => ({
    getDiscount: () => discount,
    showEndorsementDetails: (isShow) => setShowEndorsement(isShow),
  }))

  const isManualOrder = useMemo(() => {
    return policy?.policy_detail?.protection_case === MANUAL_ORDER
  }, [policy])

  const handleShowAddDiscount = useCallback(() => {
    setShowAddDiscount((prevValue) => !prevValue)
    if (showAddDiscount) {
      setDiscount(0)
      onDiscountChange(0)
    }
  }, [showAddDiscount, onDiscountChange])

  const handleEndorsementDetails = useCallback(() => {
    // same endorsement details
    setShowEndorsement((showEndorsement) => !showEndorsement)
  }, [])

  const getAmountName = useCallback(
    (title, color = AgentColorPallette.black, weight) => {
      return (
        <CustomText color={color} size="0.8em" weight={weight}>
          {title}
        </CustomText>
      )
    },
    []
  )

  const getAmountContainer = useCallback(
    ({
      title,
      amount,
      className = '',
      color = AgentColorPallette.black,
      titleColor = AgentColorPallette.fontDarkerGrey,
      isSkipZero = false,
      amountPrefix,
      subTitle,
      subTitleSize = '10px',
      convertAmount = true,
      showText = false,
    }) => {
      if (amount || subTitle || isSkipZero) {
        let formattedAmount
        if (showText) {
          formattedAmount = amount
        } else {
          if (
            policy?.policy_detail?.currency_label !== 'IDR' &&
            isManualOrder &&
            convertAmount === true
          ) {
            formattedAmount = `${policy?.policy_detail?.currency_symbol || '$'} ${getConvertedCurrency(amount, policy?.policy_detail?.exchange_rate)}`
          } else {
            formattedAmount = `${formatMoney(amount, 0)}`
          }
        }

        return (
          <div className={`payment-row ${className}`}>
            <Row justify="space-between">
              {getAmountName(title, titleColor)}
              {getAmountName(formattedAmount, color)}
            </Row>
            {subTitle && (
              <CustomText color={color} size={subTitleSize}>
                {subTitle}
              </CustomText>
            )}
          </div>
        )
      }

      return null
    },
    [getAmountName, isManualOrder, policy?.policy_detail]
  )

  const handleDiscountType = useCallback(
    (type) => {
      // handle the discount
      setDiscountType(type)
      setDiscount(0)
      onDiscountChange(0)
      discountInputRef.current.resetInputValue()
    },
    [onDiscountChange]
  )

  const getDiscountAmount = useCallback(
    (value = 0) => {
      if (discountType === 'nominal') {
        return value || 0
      } else {
        return Math.floor(paymentMap.sub_total * (value / 100))
      }
    },
    [discountType, paymentMap]
  )

  const handlePercentageValue = useCallback(
    (value) => {
      const isPercentageType = discountType === 'percentage'
      if (
        value > maxDiscount ||
        (isPercentageType && value > discountPercent)
      ) {
        setDiscountError(true)
        setDisabled(true)
        return false
      }
      setDiscountError(false)
      setDisabled(false)
      const finalDiscount = getDiscountAmount(value)
      setDiscount(finalDiscount)
      onDiscountChange && onDiscountChange(finalDiscount)
    },
    [
      discountType,
      getDiscountAmount,
      discountPercent,
      maxDiscount,
      onDiscountChange,
    ]
  )

  const renderDiscountAddContainer = useCallback(() => {
    const isPercentageType = discountType === 'percentage'
    return (
      <div>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size="0.8em"
          bottom="0.7rem"
          top="0.7rem"
        >
          {LANG_STRINGS.enterDiscount}
        </CustomText>
        <RadioV2
          data={[
            {
              value: 'nominal',
              name: LANG_STRINGS.nominalNew,
            },
            {
              value: 'percentage',
              name: LANG_STRINGS.percentageNew,
            },
          ]}
          defaultValue={discountType}
          titleSize="0.7em"
          name="discount_type"
          className="discount-radio-display"
          onChange={handleDiscountType}
        />
        <DiscountInputContainer>
          <Row align="center">
            {!isPercentageType && <div className="rupee-icon">Rp</div>}
            <NumericInput
              ref={discountInputRef}
              name="percentageInput"
              onChange={handlePercentageValue}
              id="percentageInput"
              value={discount}
              type={isPercentageType ? 'discount' : ''}
              isNotSuffix
              className={
                isPercentageType ? 'numeric-input' : 'numeric-input-nominal'
              }
              placeholder={
                isPercentageType
                  ? LANG_STRINGS.percentagePlaceholder.replace(
                      'XXX',
                      discountPercent
                    )
                  : LANG_STRINGS.maxAmountYourCommission
              }
            />
            {isPercentageType && <div className="percentage-icon">%</div>}
          </Row>
          {discountError && <Error>{ERROR_LANG.maxDiscountError}</Error>}
        </DiscountInputContainer>
        {getAmountContainer({
          title: LANG_STRINGS.transactionAmount,
          amount: commission,
        })}
        {getAmountContainer({
          title: LANG_STRINGS.discount,
          amount: discount,
          color: AgentColorPallette.vibrantRed,
          titleColor: AgentColorPallette.vibrantRed,
          isSkipZero: true,
        })}
        {getAmountContainer({
          title:
            LANG_STRINGS.finalCommission + (showFinalCommissionWord ? '*' : ''),
          amount: commission - (discount || 0),
          className: 'final-amount',
          subTitle: showFinalCommissionWord ? 'Dikenakan Pajak WHT 2%' : '',
          subTitleSize: showFinalCommissionWord ? '8px' : '',
        })}
      </div>
    )
  }, [
    handleDiscountType,
    discountType,
    handlePercentageValue,
    discountPercent,
    commission,
    getAmountContainer,
    discount,
    discountError,
    showFinalCommissionWord,
  ])

  const renderDiscountAdd = useCallback(
    (title, discount, className) => {
      return (
        <div
          className={`payment-row ${className} ${showAddDiscount && 'add-discount-box'}`}
        >
          <Row justify="space-between">
            {getAmountName(title, AgentColorPallette.fontDarkerGrey)}
            <div onClick={handleShowAddDiscount}>
              {getAmountName(
                showAddDiscount
                  ? LANG_STRINGS.cancelSmall
                  : LANG_STRINGS.addNew,
                AgentColorPallette.buddhaGold
              )}
            </div>
          </Row>
          {showAddDiscount && renderDiscountAddContainer(discount)}
        </div>
      )
    },
    [
      getAmountName,
      showAddDiscount,
      handleShowAddDiscount,
      renderDiscountAddContainer,
    ]
  )

  const renderAddonsBreakup = useCallback(() => {
    const {
      endorsement_breakup: endorsementBreakup,
      total_premium_change: totalPremiumChange = '',
      total_endorsement_fee: totalEndorsementFee = '',
    } = policy
    if (totalEndorsementFee) {
      return (
        <EndorsementStyle
          className="addons-row"
          borderSize={showEndorsement && '3px'}
          id="endorsementInfo"
        >
          <Row justify="space-between" onClick={handleEndorsementDetails}>
            <Row align="center">
              {getAmountName(
                LANG_STRINGS.additionalProtection,
                AgentColorPallette.fontDarkerGrey
              )}
              &nbsp;&nbsp;&nbsp;
              <img
                src={CARET_GOLD}
                width="12px"
                alt=""
                className={showEndorsement && 'arrow-rotate'}
              />
            </Row>
            {!showEndorsement &&
              getAmountName(
                formatMoney(totalPremiumChange + totalEndorsementFee, 0),
                AgentColorPallette.black
              )}
          </Row>
          {showEndorsement && (
            <>
              {getAmountContainer({
                title: LANG_STRINGS.earlyAdditionalCoverage,
                amount: paymentMap.add_on_premium,
              })}
              {getAmountContainer({
                title: LANG_STRINGS.premiumChange,
                amount: endorsementBreakup?.premium_delta,
                color: AgentColorPallette.vibrantRed,
              })}
              {getAmountContainer({
                title: LANG_STRINGS.totalEndorsementFee,
                amount: endorsementBreakup?.endorsement_fee,
                color: AgentColorPallette.vibrantRed,
              })}
              {getAmountContainer({
                title: LANG_STRINGS.lackOfPolicyPay,
                amount: 0,
                color: AgentColorPallette.vibrantRed,
              })}
              {getAmountContainer({
                title: LANG_STRINGS.totalAdditionalCoverageNew,
                amount: totalPremiumChange + totalEndorsementFee,
                color: AgentColorPallette.regular,
                titleColor: AgentColorPallette.regular,
                className: 'total-endorse-amount',
              })}
              <Row justify="space-between" className="endorse-status">
                {getAmountName(
                  LANG_STRINGS.additionalPremiumPaymentStatus,
                  AgentColorPallette.fontDarkerGrey
                )}
                {getAmountName(
                  getEndorsementStatus(
                    endorsementBreakup?.last_endorsement_status
                  ),
                  AgentColorPallette.regular
                )}
              </Row>
            </>
          )}
        </EndorsementStyle>
      )
    }
    return (
      !!paymentMap.add_on_premium &&
      getAmountContainer({
        title: LANG_STRINGS.additionalPackage,
        amount: paymentMap.add_on_premium,
        className: 'addons-row',
      })
    )
  }, [
    paymentMap,
    policy,
    showEndorsement,
    getAmountContainer,
    getAmountName,
    handleEndorsementDetails,
  ])

  return (
    <PaymentBreakUpStyle>
      {getAmountContainer({
        title: isUseInstalment
          ? `${LANG_STRINGS.basicPremium} ${LANG_STRINGS.instalment} ${instalmentPayment?.serial_number}`
          : LANG_STRINGS.basicPremium,
        amount: paymentMap.basic_premium,
      })}
      {isManualOrder &&
        policy?.policy_detail?.currency_symbol &&
        policy?.policy_detail?.currency_symbol !== 'Rp' &&
        getAmountContainer({
          title: LANG_STRINGS.currency,
          amount: `${policy?.policy_detail?.currency_label} (${policy?.policy_detail?.currency_symbol})`,
          showText: true,
        })}
      {renderAddonsBreakup()}
      {paymentMap.fleet_discount &&
        getAmountContainer({
          title: LANG_STRINGS.fleetDiscount,
          amount: paymentMap.fleet_discount,
        })}
      {getAmountContainer({
        title: LANG_STRINGS.subTotal,
        amount: paymentMap.sub_total,
        className: 'subtotal-bg',
      })}
      {getAmountContainer({
        title: LANG_STRINGS.policyPrintingFees,
        amount: paymentMap.printing_fee,
        className: 'border-btm',
      })}

      {/* FEES NEW APPROACH */}
      {paymentMap?.fees?.map((fee, idx) => {
        return (
          <div key={(fee?.key, idx)}>
            {getAmountContainer({
              title: fee?.label || '',
              amount: fee.value,
              className: 'border-btm',
            })}
          </div>
        )
      })}
      {/* {
        getAmountContainer({
          title: LANG_STRINGS.stampDuty,
          amount: (paymentMap.stamp_duty),
          className: 'border-btm'
        })
      } */}
      {/* {
        getAmountContainer({
          title: LANG_STRINGS.tax,
          amount: (paymentMap.tax),
          className: 'border-btm'
        })
      } */}
      {/* {
        getAmountContainer({
          title: LANG_STRINGS.adminFee,
          amount: (paymentMap.admin_fee),
          className: 'border-btm'
        })
      } */}
      {getAmountContainer({
        title: LANG_STRINGS.serviceFee,
        amount: paymentMap.service_fee,
        className: 'border-btm',
      })}
      {paymentMap.discount && !showDiscount
        ? getAmountContainer({
            title: LANG_STRINGS.discount,
            amount: paymentMap.discount,
            className: 'border-btm',
            color: AgentColorPallette.vibrantRed,
          })
        : showDiscount &&
          renderDiscountAdd(
            LANG_STRINGS.discount,
            paymentMap.discount,
            'border-btm'
          )}
      {/* {
        ['AGENT', 'agent'].includes(policy?.payment_by) && (
          getAmountContainer({
            title: LANG_STRINGS.fromYourCommission,
            amount: (paymentMap.current_commission_used),
            className: 'border-btm',
            color: AgentColorPallette.vibrantRed,
            subTitle: !paymentMap.current_commission_used && LANG_STRINGS.canNotUsedBecauseOfInitialBalance
          })
        )
      } */}
      {/*
      {
        getAmountContainer({
          title: LANG_STRINGS.useOfBalance,
          amount: (paymentMap.commission_used),
          className: 'border-btm',
          color: AgentColorPallette.vibrantRed
        })
      }
      {
        getAmountContainer({
          title: LANG_STRINGS.useOfPoint,
          amount: (paymentMap.point_used * ONE_POINT_RP),
          color: AgentColorPallette.vibrantRed
        })
      } */}
      {getAmountContainer({
        title: LANG_STRINGS.totalBill,
        amount: paymentMap.total_bill,
        className: 'total-bill-bg',
        color: AgentColorPallette.white,
        titleColor: AgentColorPallette.white,
      })}
      {isManualOrder &&
        policy?.policy_detail?.currency_symbol &&
        policy?.policy_detail?.currency_symbol !== 'Rp' &&
        getAmountContainer({
          title: LANG_STRINGS.totalBill + ' (USD $)',
          amount: policy?.total_bill,
        })}
      {isManualOrder &&
        getAmountContainer({
          title: LANG_STRINGS.totalBill + ' (Rp)',
          amount: policy?.total_bill,
          convertAmount: false,
        })}
      {isManualOrder &&
        policy?.policy_detail?.currency_symbol &&
        policy?.policy_detail?.currency_symbol !== 'Rp' &&
        getAmountContainer({
          title: LANG_STRINGS.conversionRate,
          amount: `Rp ${policy?.policy_detail?.exchange_rate}/${policy?.policy_detail?.currency_symbol}1`,
          showText: true,
        })}
    </PaymentBreakUpStyle>
  )
}

export default forwardRef(PaymentBreakup)
