import { get } from 'lodash'
import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { withRouter } from 'react-router'
import { BottomActionContainerStyle } from '../../../../../commonStyle/index.style'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import { LANG_STRINGS } from '../../../../../lang'
import policyActions from '../../../../../redux/policy/action'
import { PolicyBtnsStyle } from './index.style'
import { NotificationContainer } from 'react-notifications'
import PaymentConfirmationModal from '../../../Application/components/PaymentConfirmationModal'
import {
  MARINE_CARGO_PROTECTION,
  PROPERTY_PROTECTION_BASIC,
  RENEW_PURCHASE,
} from '../../../../../constants/pkgCode'
import { SEND_GOLD_ICON, DOWNLOAD_GOLD } from '../../../../../images/imageUrl'
// import ConfirmationModal from '../../../../../components/ConfirmationModal'
import { getTaxForAgentAmount } from '../../../../../helpers/utility'
import { HIDE_PAYMENT_TXN_STATUS } from '../../../../../constants/quoatation'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

const { agentPayingRequest, resetPolicyStore, getTaxSlabRequest } =
  policyActions

function PolicyBtns(props) {
  const {
    policy = {},
    history,
    resetPolicyStore,
    agentPayingRequest,
    agentPayingMsg,
    agentPayingData,
    agentPayingLoading,
    getTaxSlabRequest,
    taxSlabLoader,
    getTaxSlabData,
    grey,
    onHandleWaitingPage,
  } = props
  const {
    status,
    id,
    policy_status: policyStatus,
    payment_status: paymentStatus,
  } = policy

  // const [modalState, setModalState] = useState({
  //   showConfirmationModal: false
  // })
  const [paymentModalState, setPaymentModalState] = useState({
    showConfirmationPopup: false,
  })

  useEffect(() => {
    if (taxSlabLoader === undefined) {
      // getTaxSlabRequest()
    }
  }, [getTaxSlabRequest, taxSlabLoader])

  useEffect(() => {
    if (agentPayingMsg === 'success') {
      const pkgCode = get(policy, 'product.package.code', 'policy') || 'policy'
      if (agentPayingData.transaction_id) {
        history.push({
          // pathname: `/motor-vehicle/${agentPayingData.transaction_id}/agent/${id}/payment`,
          pathname: `/payment/${pkgCode}/${id}`,
          state: {
            token: id,
            transactionId: agentPayingData.transaction_id,
            policyStatus: policy.policy_status,
          },
        })
      }
      resetPolicyStore(['agentPayingMsg', 'agentPayingData'])
    }
  }, [resetPolicyStore, policy, agentPayingMsg, agentPayingData, id, history])

  // const handlePaymentConfirm = () => {
  //   setModalState(prevProps => ({
  //     showConfirmationModal: !modalState.showConfirmationModal,
  //     confirmModalTitle: LANG_STRINGS.information,
  //     confirmModalAgree: LANG_STRINGS.okay,
  //     isPdfConfirm: false,
  //     confirmModalText: LANG_STRINGS.youCanNotPayThisAgent
  //   }))
  // }

  const handleMakePayment = (isInstalment) => {
    // move to different step
    // status": "PAYMENT_PENDING"
    const {
      payment_status: paymentStatus,
      payment_by: paymentBy,
      use_pay_later: usePayLater,
      policy_status: policyStatus,
      policy_detail: policyDetail,
      transaction_ids: transactionIdsMap = {},
      bank_va: bankVa,
    } = policy
    const pkgCode = get(policy, 'product.package.code', '')
    let path = ''
    if (isInstalment) {
      history.push({
        pathname: `/payment/offline-online/${id}`,
      })
      return
    }
    if (bankVa && transactionIdsMap.agent && paymentStatus === 'COMPLETED') {
      return history.push(`/agent/va/detail/${transactionIdsMap.agent}/${id}`)
    }
    // if ((paymentBy === 'CUSTOMER_EMAIL' || paymentBy === 'CUSTOMER') && paymentStatus === 'ACTIVE') {
    //   handlePaymentConfirm()
    //   return
    // }

    // if (usePayLater && (status === 'PROVISIONAL_CREATED')) {
    //   // ask the agent to confirm pay later option
    //   path = '' // this agent pay later and maintained
    //   setPaymentModalState({
    //     showConfirmationPopup: true
    //   })
    //   return
    // } else
    if (status === 'QUOTATION' || status === 'INITIATED') {
      // move to step 3
      if (pkgCode === PROPERTY_PROTECTION_BASIC) {
        path = `/property/${id}/form`
      } else if (pkgCode === MARINE_CARGO_PROTECTION) {
        path = `/marine_cargo/packages/${id}/form`
      } else {
        if (policyDetail.purchase_type === RENEW_PURCHASE) {
          path = `/motor_vehicle/renewal/policy/form/${id}/${policyDetail.org_policy_ref_id}` // `/motor_vehicle/packages/${id}/form`
        } else {
          path = `/motor_vehicle/packages/${id}/form`
        }
      }
    } else if (
      status === 'APPLICATION_COMPLETED' ||
      (((status === 'PAYMENT_PENDING' &&
        [
          'WAITING_FOR_PAYMENT',
          'NO_PAYMENT_MADE',
          'ACTIVE',
          'EXPIRED',
        ].includes(paymentStatus)) ||
        ((paymentBy === 'CUSTOMER_EMAIL' || paymentBy === 'CUSTOMER') &&
          paymentStatus !== 'ACTIVE')) &&
        !transactionIdsMap.agent) ||
      (usePayLater && status === 'PROVISIONAL_CREATED') ||
      (transactionIdsMap.agent &&
        status === 'PAYMENT_PENDING' &&
        ['WAITING_FOR_PAYMENT', 'ACTIVE', 'EXPIRED', 'FAILED'].includes(
          paymentStatus
        ))
    ) {
      path = `/payment/${pkgCode}/${id}`
    } else if (status === 'PAYMENT_PENDING' && transactionIdsMap.agent) {
      path = `/agent/payment/success/${transactionIdsMap.agent}/${id}`
    }

    history.push({
      pathname: path,
      state: {
        status,
        policyStatus,
        token: id,
        policyId: id,
        transactionId: policy.transaction_id,
        paymentTransactionId: transactionIdsMap.agent,
        createPolicyData: policy,
        applicationNo: policy.application_no,
      },
    })
  }

  const handleCloseModal = () => {
    setPaymentModalState({
      showConfirmationPopup: false,
    })
  }

  const handleAgreePayment = () => {
    const {
      total_premium: totalPremium = 0,
      agent_commission: agentCommission = 0,
      discount = 0,
    } = policy
    const agentCommissionWithoutDiscount = agentCommission - discount
    const taxOnAgentCommission = getTaxForAgentAmount(
      agentCommissionWithoutDiscount,
      getTaxSlabData.tax_slab_info
    )
    const payableAmount =
      totalPremium - (agentCommission - taxOnAgentCommission)
    agentPayingRequest({
      token: id,
      commission: {
        amount: 0,
        tax: 0,
      },
      point: {
        amount: 0,
        point: 0,
        tax: 0,
      },
      payable_amount: payableAmount,
      agent_paying: true,
    })
  }

  const handleToDocumentsPage = () => {
    // open the documents screen
    history.push({
      pathname: `/transactions/${id}/details/documents`,
    })
  }

  if (
    (HIDE_PAYMENT_TXN_STATUS.includes(status) &&
      ['ACTIVE', 'PROVISIONAL_ISSUED', 'CANCELLED', 'REJECTED'].includes(
        policyStatus
      )) ||
    ['COMPLETED', 'PROOF_SUBMITTED'].includes(paymentStatus)
  ) {
    return (
      <PolicyBtnsStyle>
        <BottomActionContainerStyle className="btn-container" padding="10px">
          <ButtonWithIcon
            text={LANG_STRINGS.downLoadPolicyDocuments}
            icon={DOWNLOAD_GOLD}
            iconRight
            onClick={handleToDocumentsPage}
          />
        </BottomActionContainerStyle>
      </PolicyBtnsStyle>
    )
  } else {
    return (
      <PolicyBtnsStyle>
        <BottomActionContainerStyle className="btn-container" padding="10px">
          <ButtonWithIcon
            text={
              policy?.upcoming_instalment
                ? `${LANG_STRINGS.payInstalmentTo}-${policy?.upcoming_instalment?.serial_number}`
                : LANG_STRINGS.makePayment
            }
            icon={SEND_GOLD_ICON}
            iconRight
            onClick={
              grey
                ? onHandleWaitingPage
                : () => handleMakePayment(policy?.upcoming_instalment)
            }
            color={
              grey ? AgentColorPallette.white : AgentColorPallette.blackGrey
            }
            backgroundColor={grey ? AgentColorPallette.fontSemiGrey : ''}
          />
        </BottomActionContainerStyle>
        <NotificationContainer />
        <PaymentConfirmationModal
          confirmText={LANG_STRINGS.agentDoingPaymentConfirmation}
          showModal={paymentModalState.showConfirmationPopup}
          isLoader={agentPayingLoading}
          onClose={handleCloseModal}
          onAgree={handleAgreePayment}
        />
        {/* <ConfirmationModal
          showModal={modalState.showConfirmationModal}
          onClose={handlePaymentConfirm}
          agreeText={modalState.confirmModalAgree}
          confirmText={modalState.confirmModalText}
          modelTitle={modalState.confirmModalTitle}
          hideClose={!modalState.isPdfConfirm}
          onAgree={handlePaymentConfirm}
        /> */}
      </PolicyBtnsStyle>
    )
  }
}

export default withRouter(
  connect(
    (state) => ({
      agentPayingData: state.Policy.agentPayingData,
      agentPayingMsg: state.Policy.agentPayingMsg,
      getTaxSlabData: state.Policy.getTaxSlabData,
      taxSlabLoader: state.Loading.GET_TAX_SLAB,
      agentPayingError: state.Error.AGENT_PAYING,
      agentPayingLoading: state.Loading.AGENT_PAYING,
    }),
    {
      agentPayingRequest,
      getTaxSlabRequest,
      resetPolicyStore,
    }
  )(PolicyBtns)
)
