import BottomActionSheet from '../../../../../../../components/BottomActionSheet'
import { MVReviewTermsStyle } from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang/index'
import { Grid } from '../../../../../../../commonStyle/index.style'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { useState, useCallback } from 'react'
import Button from '../../../../../../../components/Button/index'
import ModifyTermsConditions from '../../../../../../../components/TermsCondition/components/ModifytTermsConditions/index'
import ShowSnackbar from '../../../../../../../components/ShowNotification/index'

function MVReviewTermsConditions ({ show, onClose, tncData, onAcceptClick = () => {} }) {
  const [termsAccept, setTermsAccept] = useState(false)
  const [showTerms, setShowTerms] = useState(false)

  const handleAcceptPayment = useCallback(() => {
    if (!termsAccept) {
      ShowSnackbar.error({
        visible: true, text: ERROR_LANG.pleaseAcceptTermCondition
      })
      return
    }
    onAcceptClick()
  }, [termsAccept, onAcceptClick])

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      showHeader
      title={LANG_STRINGS.agreementTermsNConditions}
      zIndex={3}
    >
      <MVReviewTermsStyle>
        <Grid
          gridColumn='24px 7fr'
          gridGap='1rem'
          align='center'
          className='terms-checkbox'
        >
          <CustomCheckbox
            isChecked={termsAccept}
            onChange={() => setTermsAccept(!termsAccept)}
            bgColor={AgentColorPallette.primary}
            color={AgentColorPallette.blackGrey}
          />
          <CustomText
            color={AgentColorPallette.blackGrey}
            size='0.8em'
          >
            Saya telah membaca dan menyetujui
            <span
              className='terms-actions-text'
              onClick={() => setShowTerms(!showTerms)}
            >&nbsp;Syarat dan Ketentuan PasarPolis Indonesia.
            </span>
          </CustomText>
        </Grid>
        {
          showTerms && (
            <Grid gridColumn='24px 7fr' gridGap='1rem' align='center'>
              <div />
              <div className='render-review-terms'>
                <div className='terms-border-top' />
                {
                  Array.isArray(tncData) ? tncData.map((term, index) => (
                    <p className='terms-font' key={index} dangerouslySetInnerHTML={{ __html: `${index + 1}. ${term}` }} />
                  )) : (
                    <ModifyTermsConditions data={tncData} />
                  )
                }
              </div>
            </Grid>
          )
        }
        <Button onClick={handleAcceptPayment}>
          {LANG_STRINGS.continue}
        </Button>
      </MVReviewTermsStyle>
    </BottomActionSheet>
  )
}

export default MVReviewTermsConditions
