import QuoteSection from '../QuoteSections'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { useMemo } from 'react'

function VehiclePhotSection ({ policy, className, onEditClick, isEdit }) {
  const vehiclePhotos = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.dashboard,
        type: 'img',
        value: policy?.images?.dashboard
      },
      {
        title: LANG_STRINGS.frontLook,
        type: 'img',
        value: policy?.images?.front
      },
      {
        title: LANG_STRINGS.toTheRightSide,
        type: 'img',
        value: policy?.images?.right
      },
      {
        title: LANG_STRINGS.leftSide,
        type: 'img',
        value: policy?.images?.left
      },
      {
        title: LANG_STRINGS.backView,
        type: 'img',
        value: policy?.images?.back
      }
    ]
  }, [policy])

  return (
    <div className={className}>
      <QuoteSection
        title={LANG_STRINGS.vehiclePhoto}
        data={vehiclePhotos}
        onEditClick={onEditClick}
        isEdit={isEdit}
      />
    </div>
  )
}

export default VehiclePhotSection
