import { useCallback, useMemo, useState } from 'react'
import { ARROW_DOWN_BLACK } from '../../../../../../../images'
import { formatDate } from '../../../../../../../helpers/formatDate'
import { StyleContainer } from './index.style'
import { LINE_COLORS, HeaderStatusIcon, StepStatusIcon } from './icons'
import { TrackerToggleButton, TrackerActionButton } from './TrackerButtons'

const TEST_ID = 'tracker-payment-status'

function connectorTone(step) {
  const v = step?.variant || 'neutral'
  const s = step?.state
  if (v === 'error') return 'error'
  if (v === 'warning') return 'warning'
  if (s === 'completed' && v === 'success') return 'success'
  if (s === 'current' || v === 'pending') return 'pending'
  if (s === 'completed') return 'success'
  return 'neutral'
}

function resolveStepVariant(step) {
  if (step.variant) return step.variant
  if (step.state === 'completed') return 'success'
  if (step.state === 'current') return 'pending'
  return 'neutral'
}

function TrackerPaymentStatus({ trackerData }) {
  const [expanded, setExpanded] = useState(() => trackerData?.default_expanded ?? false)

  const toggle = useCallback(() => {
    setExpanded((v) => !v)
  }, [])

  const sortedSteps = useMemo(() => {
    const steps = trackerData?.steps || []
    return [...steps].sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
  }, [trackerData?.steps])

  if (!trackerData) {
    return null
  }

  const sectionLabel = trackerData.section_label
  const currentStatusTitle = trackerData.current_status_title
  const headerVariant = trackerData.current_status_variant ?? 'pending'

  return (
    <StyleContainer data-testid={TEST_ID}>
      <TrackerToggleButton
        type="button"
        className="tracker-header"
        onClick={toggle}
        aria-expanded={expanded}
        data-testid={`${TEST_ID}-toggle`}
      >
        <div className="header-icon-wrap">
          <HeaderStatusIcon variant={headerVariant} />
        </div>
        <div className="header-text">
          {sectionLabel ? (
            <div className="section-label" data-testid={`${TEST_ID}-section-label`}>
              {sectionLabel}
            </div>
          ) : null}
          <div className="current-title" data-testid={`${TEST_ID}-current-title`}>
            {currentStatusTitle}
          </div>
        </div>
        <img
          className={`chevron ${expanded ? 'expanded' : ''}`}
          src={ARROW_DOWN_BLACK}
          alt=""
          aria-hidden
        />
      </TrackerToggleButton>

      <div className={`timeline ${expanded ? 'expanded' : ''}`} data-testid={`${TEST_ID}-timeline`}>
        {sortedSteps.length > 0 &&
          sortedSteps.map((step, idx) => {
            const isLast = idx === sortedSteps.length - 1
            const v = resolveStepVariant(step)
            const lineTone = connectorTone(step)
            const titleMuted = step.state === 'upcoming'
            const timeLabel = formatDate(step.occurred_at, 'DD/MM/YYYY, HH:mm:ss')

            return (
              <div className="step-row" key={idx} data-testid={`${TEST_ID}-step-${idx}`}>
                <div className="step-rail">
                  <div className="step-icon-slot">
                    <StepStatusIcon variant={v} state={step.state} />
                  </div>
                  {!isLast ? (
                    <div
                      className="connector"
                      style={{ background: LINE_COLORS[lineTone] || LINE_COLORS.neutral }}
                    />
                  ) : null}
                </div>
                <div className="step-body">
                  <div className={`step-title ${titleMuted ? 'is-muted' : ''}`}>{step.title}</div>
                  {timeLabel ? <div className="step-time">{timeLabel}</div> : null}
                  {step.actions?.length ? (
                    <div className="step-actions">
                      {step.actions.map((action, aidx) => (
                        <TrackerActionButton
                          key={action.label || aidx}
                          type="button"
                          className="step-action-link"
                          data-testid={`${TEST_ID}-action-${idx}-${aidx}`}
                          onClick={(e) => {
                            e.stopPropagation()
                          }}
                        >
                          {action.label}
                        </TrackerActionButton>
                      ))}
                    </div>
                  ) : null}
                </div>
              </div>
            )
          })}
      </div>
    </StyleContainer>
  )
}

export default TrackerPaymentStatus
