import { Component } from 'react'
import { connect } from 'react-redux'
import { isEmpty } from 'lodash/lang'
import { get } from 'lodash/object'
import Cookies from 'universal-cookie'
import { DetailWrapper } from '../../index.style'
import PolicyActions from '../../../../../redux/policy/action'
import { CustomText, Benefit } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PHOTO } from '../../../../../images'
import {
  formatMoney,
  validatePaymentTimeCounter,
} from '../../../../../helpers/utility'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import { LANG_STRINGS } from '../../../../../lang'
import { Row, DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import PdfContainer from '../../../../../components/PdfContainer'
import { PaylaterBadge } from '../../../../../components/ContentBox/index.style'
import { OFFLINE_PACKAGE_CODE } from '../../../../../constants/pkgCode'
import { withRouter } from 'react-router'
import PolicyBtns from '../../components/PolicyBtns'
import { IS_TRANSACTION_CHANGE } from '../../../../../constants/cookies'
import Transactions from '../../components/Transactions'
import TransactionHeader from '../../components/TransactionHeader'
import TransactionPaymentHeader from '../../components/TransactionPaymentHeader'
import PolicyTransactionInfo from '../../components/PolicyTransactionInfo'
import AgentCommissionPoint from '../../components/AgentCommissionPoint'
import PolicyInfoCard from '../../components/PolicyInfoCard'
import CustomerData from '../../components/CustomerData'
import MVInsuredInfo from '../../components/MVInsuredInfo'
import MVImgsInfo from '../../components/MVImgsInfo'
import MVAccessories from '../../components/MVAccessories'
import PolicyAddons from '../../components/PolicyAddons'
import InfoBar from '../../../../../components/InfoBar'
import PolicyPrintAddress from '../../components/PolicyPrintAddress'
import SurveyInfo from '../../components/SurveyCard'
import InsuranceInfoCard from '../../../../../components/InsuranceInfoCard'
import PolicyInfo from '../../../../../components/PolicyCancelledRejectionInfo'

const { getApplicationDetail, resetPolicyStore, getDownloadPdfRequest } =
  PolicyActions
const cookies = new Cookies()

class OfflineTransactionDetails extends Component {
  constructor(props) {
    super(props)
    this.state = {
      isValidateTime: true,
      isOfflinePolicy: false,
    }
    this.validityCheck = false

    this.hideTimerStates = ['ACTIVE', 'EXPIRED', 'COMPLETED', 'AGENT_PAID']
  }

  componentDidMount() {
    this.validityCheck = false
    if (cookies.get(IS_TRANSACTION_CHANGE) === 'true') {
      NotificationManager.success(LANG_STRINGS.transactionTypeHasBeenChange)
      cookies.remove(IS_TRANSACTION_CHANGE, {
        path: '/',
      })
    }
  }

  componentWillUnmount() {
    this.props.resetPolicyStore(['applicationDetail'])
    this.isValidateTime = false
  }

  componentWillReceiveProps(nextProps) {
    const {
      applicationDetail,
      agentPayingMsg,
      agentPayingData,
      resetPolicyStore,
    } = nextProps

    if (!this.validityCheck && applicationDetail.application_date) {
      this.validityCheck = true
      const isShowBtn = !this.hideTimerStates.includes(
        applicationDetail.payment_status
      )
      this.setState({
        isValidateTime:
          isShowBtn &&
          validatePaymentTimeCounter(applicationDetail.application_date),
      })
    }

    if (
      !this.state.isOfflinePolicy &&
      get(applicationDetail, 'product.package.code', '') ===
        OFFLINE_PACKAGE_CODE
    ) {
      this.setState({
        isOfflinePolicy: true,
      })
    }

    if (agentPayingMsg === 'success') {
      if (agentPayingData.transaction_id) {
        this.props.history.push({
          pathname: `/motor-vehicle/${agentPayingData.transaction_id}/agent/${applicationDetail.id}/payment`,
          state: {
            token: applicationDetail.id,
            transactionId: agentPayingData.transaction_id,
          },
        })
      }
      resetPolicyStore(['agentPayingMsg', 'agentPayingData'])
    }
  }

  isAllowedPaymentBtn = () => {
    if (this.props.applicationDetail) {
      return (
        !['PROVISIONAL_ISSUED'].includes(
          this.props.applicationDetail?.policy_status
        ) ||
        ['COMPLETED', 'PROOF_SUBMITTED'].includes(
          this.props.applicationDetail?.payment_status
        )
      )
    }
    return false
  }

  handleChangeTransaction = () => {
    // open change transaction Page
    this.props.history.push({
      pathname: `/transaction/type/${get(this.props, 'applicationDetail.id', '')}`,
    })
  }

  handleWaitingPage = () => {
    this.props.history.push({
      pathname: `/payment/status/paylater/${this.props.applicationDetail?.id}`,
    })
  }

  renderCardDetail = (
    heading,
    data,
    className,
    usePaylater,
    showTransactionType
  ) => {
    return (
      <div className={`detail-card ${className}`}>
        <CustomText
          className="item-padding"
          color={AgentColorPallette.black}
          weight={800}
          size="15px"
        >
          {heading}
        </CustomText>
        {usePaylater && <PaylaterBadge>{LANG_STRINGS.paylater}</PaylaterBadge>}
        <hr className="margin-0" />
        {data.map((item, index) => {
          if (item.value === 'mitraNotAvilable') return null
          return (
            <div key={index}>
              <Row className="item-padding" justify="space-between">
                <CustomText
                  size="13px"
                  className="width-50"
                  color={AgentColorPallette.fontDarkerGrey}
                >
                  {item.head}
                </CustomText>
                <div className="width-50">
                  {item.head === 'Manfaat' ? (
                    <div className="detail-container width-50">
                      <Benefit benefitData={item.value} />
                    </div>
                  ) : (
                    this.getValueContainer(item)
                  )}
                </div>
              </Row>
              <hr className="margin-0" />
            </div>
          )
        })}
        {showTransactionType && (
          <Row
            className="transaction-container"
            align="center"
            justify="space-between"
            onClick={this.handleChangeTransaction}
          >
            <div>
              <CustomText color={AgentColorPallette.fontSemiGrey}>
                {LANG_STRINGS.transactionType}
              </CustomText>
              <CustomText size="10px" color={AgentColorPallette.fontSemiGrey}>
                {LANG_STRINGS.youCanChangeTheTypeOfTransaction}
              </CustomText>
            </div>
            <Row className="transaction-type" justify="space-between">
              {this.getValueContainer({ value: 'Normal' })}
              <i className="fas fa-angle-right" />
            </Row>
          </Row>
        )}
      </div>
    )
  }

  getValueContainer = (item = {}) => {
    if (item.type === 'img') {
      return item.value ? (
        <SingleImgContainer
          imgUrl={item.value}
          imgClassName="single-img-margin"
        />
      ) : (
        this.getNoImgContainer('single-img-margin')
      )
    }

    return (
      <CustomText
        textAlign="right"
        color={item.color || AgentColorPallette.regular}
        weight={800}
      >
        {item.value || '-'}
      </CustomText>
    )
  }

  renderCard = (image, heading, value) => (
    <div className="card">
      <img src={image} width={28} alt="card-img" />
      <CustomText
        color={AgentColorPallette.fontSemiGrey}
        textAlign="center"
        size="10px"
      >
        {heading}
      </CustomText>
      <CustomText
        color={AgentColorPallette.black}
        size="14px"
        textAlign="center"
        weight={700}
      >
        {value}
      </CustomText>
    </div>
  )

  renderHeader = (head) => {
    return (
      <CustomText
        color={AgentColorPallette.black}
        size="16px"
        weight={800}
        bottom="0"
        className="item-padding"
      >
        {head}
      </CustomText>
    )
  }

  getNoImgContainer = (widthClass) => {
    return (
      <DisplayFlexCCC className={`no-img ${widthClass}`}>
        <img alt="dashboard-img" src={PHOTO} className="uploaded-image" />
      </DisplayFlexCCC>
    )
  }

  renderPdfContainer = (url, headerTitle, title) => {
    const isCertificate = !!url
    return (
      <div className={`detail-card ${!isCertificate && 'border-red'}`}>
        {this.renderHeader(headerTitle)}
        <hr className="margin-0" />
        <div className="item-padding">
          <CustomText color={AgentColorPallette.black} size="15px">
            {title}
          </CustomText>
          {isCertificate ? (
            <PdfContainer url={url} />
          ) : (
            this.getNoImgContainer()
          )}
        </div>
      </div>
    )
  }

  render() {
    const { applicationDetail = {}, history, isStaffAgent } = this.props
    const {
      policy_detail: policyDetail = {},
      status,
      product = {},
    } = applicationDetail
    const { isOfflinePolicy } = this.state

    const isShowKTPSTNKAddress = status === 'QUOTATION'
    const isGrossPremiumChanged = get(
      applicationDetail,
      'is_gross_premium_changed',
      false
    )
    const oldCertificateUrl = policyDetail.old_policy_certificate_urls || []
    const isBulkCommssion = applicationDetail?.is_bulk_business

    return (
      <>
        {!isEmpty(applicationDetail) && (
          <DetailWrapper>
            <PolicyInfo
              remarks={
                applicationDetail?.insurance_details?.remark_details || {}
              }
              status={applicationDetail?.policy_status || ''}
            />
            <TransactionPaymentHeader policy={applicationDetail} />
            <TransactionHeader policy={applicationDetail} />
            <div className="detail-body">
              {!isStaffAgent && !isBulkCommssion && (
                <AgentCommissionPoint
                  commission={get(applicationDetail, 'agent_commission', 0)}
                  points={get(applicationDetail, 'agent_points', 0)}
                  paymentBy={get(applicationDetail, 'payment_by', 0)}
                />
              )}
              <div className="info-card-container">
                <InsuranceInfoCard
                  isShowDisclaimer
                  tnc={get(applicationDetail, 'product.tnc.data', [])}
                  benefit={get(
                    applicationDetail,
                    'product.benefit.data[0].description',
                    ''
                  )}
                  claims={get(
                    applicationDetail,
                    'product.claims.description',
                    ''
                  )}
                />
              </div>
              {isGrossPremiumChanged && (
                <InfoBar
                  text={
                    LANG_STRINGS.changeInCommissionsAndPointsAfterEndorsement
                  }
                />
              )}

              <Transactions
                policy={applicationDetail}
                isOfflinePolicy={isOfflinePolicy}
              />
              <PolicyTransactionInfo
                policy={applicationDetail}
                history={history}
              />
              {!isOfflinePolicy && (
                <>
                  <PolicyInfoCard
                    policy={applicationDetail}
                    history={history}
                  />
                  <CustomerData policy={applicationDetail} />
                  {!isOfflinePolicy &&
                    !product.photo_required &&
                    this.renderPdfContainer(
                      policyDetail.previous_certificate_url ||
                        oldCertificateUrl[0]?.url,
                      LANG_STRINGS.policyCertificate,
                      LANG_STRINGS.policyCertificate
                    )}
                  {policyDetail.appointment_letter_url &&
                    this.renderPdfContainer(
                      policyDetail.appointment_letter_url,
                      LANG_STRINGS.otherDocuments,
                      LANG_STRINGS.letterOfAppointment
                    )}
                  <MVInsuredInfo
                    isShowKTPSTNKAddress={isShowKTPSTNKAddress}
                    policy={applicationDetail}
                  />
                  {product.photo_required && (
                    <MVImgsInfo policy={applicationDetail} />
                  )}
                  {!!get(
                    applicationDetail,
                    'policy_detail.accessories.length',
                    0
                  ) && <MVAccessories policy={applicationDetail} />}
                </>
              )}
              <>
                <PolicyPrintAddress
                  history={history}
                  policy={applicationDetail}
                />
                {applicationDetail?.survey_response && (
                  <SurveyInfo policy={applicationDetail} />
                )}

                {!isOfflinePolicy && (
                  <PolicyAddons policy={applicationDetail} />
                )}
                {!isOfflinePolicy &&
                  !!get(
                    applicationDetail,
                    'policy_detail.additional_sum_insured',
                    0
                  ) &&
                  this.renderCardDetail(LANG_STRINGS.thirdPartyLegal, [
                    {
                      head: 'Jumlah Tambahan Pertanggungan',
                      value: formatMoney(
                        applicationDetail.policy_detail.additional_sum_insured,
                        0
                      ),
                    },
                  ])}
              </>
            </div>
            <PolicyBtns
              policy={applicationDetail}
              isOfflinePolicy={isOfflinePolicy}
              grey={this.isAllowedPaymentBtn()}
              onHandleWaitingPage={this.handleWaitingPage}
            />
          </DetailWrapper>
        )}
        <NotificationContainer />
      </>
    )
  }
}

export default withRouter(
  connect(
    (state) => ({
      agentDetails: state.User.agentDetails,
      isStaffAgent: state.User.isStaffAgent,
      applicationDetail: state.Policy.applicationDetail,
      agentPayingData: state.Policy.agentPayingData,
      agentPayingMsg: state.Policy.agentPayingMsg,
      agentPayingError: state.Error.AGENT_PAYING,
      agentPayingLoading: state.Loading.AGENT_PAYING,
      applicationDetailLoading: state.Loading.GET_APPLICATION_DETAIL,
      pdfDownloadLoading: state.Loading.GET_DOWNLOAD_PDF,
    }),
    {
      getApplicationDetail,
      getDownloadPdfRequest,
      resetPolicyStore,
    }
  )(OfflineTransactionDetails)
)
